-- TerraLens place seed: real places with real coordinates.
--
-- Every row is a Wikidata item that has coordinates (P625), a country (P17) and an
-- English Wikipedia article. The description is that article's opening sentences.
-- Nothing here is invented: no fee, season or access detail is guessed, so those
-- fields carry an honest "check locally" default for the admin to fill in.
--
-- The data is passed as JSON inside dollar-quoting, so apostrophes in place names and
-- descriptions cannot break the statement.
--
-- Safe to re-run: rows whose slug already exists are skipped.

-- batch 1 of 6: 150 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Mount Shuksan Waterfalls","slug":"mount-shuksan-waterfalls","category":"Waterfall","country":"United States","region":"Whatcom County","city":null,"latitude":48.81389,"longitude":-121.56389,"description":"There are four prominent waterfalls in the basin of a short tributary of Sulphide Creek, on the southeast flank of 9,127-foot (2,781m) Mount Shuksan in North Cascades National Park, Washington. Seahpo Peak Falls and Cloudcap Falls, the taller two of the three, are located on separate streams that converge and plunge over Rockflow Canyon Falls."},{"name":"Sulphide Creek Falls","slug":"sulphide-creek-falls","category":"Waterfall","country":"United States","region":"Washington","city":null,"latitude":48.7965,"longitude":-121.576,"description":"Sulphide Creek Falls is a tall, moderately large volume waterfall within North Cascades National Park in Washington state that is one of the tallest waterfalls in North America. The falls drop from Sulphide Lake on the southeast side of Mount Shuksan down a narrow flume-like canyon to a broad basin below."},{"name":"Bear Creek Falls","slug":"bear-creek-falls","category":"Waterfall","country":"United States","region":"Washington","city":null,"latitude":47.8926,"longitude":-121.382,"description":"Bear Creek Falls is the final of the two waterfalls on the North Fork Skykomish River in the U.S. state of Washington. The falls are located within a short, narrow canyon."},{"name":"Promontory Falls","slug":"promontory-falls","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.1959,"longitude":-79.6449,"description":"The city of Hamilton in Ontario, Canada is home to more than 100 waterfalls and cascades, most of which are on or near the Bruce Trail as it winds through the Niagara Escarpment. Ontario's internationally recognized Niagara Escarpment provides perfect geological conditions for waterfalls to occur, from Tobermory to Niagara Falls."},{"name":"Sliding Rock","slug":"sliding-rock","category":"Waterfall","country":"United States","region":"North Carolina","city":null,"latitude":35.31102,"longitude":-82.78725,"description":"Sliding Rock is a waterfall in Western North Carolina, located near Brevard, so named because visitors can slide all the way down the waterfall into the plunge pool below. The plunge pool is around 8 feet deep in the middle, with a strong churning river current, so users must be able to swim or wear a life vest. The water in the river and the plunge pool remains near 55 degrees Fahrenheit year round."},{"name":"Humboldt Falls","slug":"humboldt-falls","category":"Waterfall","country":"New Zealand","region":"Southland District","city":null,"latitude":-44.69726,"longitude":168.13502,"description":"Humboldt Falls is a waterfall located in the Hollyford Valley in the Fiordland district of New Zealand. They fall 275 metres in three drops; the largest of the three drops is 134 metres high."},{"name":"Weir's Falls","slug":"weirs-falls","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.2632,"longitude":-80.0121,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Lower Fruitland Falls","slug":"lower-fruitland-falls","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.20639,"longitude":-79.70611,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Keoti Falls","slug":"keoti-falls","category":"Waterfall","country":"India","region":"Rewa District","city":null,"latitude":24.816,"longitude":81.453,"description":"Keoti Falls is in Rewa district in the Indian state of Madhya Pradesh. It is the 24th highest waterfall in India."},{"name":"Bahia Falls","slug":"bahia-falls","category":"Waterfall","country":"Brazil","region":null,"city":null,"latitude":-19.236,"longitude":-43.218,"description":"Bahia Falls is a waterfall on the Santo Antônio River, in city of Santo Antônio do Rio Abaixo, in the state of Minas Gerais in Brazil. It has about 4 m (13 ft) of height."},{"name":"Chuvisco Falls","slug":"chuvisco-falls","category":"Waterfall","country":"Brazil","region":"Mato Grosso","city":null,"latitude":-19.2861,"longitude":-43.2569,"description":"Chuvisco Falls is a waterfall on the Rio Preto in Minas Gerais, Brazil, on the boundary between the municipalities of Santo Antônio do Rio Abaixo and São Sebastião do Rio Preto, about 170 kilometres (110 mi) east of Belo Horizonte. The falls have a drop of about 10 metres (33 ft) and are surrounded by dense forest."},{"name":"Kattimannap Qurlua","slug":"kattimannap-qurlua","category":"Waterfall","country":"Canada","region":"Nunavut","city":null,"latitude":67.096,"longitude":-108.799,"description":"Kattimannap Qurlua, formerly Wilberforce Falls, is an almost 60 metres (200 ft) tall waterfall located in the Wilberforce Gorge of the Hood River in Nunavut, Canada. The falls are one of the few major waterfalls in the North America mainland north of the Arctic Circle."},{"name":"Amicalola Falls","slug":"amicalola-falls","category":"Waterfall","country":"United States","region":"Georgia","city":null,"latitude":34.56398,"longitude":-84.23964,"description":"Amicalola Falls is a 729-foot waterfall on Amicalola Creek in Dawson County, Georgia, United States. It is the highest waterfall in Georgia and is considered to be one of the Seven Natural Wonders of Georgia. The name \"Amicalola\" is derived from a Cherokee language term ama uqwalelvyi, meaning \"tumbling waters.\" The falls are the centerpiece of Amicalola Falls State Park."},{"name":"Tarawera Falls","slug":"tarawera-falls","category":"Waterfall","country":"New Zealand","region":"Bay of Plenty Region","city":null,"latitude":-38.163,"longitude":176.52,"description":"Tarawera Falls is a 65 m (213 ft) high waterfall on the Tarawera River in the Bay of Plenty region in New Zealand's North Island."},{"name":"Horsetail Falls","slug":"horsetail-falls","category":"Waterfall","country":"United States","region":"Multnomah County","city":null,"latitude":45.5894,"longitude":-122.068,"description":"Horsetail Falls is a waterfall located on Horsetail Creek along the Columbia River Gorge in Multnomah County, in the U.S. state of Oregon. The falls drop over a cut over the columnar basalt cliff within the Oneonta Gorge. It is one of the waterfalls along the Columbia River Highway's waterfall corridor."},{"name":"Cotter Force","slug":"cotter-force","category":"Waterfall","country":"United Kingdom","region":"High Abbotside","city":null,"latitude":54.31778,"longitude":-2.23333,"description":"Cotter Force is a small waterfall on Cotterdale Beck, a minor tributary of the River Ure, near the mouth of Cotterdale, a side dale in Wensleydale, North Yorkshire, England."},{"name":"Falls of Foyers","slug":"falls-of-foyers","category":"Waterfall","country":"United Kingdom","region":"Highland","city":null,"latitude":57.24862,"longitude":-4.49269,"description":"The Falls of Foyers are two waterfalls on the River Foyers, which feeds Loch Ness, in Highland, Scotland. They are located on the lower portion of the River Foyers, and consist of the upper falls, with a drop of 46 feet (14 m) and the lower falls, which drop 98 feet (30 m). The River Foyers flows into Loch Ness on the south-eastern shore about half-way along its length, where the village of Foyers is sited."},{"name":"Pistyll y Llyn","slug":"pistyll-y-llyn","category":"Waterfall","country":"United Kingdom","region":"Cadfarch","city":null,"latitude":52.53137,"longitude":-3.83842,"description":"Pistyll y Llyn is one of the tallest waterfalls in Wales and the United Kingdom. It is a horsetail style set of falls which are located in the Cambrian Mountains about 2+1⁄2 miles from Glaspwll in Powys, Wales."},{"name":"Grey Mare's Tail","slug":"grey-mares-tail","category":"Waterfall","country":"United Kingdom","region":"Dumfries and Galloway","city":null,"latitude":55.42118,"longitude":-3.29154,"description":"Grey Mare's Tail is a 60-metre (200 ft) hanging valley waterfall near to Moffat in southern Scotland. The fall is produced by the Tail Burn flowing from Loch Skeen cascading into the Moffat Water in the lower valley below."},{"name":"Janet's Foss","slug":"janets-foss","category":"Waterfall","country":"United Kingdom","region":"Malham","city":null,"latitude":54.06573,"longitude":-2.13635,"description":"Janet's Foss is a small waterfall near the village of Malham, North Yorkshire, England. It carries Gordale Beck over a limestone outcrop topped by tufa into a deep pool below. The pool was traditionally used for sheep dipping, an event which drew in local village inhabitants for the social occasion."},{"name":"Sydney Falls","slug":"sydney-falls","category":"Waterfall","country":"United States","region":"Pierce County","city":null,"latitude":46.8403,"longitude":-121.559,"description":"Sydney Falls, more commonly called Kotsuck Creek Falls or Kotsuck Falls, is a waterfall in the Mount Rainier National Park in the U.S. state of Washington."},{"name":"Kautz Creek Falls","slug":"kautz-creek-falls","category":"Waterfall","country":"United States","region":"Pierce County","city":null,"latitude":46.8104,"longitude":-121.781,"description":"Kautz Creek Falls is a waterfall on Kautz Creek in the Mount Rainier National Park in the state of Washington. It was formed when the Kautz Glacier retreated in the last 50 years, creating a series of long and slender cascades totaling about 400 feet (120 m) in height down a tall glacial cliff, with a highest drop of 150 feet (46 m). The falls consist of two parts, each with two distinct tiers."},{"name":"Van Trump Falls","slug":"van-trump-falls","category":"Waterfall","country":"United States","region":"Pierce County","city":null,"latitude":46.7922,"longitude":-121.782,"description":"Van Trump Falls is a waterfall on Van Trump Creek in Pierce County, Washington. The falls are located a short distance downstream from the mouth of Falls Creek."},{"name":"Bow Falls","slug":"bow-falls","category":"Waterfall","country":"Canada","region":"Alberta","city":null,"latitude":51.16797,"longitude":-115.56149,"description":"Bow Falls is a major waterfall on the Bow River, Alberta just before the junction of it and the Spray River. They are located near the Banff Springs Hotel and golf course on the left-hand side of River Road."},{"name":"Comet Falls","slug":"comet-falls","category":"Waterfall","country":"United States","region":"Pierce County","city":null,"latitude":46.7958,"longitude":-121.78,"description":"Comet Falls is a tall waterfall located on Van Trump Creek in Pierce County, Washington. The falls are thought to be the best in the Mount Rainier region."},{"name":"Teviot Falls","slug":"teviot-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.23283,"longitude":152.48583,"description":"The Teviot Falls is a plunge waterfall on Teviot Brook in Carneys Creek, Scenic Rim Region, Queensland, Australia."},{"name":"Daggs Falls","slug":"daggs-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.3405,"longitude":152.34587,"description":"The Daggs Falls is a plunge waterfall on Spring Creek that is located in the Darling Downs region of Queensland, Australia."},{"name":"Kearneys Falls","slug":"kearneys-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-17.24099,"longitude":145.7781,"description":"The Kearneys Falls is a cascade waterfall on a tributary of the Mulgrave River, in the Wooroonooran National Park, in the Goldsborough Valley of Far North region of Queensland, Australia."},{"name":"Goomoolahra Falls","slug":"goomoolahra-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.22277,"longitude":153.2849,"description":"The Bilbrough Falls, also known as the Goomoolahra Falls, is a cascade waterfall that is located within the Springbrook National Park in the South East region of Queensland, Australia."},{"name":"Herbert River Falls","slug":"herbert-river-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-18.23375,"longitude":145.36989,"description":"The Herbert River Falls is a plunge waterfall on the Herbert River that is located in the UNESCO World Heritage–listed Wet Tropics in the Far North region of Queensland, Australia."},{"name":"Kiliyur Falls","slug":"kiliyur-falls","category":"Waterfall","country":"India","region":"Yercaud","city":null,"latitude":11.76667,"longitude":78.23333,"description":"Kiliyur Falls is a waterfall on the Periyaaru river in the Servarayan hill range in the Eastern Ghats, Tamil Nadu, India. The waters overflowing the Yercaud Lake fall 91 m (300 ft) into the Kiliyur Valley. People need to walk down 200–250 steep steps from the nearest road to reach this waterfall."},{"name":"Unchalli Falls","slug":"unchalli-falls","category":"Waterfall","country":"India","region":"Uttara Kannada District","city":null,"latitude":14.40944,"longitude":74.7475,"description":"Unchalli Falls, also known as Lushington Falls, is a waterfall created by a 116-metre (381 ft) drop in the River Aghanashini in Karnataka, India. The falls are located 35 km (22 mi) from Sirsi. The falls were named for J. D. Lushington, a District Collector for the British Government, who discovered the falls in 1845. It is one of world's five waterfalls where one can witness the extremely rare phenomena \"Moonbows\"."},{"name":"Hebbe Falls","slug":"hebbe-falls","category":"Waterfall","country":"India","region":"Kemmangundi","city":null,"latitude":13.54139,"longitude":75.725,"description":"Hebbe Falls is situated at 13°32′29″N 75°43′30″E about 10 km away from the hill station Kemmangundi in Karnataka, India. The waterfall is inside a coffee estate. Hebbe Falls gushes from a height of 551 ft in two stages to form Dodda Hebbe and Chikka Hebbe"},{"name":"Browne Falls","slug":"browne-falls","category":"Waterfall","country":"New Zealand","region":"Southland Region","city":null,"latitude":-45.39935,"longitude":167.0858,"description":"Browne Falls is a waterfall above Doubtful Sound, which is located in Fiordland National Park, New Zealand. In a temperate rain forest, the falls cascade down to the fiord near Hall Arm. Heights of 619 metres and 836 metres have been given for the falls. Their source is a tarn called Lake Browne which when full, overflows down the side of the mountain face."},{"name":"Jonha Falls","slug":"jonha-falls","category":"Waterfall","country":"India","region":"Ranchi district","city":null,"latitude":23.34167,"longitude":85.60833,"description":"The Jonha Falls is a waterfall located in Ranchi district in the Indian state of Jharkhand. The best way to reach water fall without using 722 steps is through the Jonha Fall Resort Road."},{"name":"Agaya Gangai","slug":"agaya-gangai","category":"Waterfall","country":"India","region":"Tamil Nadu","city":null,"latitude":11.26694,"longitude":78.39389,"description":"Agaya Gangai is a waterfall located in Kolli Hills of the Eastern Ghats, in Namakkal district, Tamil Nadu, India. It falls from a height of 300 feet (91 m) and is formed by the Aiyaru river. Agaya Gangai is also known as Peraruvi and can be reached by climbing down 1196 steps. The caves of sages Bogar, Agastyar, Korakkar and Kalangi Nathar are located near the waterfalls inside the forest."},{"name":"Kumbakkarai Falls","slug":"kumbakkarai-falls","category":"Waterfall","country":"India","region":"Tamil Nadu","city":null,"latitude":10.18,"longitude":77.53056,"description":"Kumbakkarai Falls are lesser known falls in the foothills of the Kodaikanal Hills. They are located at 10°10′48″N 77°31′50″E in Theni district, 9 kilometers (5.6 mi) from Periyakulam. Kumbakkarai Falls are located along the Kodai-Vellagavi-Periyakulam footpath."},{"name":"Karlovsko Praskalo","slug":"karlovsko-praskalo","category":"Waterfall","country":"Bulgaria","region":"Plovdiv","city":null,"latitude":42.71,"longitude":24.85306,"description":"Karlovsko Praskalo is a waterfall in the Central Balkan National Park, Balkan Mountains, central Bulgaria. It is located at 1,450 m altitude in the southern slope of the Zhaltets Peak. The waterfall is 30 m high. Karlovsko Praskalo and the surrounding area was declared a natural landmark in 1965."},{"name":"Etropole waterfall “Varovitets”","slug":"etropole-waterfall-varovitets","category":"Waterfall","country":"Bulgaria","region":"Sofia Oblast","city":null,"latitude":42.82426,"longitude":24.03888,"description":"Etropole Waterfall, known also as Varovitets (Варовитец) is a waterfall in the Balkan Mountains, Bulgaria, located near the Etropole Monastery. It is situated on the Malki Iskar River, which flows near the monastery. The drop from the waterfall is roughly 15 meters(49.2 feet)."},{"name":"Volio Waterfall","slug":"volio-waterfall","category":"Waterfall","country":"Costa Rica","region":"Bribri","city":null,"latitude":9.64444,"longitude":-82.87028,"description":"The Volio Waterfall is located near the town of Bribri, Costa Rica in Limón Province. It is located within the Bribri Indian Reservation. Many tour companies offer visits to the waterfall. There is a moderate hike to reach the waterfall, which is located in the Talamancan montane forests. A large pool is located at the bottom of the falls and is popular with locals and tourists alike."},{"name":"Cristal Falls","slug":"cristal-falls","category":"Waterfall","country":"Brazil","region":null,"city":null,"latitude":-19.206,"longitude":-43.242,"description":"Cristal Falls is a waterfall in the Cristal Mountains of Brazil. It is located in the city of Santo Antônio do Rio Abaixo in the state of Minas Gerais. It is approximately 20 m (66 ft) high."},{"name":"Kaieteur Falls","slug":"kaieteur-falls","category":"Waterfall","country":"Guyana","region":"Potaro-Siparuni","city":null,"latitude":5.17811,"longitude":-59.48228,"description":"Kaieteur Falls is one of the most powerful single-drop waterfalls in the world. It is located on the Potaro River in Kaieteur National Park, central Essequibo Territory, Guyana. It is 226 metres (741 ft) high when measured from its plunge over a sandstone and conglomerate cliff to the first break."},{"name":"Trümmelbach Falls","slug":"tr-mmelbach-falls","category":"Waterfall","country":"Switzerland","region":"Canton of Berne","city":null,"latitude":46.56907,"longitude":7.91498,"description":"Trümmelbach Falls are a series of ten waterfalls within a mountain in the Lauterbrunnen Valley of the Bernese Oberland in Switzerland. The stream is fed by meltwater from glaciers on the flanks of the Eiger, Mönch and Jungfrau and descends about 140 metres through the mountain."},{"name":"Jōren Falls","slug":"j-ren-falls","category":"Waterfall","country":"Japan","region":"Izu","city":null,"latitude":34.87181,"longitude":138.92214,"description":"Jōren Falls is a waterfall in the Yugashima district of Izu city, Shizuoka Prefecture, Japan, in central Izu Peninsula, in the upper reaches of the Kano River. It is a Shizuoka Prefectural Natural Monument. It is one of \"Japan’s Top 100 Waterfalls\", in a listing published by the Japanese Ministry of the Environment in 1990."},{"name":"Otodome Falls","slug":"otodome-falls","category":"Waterfall","country":"Japan","region":"Shizuoka Prefecture","city":null,"latitude":35.31222,"longitude":138.58917,"description":"Otodome Falls is a waterfall in Fujinomiya, Shizuoka Prefecture, near Mount Fuji, Japan. This waterfall with a height of 25 m (82 ft) is part of the Fuji-Hakone-Izu National Park. Another waterfall, the Shiraito Falls is about a five-minute walk away."},{"name":"Shasui Falls","slug":"shasui-falls","category":"Waterfall","country":"Japan","region":"Kanagawa Prefecture","city":null,"latitude":35.3525,"longitude":139.06167,"description":"Shasui Falls is a waterfall on the Tanzawa River in Yamakita, Ashigarakami District, Kanagawa Prefecture, Japan."},{"name":"Khone Phapheng Falls","slug":"khone-phapheng-falls","category":"Waterfall","country":"Laos","region":"Champasak Province","city":null,"latitude":13.95972,"longitude":105.98667,"description":"The Khone Falls and Pha Pheng Falls together form a waterfall located in Champasak Province on the Mekong River in southern Laos, near the border with Cambodia. It is the widest waterfall in the world at 10,783 metres in width from one edge of its multiple channels to the other."},{"name":"Dhuandhar Falls","slug":"dhuandhar-falls","category":"Waterfall","country":"India","region":"Jabalpur district","city":null,"latitude":23.125,"longitude":79.813,"description":"The Dhuandhar Falls (धुआंधार) is a waterfall in Jabalpur district in the Indian state of Madhya Pradesh."},{"name":"Sanaghagara Waterfall","slug":"sanaghagara-waterfall","category":"Waterfall","country":"India","region":"Kendujhar district","city":null,"latitude":21.63279,"longitude":85.55688,"description":"The Sanaghagara Waterfall is a waterfall located in the Kendujhar district in the Indian state of Odisha. It is located 3 kilometers upstream of Badaghagara Waterfall, also in Kendujhar."},{"name":"Khandadhar Falls, Sundagarh","slug":"khandadhar-falls-sundagarh","category":"Waterfall","country":"India","region":null,"city":null,"latitude":21.76129,"longitude":85.11721,"description":"The Khandadhar Falls is located in Nandapani, Bonaigarh in the Sundargarh district on the Indian state of Odisha. It is the 9th highest waterfall in India and the second highest in Odisha after Barehipani Falls in Mayurbhanj."},{"name":"Thusharagiri Falls","slug":"thusharagiri-falls","category":"Waterfall","country":"India","region":"Kozhikode district","city":null,"latitude":11.47289,"longitude":76.05417,"description":"Thusharagiri Falls is a waterfall located in Kozhikode district in the Indian state of Kerala, India."},{"name":"Suruli Falls","slug":"suruli-falls","category":"Waterfall","country":"India","region":"Theni district","city":null,"latitude":9.66444,"longitude":77.30333,"description":"Suruli falls, is located 56 km (35 mi) from Theni and 10 km (6.2 mi) from Cumbum in the Theni District in Tamil Nadu, India. It is a 2 stage Cascading water fall. The Suruli River supplying the falls originates from the Meghamalai mountain range. The falls drop from a height of 150 feet (46 m) gathers into a pool, flows for a short distance and again plummets an additional 40 feet (12 m)."},{"name":"Kutladampatti Falls","slug":"kutladampatti-falls","category":"Waterfall","country":"India","region":"Madurai district","city":null,"latitude":10.131,"longitude":78.017,"description":"Kutladampatti Falls is a waterfall located in the village of Kutladampatti near Vadipatti in Madurai district about 30 km (19 mi) northwest of Madurai, Tamil Nadu, India. The waterfall is in a reserve forest managed by the Tamil Nadu Forest Department. The water falls from a height of about 27 metres (89 ft)."},{"name":"Pykara","slug":"pykara","category":"Waterfall","country":"India","region":"Tamil Nadu","city":null,"latitude":11.45472,"longitude":76.59722,"description":"The Pykara is a river 19 kilometres (12 mi) from Ooty in the Indian State of Tamil Nadu with a village by the same name nearby. The Pykara River is considered very sacred by the Todas. It rises at Mukurthi peak, flows northwards, and then turns to the west after reaching the edge of the plateau. The river flows through Mukurthi, Pykara and Glenmorgan dams, and forms part of an important hydro-electric power project."},{"name":"Pilj Waterfall","slug":"pilj-waterfall","category":"Waterfall","country":"Serbia","region":null,"city":null,"latitude":43.3265,"longitude":22.72164,"description":"Pilj Waterfall, or simply Pilj, is the third-highest waterfall in Serbia. It was discovered by geologists and alpinists only in 2002."},{"name":"Namtok Si Dit","slug":"namtok-si-dit","category":"Waterfall","country":"Thailand","region":"Nong Mae Na","city":null,"latitude":16.62889,"longitude":100.93861,"description":"Namtok Si Dit is a waterfall and tourist attraction in Thailand. The waterfall is on the Wang Thong River and it runs throughout the year. At the falls, there is a rice mortar using power generated from the waterfall, built by the Communist Party of Thailand."},{"name":"Mantayupan Falls","slug":"mantayupan-falls","category":"Waterfall","country":"Philippines","region":"Barili","city":null,"latitude":10.10653,"longitude":123.521,"description":"Barili, officially the Municipality of Barili, is a municipality in the province of Cebu, Philippines. According to the 2024 census, it has a population of 82,427 people."},{"name":"Gibbon Falls","slug":"gibbon-falls","category":"Waterfall","country":"United States","region":"Wyoming","city":null,"latitude":44.65402,"longitude":-110.77075,"description":"Gibbon Falls is a waterfall on the Gibbon River in northwestern Yellowstone National Park in the United States. Gibbon Falls has a drop of approximately 84 feet (26 m). The falls are located roadside, 4.7 miles (7.6 km) upstream from the confluence of the Gibbon and Firehole Rivers at Madison Junction on the Grand Loop Road."},{"name":"Howick Falls","slug":"howick-falls","category":"Waterfall","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-29.48667,"longitude":30.28972,"description":"Howick Falls is a waterfall in Howick, KwaZulu-Natal Province, South Africa. The waterfall is approximately 95 m in height (310 feet) and lies on the Umgeni River. The Zulu people called the falls KwaNogqaza, which means \"Place of the Tall One\"."},{"name":"Morans Falls","slug":"morans-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.23056,"longitude":153.12472,"description":"The Morans Falls, a plunge waterfall on Morans Creek, is located in the UNESCO World Heritage–listed Gondwana Rainforests in the South East region of Queensland, Australia."},{"name":"Barron Falls","slug":"barron-falls","category":"Waterfall","country":"Australia","region":"Shire of Mareeba","city":null,"latitude":-16.83444,"longitude":145.64361,"description":"Barron Falls is a steep tiered cascade waterfall in Kuranda, Shire of Mareeba, Queensland, Australia. The falls are created by the Barron River descending from the Atherton Tablelands to the Cairns coastal plain."},{"name":"Murray Falls","slug":"murray-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-18.15227,"longitude":145.81585,"description":"The Murray Falls, a cascade waterfall on the Murray River, is located in the UNESCO World Heritage–listed Wet Tropics in Murray Upper, Cassowary Coast Region in the Far North region of Queensland, Australia."},{"name":"Florence Falls","slug":"florence-falls","category":"Waterfall","country":"Australia","region":"Northern Territory","city":null,"latitude":-13.0992,"longitude":130.783,"description":"Florence Falls is a segmented waterfall on the Florence Creek located within Litchfield National Park in the Northern Territory of Australia."},{"name":"Surprise Creek Falls","slug":"surprise-creek-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-18.17358,"longitude":145.60284,"description":"The Surprise Creek Falls, a segmented waterfall on the Surprise Creek, is located in the UNESCO World Heritage–listed Wet Tropics in the Far North region of Queensland, Australia."},{"name":"Wannon Falls","slug":"wannon-falls","category":"Waterfall","country":"Australia","region":"Victoria","city":null,"latitude":-37.67626,"longitude":141.84083,"description":"The Wannon Falls are a punchbowl waterfall located in the Southern Grampians Shire, approximately 19 kilometres (12 mi) west of Hamilton, in western Victoria, Australia. The falls are fed by the Wannon River that has its head waters in the Grampians mountains."},{"name":"Dinner Falls","slug":"dinner-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-17.42634,"longitude":145.48834,"description":"The Dinner Falls is a mix of three waterfalls that display plunge, segmented and cascade characteristics on the upper Barron River located in the Far North region of Queensland, Australia."},{"name":"Elabana Falls","slug":"elabana-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.24329,"longitude":153.15298,"description":"The Elabana Falls is a cascade waterfall that is located within Lamington National Park in the South East region of Queensland, Australia."},{"name":"Ebor Falls","slug":"ebor-falls","category":"Waterfall","country":"Australia","region":"New South Wales","city":null,"latitude":-30.40229,"longitude":152.34158,"description":"Ebor Falls is a tiered waterfall on the Guy Fawkes River, located near Ebor and about 37 kilometres (23 mi) north-east of Wollomombi on Waterfall Way in the New England region of New South Wales, Australia."},{"name":"Yarrbilgong Falls","slug":"yarrbilgong-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.232,"longitude":153.19036,"description":"The Yarrbilgong Falls, a waterfall on the Coomera River, is located within Lamington National Park in the South East region of Queensland, Australia."},{"name":"Bloomfield Falls","slug":"bloomfield-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-15.95881,"longitude":145.3195,"description":"The Bloomfield Falls is a cascade waterfall on the Bloomfield River near Cape Tribulation, close to Wujal Wujal in Queensland, Australia. It is within the Wet Tropics of Queensland World Heritage Area."},{"name":"Tinaroo Falls","slug":"tinaroo-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-17.16361,"longitude":145.54583,"description":"The Tinaroo Falls, a waterfall on the Barron River, is located in the below the Lake Tinaroo dam wall in Far North region of Queensland, Australia."},{"name":"Josephine Falls","slug":"josephine-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-17.43345,"longitude":145.86275,"description":"The Josephine Falls is a tiered cascade waterfall on the Josephine Creek located in Wooroonooran, Cairns Region in the Far North region of Queensland, Australia."},{"name":"Coomera Falls","slug":"coomera-falls","category":"Waterfall","country":"Australia","region":null,"city":null,"latitude":-28.23347,"longitude":153.19085,"description":"The Coomera Falls is a segmented waterfall on the upper Coomera River in the South East region of Queensland, Australia."},{"name":"Glymur","slug":"glymur","category":"Waterfall","country":"Iceland","region":"Hvalfjarðarsveit","city":null,"latitude":64.39092,"longitude":-21.25184,"description":"Glymur is a waterfall in Hvalfjarðarsveit, Vesturland, Iceland. It is the second-tallest in the country with a cascade of 198 metres (650 ft). Glymur was long regarded as the tallest until being surpassed by Morsárfoss, a newly measured waterfall near Morsárjökull in 2011."},{"name":"Cascata delle Marmore","slug":"cascata-delle-marmore","category":"Waterfall","country":"Italy","region":"Terni","city":null,"latitude":42.55106,"longitude":12.71522,"description":"The Cascata delle Marmore or Marmore Falls is a tiered, man-made waterfall in Italy, created by the Romans in 271 BC. At 165m tall, it is the largest man-made waterfall in the world. It is located 7.7 km from Terni, in the region of Umbria."},{"name":"Nevada Fall","slug":"nevada-fall","category":"Waterfall","country":"United States","region":"Mariposa County","city":null,"latitude":37.72528,"longitude":-119.53278,"description":"Nevada Fall is a 594-foot-high (181 m) waterfall on the Merced River in Yosemite National Park, California. It is located below the granite dome, Liberty Cap, at the west end of Little Yosemite Valley. The waterfall is widely recognized by its \"bent\" shape, in which the water free-falls for roughly the first third of its length to a steep slick-rock slope."},{"name":"Vøringfossen","slug":"v-ringfossen","category":"Waterfall","country":"Norway","region":"Eidfjord Municipality","city":null,"latitude":60.42689,"longitude":7.25114,"description":"Vøringsfossen or Vøringen is the 83rd highest waterfall in Norway on the basis of total fall. It lies at the top of the Måbødalen valley in Eidfjord Municipality in Vestland county. It is located near Norwegian National Road 7, which connects Oslo with Bergen. It has a total drop of 182 metres (597 ft), and a major drop of 163 metres (535 ft)."},{"name":"Narada Falls","slug":"narada-falls","category":"Waterfall","country":"United States","region":"Lewis County","city":null,"latitude":46.775,"longitude":-121.746,"description":"Narada Falls is a waterfall in Mount Rainier National Park, in the U.S. state of Washington. It is said to be the most popular, because the Mount Rainier Highway crosses the falls between its two tiers."},{"name":"Bridal Veil Falls","slug":"bridal-veil-falls","category":"Waterfall","country":"United States","region":"Niagara Falls","city":null,"latitude":43.0835,"longitude":-79.0707,"description":"Bridal Veil Falls is the smallest of the three waterfalls that make up Niagara Falls. It is located on the United States side in New York state. Luna Island separates it from the American Falls and Goat Island separates it from the Horseshoe Falls. Bridal Veil Falls faces to the northwest and has a crest 56 ft (17 m) wide."},{"name":"Gocta Cataracts","slug":"gocta-cataracts","category":"Waterfall","country":"Peru","region":"Amazonas Department","city":null,"latitude":-6.02306,"longitude":-77.88722,"description":"Gocta is a perennial waterfall with two drops located in Peru's province of Bongara in Amazonas, approximately 771 kilometres (479 mi) to the northeast of Lima. It flows into the Cocahuayco River. Although the waterfall had been well known to locals for centuries, its existence was not made known to the world until after an expedition made in 2002 by a German, Stefan Ziemendorff, with a group of Peruvian explorers."},{"name":"Iguaçu Falls","slug":"igua-u-falls","category":"Waterfall","country":"Brazil","region":"Paraná","city":null,"latitude":-25.69528,"longitude":-54.43667,"description":"The Iguazú Falls or Iguaçu Falls are waterfalls of the Iguazu River on the border of the Argentine province of Misiones and the Brazilian state of Paraná. Together, they make up the largest waterfall system in the world. The falls divide the river into the upper and lower Iguazu. The Iguazu River rises near the heart of the city of Curitiba."},{"name":"Hooker Falls","slug":"hooker-falls","category":"Waterfall","country":"United States","region":"Transylvania County","city":null,"latitude":35.20211,"longitude":-82.62375,"description":"Hooker Falls is a 14 ft (4.3 m) waterfall located in the DuPont State Forest, southeast of Brevard, North Carolina."},{"name":"Mekedaatu","slug":"mekedaatu","category":"Waterfall","country":"India","region":"Bengaluru","city":null,"latitude":12.25818,"longitude":77.44866,"description":"Mekedatu is a location in kanakapura along Kaveri in the border of Bengaluru South and Chamarajanagar Districts. From this point, about 3.5 kilometers downstream, the river Kaveri flows through a deep and narrow gorge. Mekedatu means 'goat's leap' in Kannada. The name comes from an event which is believed to have been witnessed by herdsmen in that area a long time ago."},{"name":"Sisters of Mary Falls","slug":"sisters-of-mary-falls","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.23325,"longitude":-79.97835,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Kepler Cascades","slug":"kepler-cascades","category":"Waterfall","country":"United States","region":"Teton County","city":null,"latitude":44.44554,"longitude":-110.80587,"description":"Kepler Cascades is a waterfall on the Firehole River in southwestern Yellowstone National Park in the United States. The cascades are located approximately 2.5 miles south of Old Faithful. The cascades drop approximately 150 feet over multiple drops. The longest drop is 50 feet. The cascades are located very near to and visible from the Old Faithful to West Thumb road."},{"name":"Horsetrough Falls","slug":"horsetrough-falls","category":"Waterfall","country":"United States","region":"Georgia","city":null,"latitude":34.79217,"longitude":-83.78733,"description":"Horsetrough Falls is located on one of the flanks of Horsetrough Mountain in Union County, Georgia, part of the Blue Ridge Mountains. This 70-foot (21 m) waterfall is located on a creek that is part of the headwaters of the Chattahoochee River, which forms within a mile of the falls, and located within the Mark Trail Wilderness."},{"name":"Franklin Falls","slug":"franklin-falls","category":"Waterfall","country":"United States","region":"Washington","city":null,"latitude":47.425,"longitude":-121.432,"description":"Franklin Falls is the first of three major waterfalls on the South Fork Snoqualmie River. The other two downriver falls are Weeks Falls and Twin Falls. Franklin Falls are located near Snoqualmie Pass in King County, Washington, United States, between the north and south lanes of Interstate 90, just east of exit 47. The falls actually consist of three tiers, totaling 135 feet (41 m)."},{"name":"Hemlock Falls","slug":"hemlock-falls","category":"Waterfall","country":"United States","region":"Georgia","city":null,"latitude":34.8355,"longitude":-85.4823,"description":"Hemlock Falls is an waterfall located in Cloudland Canyon State Park in Dade County, Georgia. The waterfall, formerly unnamed, was named in a contest."},{"name":"Lodh Falls","slug":"lodh-falls","category":"Waterfall","country":"India","region":"Latehar district","city":null,"latitude":23.48056,"longitude":84.01944,"description":"The Lodh Falls is a waterfall on the Burha River in the mid-forest of Palamau Tiger Reserve, in Latehar district of Jharkhand state in India. It is the highest waterfall in Jharkhand and the 21st highest waterfall in India."},{"name":"Ravana Falls","slug":"ravana-falls","category":"Waterfall","country":"Sri Lanka","region":"Ella","city":null,"latitude":6.90389,"longitude":81.05167,"description":"Ravana Ella, also known as Ravama Falls, or Bambaragala Falls is a popular sightseeing attraction in Uva province of Sri Lanka. It currently ranks as one of the widest falls in the country."},{"name":"Valaste Waterfall","slug":"valaste-waterfall","category":"Waterfall","country":"Estonia","region":"Jõhvi Rural Municipality","city":null,"latitude":59.44389,"longitude":27.33528,"description":"Valaste Falls is the highest waterfall in Estonia and neighboring regions. It is located between Ontika and Valaste in Jõhvi Parish of Ida-Viru County and is formed by Valaste Creek as it flows over the Baltic Klint not far from the shore of the Gulf of Finland. It is a popular tourist attraction, with its spray freezing up in winter."},{"name":"Bond Falls","slug":"bond-falls","category":"Waterfall","country":"United States","region":"Michigan","city":null,"latitude":46.4088,"longitude":-89.1329,"description":"Bond Falls is a waterfall on the middle branch of the Ontonagon River, a few miles east of Paulding in Haight Township in southern Ontonagon County, Michigan. The site is near U.S. Highway 45 in the western portion of the Upper Peninsula of Michigan. The waterfalls are listed by the state of Michigan as the Bond Falls Scenic Site."},{"name":"Dillon Falls","slug":"dillon-falls","category":"Waterfall","country":"United States","region":"Oregon","city":null,"latitude":43.9575,"longitude":-121.412,"description":"Dillon Falls are rapids on the Deschutes River in the U.S. state of Oregon near Bend in the Deschutes National Forest."},{"name":"Walker Falls","slug":"walker-falls","category":"Waterfall","country":"United States","region":"North Carolina","city":null,"latitude":35.75556,"longitude":-82.35437,"description":"Walker Falls is a 45-foot cascading waterfall in Buncombe County, North Carolina. Its ease of access makes it a popular destination for waterfall hunters. It is in a region of Buncombe County that has a large number of small waterfalls and several larger falls."},{"name":"Still Brook Waterfall","slug":"still-brook-waterfall","category":"Waterfall","country":"Canada","region":"Cape Breton","city":null,"latitude":46.77722,"longitude":-60.33194,"description":"Still Brook Waterfall is a waterfall at mouth of Still Brook, where the brook empties into Black Brook Cove, and so into the Cabot Strait and the Atlantic Ocean. Still Brook Waterfall flows into Black Brook Cove at the north end of Ringing Beach and Black Brook Beach, a popular swimming and picnic site on the Cabot Trail in the Cape Breton Highlands National Park, 10 kilometres (6 mi) north of Ingonish, Nova Scotia,."},{"name":"Feature Show Falls","slug":"feature-show-falls","category":"Waterfall","country":"United States","region":"Snohomish County","city":null,"latitude":48.2394,"longitude":-121.823,"description":"Feature Show Falls is a waterfall on an unnamed tributary of the Boulder River in Washington, United States. It is a segmented 180-foot (55 m) drop that is about 35 feet (11 m) wide at its base. The falls drop directly into the Boulder River."},{"name":"Rajrappa","slug":"rajrappa","category":"Waterfall","country":"India","region":"Ramgarh district","city":null,"latitude":23.632,"longitude":85.711,"description":"Rajrappa is a waterfall and a pilgrimage centre in the Chitarpur CD block in the Ramgarh subdivision of the Ramgarh district in the Indian state of Jharkhand."},{"name":"Centennial Falls","slug":"centennial-falls","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.20861,"longitude":-79.76833,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Helton Creek Falls","slug":"helton-creek-falls","category":"Waterfall","country":"United States","region":"Georgia","city":null,"latitude":34.7533,"longitude":-83.895,"description":"Helton Creek Falls is a series of two big waterfalls located within the Chattahoochee National Forest in Union County, Georgia."},{"name":"Green Lake Falls","slug":"green-lake-falls","category":"Waterfall","country":"United States","region":"Whatcom County","city":null,"latitude":48.6928,"longitude":-121.491,"description":"Green Lake Falls is a large, very difficult to access waterfall located a short distance below the outlet of remote Green Lake, in North Cascades National Park, Whatcom County, Washington. It is 979 feet (298 m) high & averages 150 feet (46 m) wide and flows year-round. It has several tiers, including a 300-foot slide and a 500-foot plunge."},{"name":"Eastatoe Falls","slug":"eastatoe-falls","category":"Waterfall","country":"United States","region":"North Carolina","city":null,"latitude":35.11176,"longitude":-82.81684,"description":"Eastatoe Falls is a waterfall in Western North Carolina, United States, located on private property near the town of Rosman. The public was once allowed access, but as of 2019, the property has been sold, and it has been closed to the public."},{"name":"Ozone Falls","slug":"ozone-falls","category":"Waterfall","country":"United States","region":"Cumberland County","city":null,"latitude":35.8804,"longitude":-84.81,"description":"Ozone Falls is a waterfall located in Cumberland County, Tennessee in the Ozone Falls State Natural Area and Cumberland Trail State Park. Ozone Falls is situated along Fall Creek, which drains a short section of the Cumberland Plateau between the Crab Orchard Mountains to the west and Walden Ridge to the east."},{"name":"Madison Creek Falls","slug":"madison-creek-falls","category":"Waterfall","country":"United States","region":"Washington","city":null,"latitude":48.0417,"longitude":-123.589,"description":"Madison Creek Falls is located within the Olympic National Park near the Elwha River, west of Port Angeles, Washington. The falls is about 50 feet high and has a light flow in a horsetail shape. Another higher falls is located above the first, but is completely inaccessible. The paved trail to the falls is very short and is wheelchair accessible."},{"name":"Lower Hopkins Cascade","slug":"lower-hopkins-cascade","category":"Waterfall","country":"Canada","region":"Hamilton","city":null,"latitude":43.29639,"longitude":-79.92917,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"La Fortuna Waterfall","slug":"la-fortuna-waterfall","category":"Waterfall","country":"Costa Rica","region":"La Fortuna","city":null,"latitude":10.44091,"longitude":-84.67639,"description":"La Fortuna Waterfall is in north-central Costa Rica, in Arenal Volcano National Park in the Alajuela Province. In Spanish, it is known as Catarata Fortuna. The waterfall drops about 70−75 meters and is at the base of the dormant Chato volcano, about 5.5 km outside of the town of La Fortuna, near the Arenal Volcano."},{"name":"Otter Falls","slug":"otter-falls","category":"Waterfall","country":"United States","region":"King County","city":null,"latitude":47.5875,"longitude":-121.467,"description":"Otter Falls is a waterfall in King County, Washington; on the southern wall of Mount Anderson. It drops about 1,600 feet (490 m) in all, but due to the relatively moderate pitch of the mountainside, only about 1/3 of the total height can be seen from the ground. The drainage of Otter Creek, which feeds the falls, is fairly small, and consists mostly of granite which does not retain water."},{"name":"Berdeen Falls","slug":"berdeen-falls","category":"Waterfall","country":"United States","region":"Whatcom County","city":null,"latitude":48.7061,"longitude":-121.482,"description":"Berdeen Falls is a series of three waterfalls located in Whatcom County, Washington. The 850-foot (260 m) falls are on a stretch of Bacon Creek downstream of Berdeen Lake.The drops include a 400-foot (120 m) horsetail, a 200-foot (61 m) bedrock slide, and a 250-foot (76 m) plunge waterfall."},{"name":"Burgess Falls","slug":"burgess-falls","category":"Waterfall","country":"United States","region":"Putnam County","city":null,"latitude":36.04417,"longitude":-85.59418,"description":"The Burgess Falls is a cascade waterfall on the Falling Water River located within the Burgess Falls State Park, in Putnam and White counties, Tennessee, in the United States. The waterfall spills approximately 136 feet (41 m) into a large limestone gorge enclosed by sheer 100–200-foot (30–61 m) walls. The Falling Water River enters Center Hill Lake downstream from Burgess Falls."},{"name":"Scenic Falls","slug":"scenic-falls","category":"Waterfall","country":"Canada","region":"Ontario","city":null,"latitude":43.2446,"longitude":-79.9337,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Bad Branch Falls","slug":"bad-branch-falls","category":"Waterfall","country":"United States","region":"Georgia","city":null,"latitude":34.9833,"longitude":-83.3333,"description":"Bad Branch Falls is a partially manmade waterfall located in Chattahoochee National Forest, Rabun County, in the U.S. State of Georgia, on the site of an old quarry. It is near Lake Rabun and Lake Seed."},{"name":"Sydenham Falls","slug":"sydenham-falls","category":"Waterfall","country":"Canada","region":"Ontario","city":null,"latitude":43.274,"longitude":-79.9582,"description":"A waterfall in Canada, documented on Wikipedia. Check local guides for access, the best season and any entry fee before you travel."},{"name":"Badaghagara Waterfall","slug":"badaghagara-waterfall","category":"Waterfall","country":"India","region":"Kendujhar district","city":null,"latitude":21.60874,"longitude":85.55574,"description":"The Badaghagara Waterfall is a waterfall of the Kendujhar district in the Indian state of Odisha."},{"name":"Phu Fa waterfall","slug":"phu-fa-waterfall","category":"Waterfall","country":"Thailand","region":"Phu Fa","city":null,"latitude":19.00278,"longitude":101.21611,"description":"Phu Fa is a waterfall in the deep jungle of the Luang Prabang Range near the Laos border. It is located in the protected area of Doi Phu Kha National Park, Mae Charim District. Phu Fa waterfall is the biggest and the tallest waterfall in Nan Province."},{"name":"Kravica","slug":"kravica","category":"Waterfall","country":"Bosnia and Herzegovina","region":"Federation of Bosnia and Herzegovina","city":null,"latitude":43.15583,"longitude":17.60833,"description":"Kravica Waterfall is a large tufa cascade on the Trebižat River, in the karstic heartland of Herzegovina in Bosnia and Herzegovina. It is 10 kilometres (6 mi) south of Ljubuški and 40 kilometres (25 mi) south of Mostar. Its height is about 25 metres (80 ft) and the radius of the lake in the base of the waterfall is 120 metres (390 ft)."},{"name":"Hagi Falls","slug":"hagi-falls","category":"Waterfall","country":"Japan","region":"Gifu","city":null,"latitude":35.45656,"longitude":136.8025,"description":"The Hagi Falls is a waterfall located in Mount Dodo's small valley in the city of Gifu, Gifu Prefecture, Japan. In 1986, it was named one of Gifu Prefecture's \"50 Famous Waters.\""},{"name":"Antisana volcano","slug":"antisana-volcano","category":"Mountain","country":"Ecuador","region":"Napo Province","city":null,"latitude":-0.48139,"longitude":-78.14083,"description":"Antisana is a stratovolcano of the northern Andes, in Ecuador. It is the fourth highest volcano in Ecuador, at 5,753 metres (18,875 ft), and is located 50 kilometres (31 mi) SE of the capital city of Quito."},{"name":"Mount Etna","slug":"mount-etna","category":"Mountain","country":"Italy","region":"Zafferana Etnea","city":null,"latitude":37.75083,"longitude":14.99322,"description":"Mount Etna, or simply Etna, is an active stratovolcano on the east coast of Sicily, Italy, in the Metropolitan City of Catania, between the cities of Messina and Catania. It is located above the convergent plate margin between the African Plate and the Eurasian Plate."},{"name":"Mount Asama","slug":"mount-asama","category":"Mountain","country":"Japan","region":"Karuizawa","city":null,"latitude":36.4,"longitude":138.51667,"description":"Mount Asama is an active stratovolcano in central Honshū, the main island of Japan. The volcano is the most active on Honshū. The Japan Meteorological Agency classifies Mount Asama as rank A. It stands 2,568 metres (8,425 ft) above sea level on the border of Gunma and Nagano prefectures. It is included in 100 Famous Japanese Mountains."},{"name":"Reventador","slug":"reventador","category":"Mountain","country":"Ecuador","region":"El Chaco","city":null,"latitude":-0.07694,"longitude":-77.65611,"description":"Reventador is an active stratovolcano which lies in the eastern Andes of Ecuador. It lies in a remote area of the national park of the same name, which is Spanish for \"exploder\". Since 1541, it has erupted over 25 times, although its isolated location means that many of its eruptions have gone unreported."},{"name":"Kentur Lokon","slug":"kentur-lokon","category":"Mountain","country":"Indonesia","region":"North Sulawesi","city":null,"latitude":1.35806,"longitude":124.79194,"description":"Mount Lokon, also known as Gunung Lokon, together with Mount Empung, is a twin volcano in the Tomohon, Minahasa Regency, North Sulawesi, Indonesia, roughly 10 km (6 mi) south of Manado. Both rise above the Tondano plain and are among active volcanoes of Sulawesi. Mount Lokon has a flat and craterless top. Its active crater is located on its foot, named \"Tompaluan\" crater."},{"name":"Cerro Azul","slug":"cerro-azul","category":"Mountain","country":"Chile","region":"San Clemente","city":null,"latitude":-35.65333,"longitude":-70.76083,"description":"Cerro Azul, sometimes referred to as Quizapu, is an active stratovolcano in the Maule Region of central Chile, immediately south of Descabezado Grande. Part of the South Volcanic Zone of the Andes, its summit is 3,788 meters (12,428 ft) above sea level, and is capped by a summit crater that is 500 meters (1,600 ft) wide and opens to the north."},{"name":"Cerro del Azufre","slug":"cerro-del-azufre","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-21.78306,"longitude":-68.23972,"description":"Cerro del Azufre is a stratovolcano located in El Loa Province, Antofagasta Region, Chile. It is part of a chain of volcanoes that separate Upper Loa River basin from the endorheic Salar de Ascotán basin and is flanked to the west by a dacitic lava dome called Chanka or Pabellón. The 6000 metre volcanoes San Pedro and San Pablo are located to the southwest of Cerro del Azufre."},{"name":"Chachani","slug":"chachani","category":"Mountain","country":"Peru","region":"Arequipa Department","city":null,"latitude":-16.19417,"longitude":-71.53167,"description":"Chachani is a volcanic group in southern Peru, 22 kilometres (14 mi) northwest of the city of Arequipa. Part of the Central Volcanic Zone of the Andes, it is 6,057 metres (19,872 ft) above sea level. It consists of several lava domes and individual volcanoes such as Nocarane, along with lava shields such as the Airport Domes. Underneath Chachani lies a caldera."},{"name":"Makushin Volcano","slug":"makushin-volcano","category":"Mountain","country":"United States","region":"Aleutians West Census Area","city":null,"latitude":53.88632,"longitude":-166.91112,"description":"The Makushin Volcano is an ice-covered stratovolcano located on Unalaska Island in the Aleutian Islands of the U.S. state of Alaska. With an elevation of 2,036 meters (6,680 ft), its summit is the highest point on the island. Makushin is one of the most active among the 52 historically active volcanoes of Alaska."},{"name":"Mount Papandayan","slug":"mount-papandayan","category":"Mountain","country":"Indonesia","region":"Garut","city":null,"latitude":-7.32897,"longitude":107.7157,"description":"Mount Papandayan is a complex stratovolcano, located in Garut Regency, to the southeast of the city of Bandung in West Java, Indonesia. It is about 15 kilometres (9.3 mi) to the southwest of the town of Garut. At the summit, there are four large craters which contain active fumarole fields."},{"name":"Ubinas","slug":"ubinas","category":"Mountain","country":"Peru","region":"Moquegua Department","city":null,"latitude":-16.34861,"longitude":-70.90222,"description":"Ubinas is an active stratovolcano in the Moquegua Region of southern Peru, approximately 60 kilometres (37 mi) east of the city of Arequipa. Part of the Central Volcanic Zone of the Andes, it rises 5,672 metres (18,609 ft) above sea level. The volcano's summit is cut by a 1.4-kilometre-wide (0.87 mi) and 150-metre-deep (490 ft) caldera, which itself contains a smaller crater."},{"name":"Mount Sumbing","slug":"mount-sumbing","category":"Mountain","country":"Indonesia","region":"Jambi","city":null,"latitude":-2.414,"longitude":101.728,"description":"Mount Sumbing is a stratovolcano in the central region of Sumatra, Indonesia. The volcano has a complicated summit region with several craters and a 180 m-long (590 ft) crater lake."},{"name":"Gunung Perbakti","slug":"gunung-perbakti","category":"Mountain","country":"Indonesia","region":"West Java","city":null,"latitude":-6.75,"longitude":106.68,"description":"Perbakti is an eroded stratovolcano west of Mount Salak in West Java, Indonesia. The summit is elongated in a northwest-southwest direction, in which Gunung Endut volcano rises above the saddle of Perbakti. Two 2 km wide depressions on the northern and the southern side has formed two rivers, the Kaluwung Herang and Pamatutan rivers."},{"name":"Dolok Lubuk Raya","slug":"dolok-lubuk-raya","category":"Mountain","country":"Indonesia","region":"South Tapanuli","city":null,"latitude":1.478,"longitude":99.209,"description":"Lubukraya is an andesitic stratovolcano on Sumatra island, Indonesia. It has a broad crater breached to the south and a lava dome at the southern foot of the volcano."},{"name":"Dolok Sibualbuali","slug":"dolok-sibualbuali","category":"Mountain","country":"Indonesia","region":"North Sumatra","city":null,"latitude":1.556,"longitude":99.255,"description":"Sibualbuali is a stratovolcano in northern Sumatra, Indonesia. It has two solfatara fields on the eastern flank. There is a rhyolitic-dacitic lava dome, erupted from the Toru-Asik fault."},{"name":"Iliboleng","slug":"iliboleng","category":"Mountain","country":"Indonesia","region":"Lesser Sunda Islands","city":null,"latitude":-8.344,"longitude":123.252,"description":"The Iliboleng is a stratovolcano located at the southeast end of Adonara Island in Flores in Indonesia."},{"name":"Yucamane","slug":"yucamane","category":"Mountain","country":"Peru","region":"Tacna Department","city":null,"latitude":-17.18,"longitude":-70.2,"description":"Yucamane, Yucamani or Yucumane is an andesitic stratovolcano in the Tacna Region of southern Peru. It is part of the Peruvian segment of the Central Volcanic Zone, one of the three volcanic belts of the Andes generated by the subduction of the Nazca plate beneath the South America plate. Peru's active volcanoes Ubinas, Sabancaya and El Misti are also part of the Central Volcanic Zone."},{"name":"Caichinque","slug":"caichinque","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-23.95,"longitude":-67.73333,"description":"Caichinque is a volcanic complex lying between Salar de Talar and Salar de Capur, in the high Andean plateau of the Antofagasta Region, in Chile. It is located southwest of the Salar de Atacama, directly S of Cerro Miñiques and SE of Cordón Puntas Negras forming part of the main branch of the Andean volcanic chain in this area. Route CH-23 is an approach road to the volcano area and could be impacted by eruptions."},{"name":"Cerro Negro de Mayasquer","slug":"cerro-negro-de-mayasquer","category":"Mountain","country":"Colombia","region":"Nariño Department","city":null,"latitude":0.8275,"longitude":-77.96444,"description":"Cerro Negro de Mayasquer is a volcano on the border of Colombia and Ecuador. It lies 3 kilometres (2 mi) north-west of the volcano Chiles, and the two peaks are considered part of the same Chiles-Cerro Negro volcanic complex. These volcanoes, together with Cumbal are andesitic in rock type."},{"name":"Colachi","slug":"colachi","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-23.24192,"longitude":-67.64605,"description":"Colachi is a stratovolcano in the Antofagasta Region of northern Chile. It was built on a basement of ignimbrites. A 7 km² silicic lava flow lies on the saddle between the volcano and Acamarachi."},{"name":"Copiapó volcano","slug":"copiap-volcano","category":"Mountain","country":"Chile","region":"Atacama Region","city":null,"latitude":-27.3056,"longitude":-69.1317,"description":"Copiapó, also known as Azufre, is a stratovolcano located in the Atacama Region of Chile. The volcano separates the two portions in which Nevado Tres Cruces National Park is divided. In its vicinity lies Ojos del Salado. At its summit an Inca platform can be found."},{"name":"Cordón de Puntas Negras","slug":"cord-n-de-puntas-negras","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-23.74278,"longitude":-67.53417,"description":"Cordón de Puntas Negras is a 500 km2 (193 mi2) volcanic chain located east of the Salar de Atacama in Chile's Antofagasta Region."},{"name":"Mount Mahawu","slug":"mount-mahawu","category":"Mountain","country":"Indonesia","region":"North Sulawesi","city":null,"latitude":1.358,"longitude":124.858,"description":"Mount Mahawu is a stratovolcano located immediately east from Lokon-Empung volcano in North Sulawesi, Indonesia. The volcano is capped with 180 m wide and 140 m deep crater with two pyroclastic cones in the northern flanks. A small explosive eruption was recorded in 1789. In 1994, fumaroles, mudpots and small geysers activities were observed along the greenish shore of a crater lake."},{"name":"Lautaro","slug":"lautaro","category":"Mountain","country":"Chile","region":"Aysén Region","city":null,"latitude":-49.019,"longitude":-73.504,"description":"Lautaro is an active subglacial stratovolcano located in Chilean Patagonia, in the northern part of the Southern Patagonian Ice Field. Its summit rises roughly 2,400 m (7,900 ft) above the average surface of the ice cap plateau. Its height above sea level is 3,623 m (11,900 ft)."},{"name":"Mount Empung","slug":"mount-empung","category":"Mountain","country":"Indonesia","region":"North Sulawesi","city":null,"latitude":1.37423,"longitude":124.80324,"description":"Mount Empung, together with Mount Lokon, is a twin volcano in the North Sulawesi, Indonesia. Both volcanoes rise above the Tondano plain and are among active volcanoes of Sulawesi. Mount Empung has a 400 m wide and 150 m deep crater at the summit that erupted in the eighteenth century."},{"name":"Hachimantai","slug":"hachimantai","category":"Mountain","country":"Japan","region":"Kazuno","city":null,"latitude":39.95778,"longitude":140.85417,"description":"Mount Hachimantai is the highest peak of a group of stratovolcanos distributed around the Hachimantai plateau in the Ōu Mountains in northern Honshū, Japan. This volcanic plateau is part of the Nasu Volcanic Zone and straddles the border between the Iwate Prefecture and Akita Prefecture. The volcano is listed as one of the 100 Famous Japanese Mountains, and forms part of the Towada-Hachimantai National Park."},{"name":"Pular","slug":"pular","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-24.2005,"longitude":-68.0665,"description":"Pular is a volcanic massif in the northern Chilean Andes, in the Antofagasta Region north of Socompa volcano. It consists of the individual mountains Pajonales and Pular, which are among the highest mountains in the region and of great cultural importance to the neighbouring towns of Socaire and Peine. Pular and Pajonales have multiple volcanic craters and have produced lava domes."},{"name":"Mount Tongkoko","slug":"mount-tongkoko","category":"Mountain","country":"Indonesia","region":"Bitung","city":null,"latitude":1.52,"longitude":125.2,"description":"Mount Tangkoko is a stratovolcano in the north of Sulawesi island in Indonesia. Its summit has an elongated deep crater.On the east flank is a flat lava dome, Batu Angus. Historical records only show eruptions in the 17th and 19th centuries, including a possible VEI5 eruption in 1680."},{"name":"Miñiques Volcano","slug":"mi-iques-volcano","category":"Mountain","country":"Chile","region":"El Loa Province","city":null,"latitude":-23.81667,"longitude":-67.76667,"description":"Miñiques is a massive volcanic complex containing a large number of craters, lava domes and flows, located in the Antofagasta Region of Chile. Located 21 km (13 mi) south of Volcán Chiliques and 26 km (16 mi) west of Cordón Puntas Negras, it is part of a frequently visited attraction conformed by the high plain lagoons Laguna Miscanti, Laguna Miñiques and the Cerro Miscanti volcano."},{"name":"Isluga","slug":"isluga","category":"Mountain","country":"Chile","region":"Tamarugal Province","city":null,"latitude":-19.15,"longitude":-68.83333,"description":"Isluga is a dormant stratovolcano in Chile's Tarapacá Region, close to the border with Bolivia. It is part of the Volcán Isluga National Park and lies in the Central Volcanic Zone of the Andes, one of several volcanic belts in the Andean Volcanic Belt. Isluga is an elongated mountain, whose summit reaches an altitude of 5,559 metres (18,238 ft) above sea level, and features a summit crater."},{"name":"La Soufrière","slug":"la-soufri-re","category":"Mountain","country":"Saint Vincent and the Grenadines","region":"Charlotte Parish","city":null,"latitude":13.33333,"longitude":-61.18333,"description":"La Soufrière or Soufrière Saint Vincent is an active volcano on the Caribbean island of Saint Vincent in Saint Vincent and the Grenadines. It is the highest peak on Saint Vincent, and has had eight recorded eruptions since 1718. The latest eruptive activity began on 27 December 2020 with the slow extrusion of a dome of lava, and culminated in a series of explosive events between 9 and 22 April 2021."},{"name":"Sarik Merapi","slug":"sarik-merapi","category":"Mountain","country":"Indonesia","region":"North Sumatra","city":null,"latitude":0.686,"longitude":99.539,"description":"Sorikmarapi is a highly vegetated stratovolcano on Sumatra island, Indonesia. It has a 600 m wide of crater lake at the summit and some sulfur deposits. A small parasitic crater, called Danau Merah, is found at the upper southeast flank of the mountain and several solfatara fields at the eastern flank. During the 19th and 20th century, small phreatic eruptions occurred."},{"name":"Cot Seulawah Agam","slug":"cot-seulawah-agam","category":"Mountain","country":"Indonesia","region":"Aceh","city":null,"latitude":5.448,"longitude":95.658,"description":"Seulawah Agam is an extensive forested stratovolcano located at the northwestern tip of Sumatra. Several names have been given to the mountain: Seulawaih Agam, Seulawain Agam, Solawa Agam, Solawaik Agam, Selawadjanten and Goldberg."},{"name":"Mount Fuji","slug":"mount-fuji","category":"Mountain","country":"Japan","region":"Shizuoka Prefecture","city":null,"latitude":35.36056,"longitude":138.7275,"description":"Mount Fuji is an active stratovolcano located on the Japanese island of Honshu, with a summit elevation of 3,776.24 m. It is the highest mountain in Japan, the second-highest volcano on any Asian island, and the seventh-highest peak of an island on Earth. Mount Fuji last erupted from 1707 to 1708."},{"name":"Mount Tandikat","slug":"mount-tandikat","category":"Mountain","country":"Indonesia","region":"West Sumatra","city":null,"latitude":-0.43258,"longitude":100.31714,"description":"Tandikat is an active stratovolcano in West Sumatra, Indonesia. Its elevation is 2,438 m (7,999 ft). It is a twin volcano with Mount Singgalang, which is located to the north-north-east of Tandikat. However, only Tandikat has had historical volcanic activity. The city of Padang Panjang is located at the foot of the mountain."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 1: % places added', added;
end $$;

-- batch 2 of 6: 150 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Damavand","slug":"damavand","category":"Mountain","country":"Iran","region":"Semnan Province","city":null,"latitude":35.95528,"longitude":52.10917,"description":"Mount Damavand is a dormant stratovolcano in Iran. It is the highest peak in Iran and Western Asia, the highest volcano in Asia, and the third highest volcano in the Eastern Hemisphere, at an elevation of 5,610 metres (18,410 ft). Damāvand has a special place in Persian mythology and folklore. It is in the middle of the Alborz range, adjacent to Varārū, Sesang, Gol-e Zard, and Mīānrūd."},{"name":"Geureudong","slug":"geureudong","category":"Mountain","country":"Indonesia","region":"Aceh","city":null,"latitude":4.8105,"longitude":96.8169,"description":"Geureudong or Bur ni Geureudong or Bur ni Telong is a stratovolcanic complex in northern Sumatra, Indonesia. The official name of the whole complex is confusing between the two adjacent volcanoes: Bur ni Geureudong and Bur ni Telong. Two other volcanic cones are Salah Nama and Pepanji, and there are small sediment hills."},{"name":"Mount Pulosari","slug":"mount-pulosari","category":"Mountain","country":"Indonesia","region":"Banten","city":null,"latitude":-6.34167,"longitude":105.97833,"description":"Mount Pulosari is a stratovolcano in Pandeglang Regency, Banten, in West Java Indonesia. There are active solfataras on its 300-metre (980 ft) deep caldera wall."},{"name":"Gunung Rajabasa","slug":"gunung-rajabasa","category":"Mountain","country":"Indonesia","region":null,"city":null,"latitude":-5.78333,"longitude":105.625,"description":"Rajabasa is an isolated 1281-m-high conical volcano along the Sunda Strait at the most southeastern point of Sumatra. It has a well-preserved 500 x 700 m summit crater with a swampy floor. The volcano is covered with vegetation. Although fumarolic activity occurs on the foot and flanks of the volcano and increased activity was reported in April 1863 and May 1892, it is not known when it last erupted."},{"name":"Mount Churchill","slug":"mount-churchill","category":"Mountain","country":"United States","region":"Copper River Census Area","city":null,"latitude":61.41917,"longitude":-141.71528,"description":"Mount Churchill is a dormant volcano in the Saint Elias Mountains and the Wrangell Volcanic Field (WVF) of eastern Alaska. Churchill and its neighbor Mount Bona are both ice-covered volcanoes with Churchill having a 2.7-by-4.2-kilometre-wide caldera just east of its summit. There are sparse outcrops of lava flows and tephra, mostly dacite."},{"name":"Mount Bona","slug":"mount-bona","category":"Mountain","country":"United States","region":"Copper River Census Area","city":null,"latitude":61.3856,"longitude":-141.749,"description":"Mount Bona is one of the major mountains of the Saint Elias Mountains in eastern Alaska, and is the fifth-highest independent peak in the United States. It is either the tenth- or eleventh-highest peak in North America. Mount Bona and its adjacent neighbor Mount Churchill are both large ice-covered stratovolcanoes."},{"name":"Volcán Zapatera","slug":"volc-n-zapatera","category":"Mountain","country":"Nicaragua","region":"Granada","city":null,"latitude":11.73,"longitude":-85.82,"description":"Zapatera is a shield volcano located in the southern part of Nicaragua. It forms the island of Isla Zapatera in the Lake Nicaragua. Isla Zapatera constitutes one of 78 protected areas of Nicaragua."},{"name":"Ball's Pyramid","slug":"balls-pyramid","category":"Mountain","country":"Australia","region":"New South Wales","city":null,"latitude":-31.75417,"longitude":159.25167,"description":"Ball's Pyramid is an uninhabited islet in the Pacific Ocean located 20 kilometres southeast of Lord Howe Island, between Australia and New Zealand. The steep rocky basalt outcrop is the eroded plug of a shield volcano and caldera that formed 6.4 million years ago. It is 572 metres (1,877 ft) high, 1,100 metres (3,609 ft) long and only 300 metres (984 ft) across, making it the tallest volcanic stack in the world."},{"name":"Mauna Loa","slug":"mauna-loa","category":"Mountain","country":"United States","region":"Hawaii County","city":null,"latitude":19.48333,"longitude":-155.6,"description":"Mauna Loa is one of five volcanoes that form the Island of Hawaii in the U.S. state of Hawaii in the Pacific Ocean. Mauna Loa is Earth's largest active volcano by both mass and volume. It was historically considered to be the largest volcano on Earth until the submarine mountain Tamu Massif was discovered to be larger."},{"name":"Cerro Tuzgle","slug":"cerro-tuzgle","category":"Mountain","country":"Argentina","region":"Jujuy Province","city":null,"latitude":-24.056,"longitude":-66.479,"description":"Cerro Tuzgle is a dormant stratovolcano in the Susques Department of Jujuy Province in northwestern Argentina. Tuzgle is a prominent volcano of the back arc of the Andes and lies about 280 kilometres (170 mi) east of the main volcanic arc. Part of the Central Volcanic Zone of the Andes, its summit is 5,486 metres (17,999 ft) above sea level and it grew during different stages over a caldera and lava domes."},{"name":"Sabancaya","slug":"sabancaya","category":"Mountain","country":"Peru","region":"Arequipa Department","city":null,"latitude":-15.78667,"longitude":-71.8575,"description":"Sabancaya is an active stratovolcano in the Andes of southern Peru, about 70 kilometres (43 mi) northwest of Arequipa. It is considered part of the Central Volcanic Zone of the Andes, one of the three distinct volcanic belts of the Andes."},{"name":"Adwa","slug":"adwa","category":"Mountain","country":"Ethiopia","region":"Gabi Rasu","city":null,"latitude":10.07,"longitude":40.84,"description":"Adwa is a stratovolcano in Ethiopia, located in the western Afar Region region and has a 4 by 5 km caldera. Due to the location of the volcano near the boundary between Afar and Issa tribes, little is known about the past and present behavior of the volcano."},{"name":"Mount Egon","slug":"mount-egon","category":"Mountain","country":"Indonesia","region":"Sikka","city":null,"latitude":-8.66667,"longitude":122.45,"description":"Mount Egon is a stratovolcano located in the southeastern part of the island of Flores, Indonesia in the area of Maumere bay. A landslide during the eruption on 29 January 2004 forced 6,000 people to evacuate the area. Activity of Gunung Egon on 15 April 2008 forced thousands of people to evacuate."},{"name":"Aguilera","slug":"aguilera","category":"Mountain","country":"Chile","region":"Última Esperanza Province","city":null,"latitude":-50.28458,"longitude":-73.66839,"description":"Aguilera is a stratovolcano in southern Chile. The volcano rises above the edge of the Southern Patagonian Ice Field. It is a remote volcano that was identified as such in 1985. The first ascent only occurred in 2014, making it the last unclimbed major Andean volcano."},{"name":"Licancabur","slug":"licancabur","category":"Mountain","country":"Chile","region":"Sur Lípez Province","city":null,"latitude":-22.83361,"longitude":-67.88278,"description":"Licancabur is a prominent, 5,916-metre-high (19,409 ft) stratovolcano on the Bolivia–Chile border in the Central Volcanic Zone of the Andes. It is capped by a 400–500-metre-wide (1,300–1,600 ft) summit crater which contains Licancabur Lake, a crater lake that is among the highest lakes in the world. There are no glaciers owing to the arid climate. Numerous plants and animal species live on the mountain."},{"name":"Colo","slug":"colo","category":"Mountain","country":"Indonesia","region":"Central Sulawesi","city":null,"latitude":-0.17,"longitude":121.608,"description":"Colo is a stratovolcano in Indonesia. It forms the island of Una-Una at the middle of the Gulf of Tomini, the northern part of Sulawesi. The volcano is broad and has a low profile with only 507 metres (1,663 ft) above the sea level. It contains a 2 kilometres (1.2 mi) wide caldera with a small volcanic cone inside. Three eruptions have been recorded, with two of them causing damage."},{"name":"Romanovka stratovolcano","slug":"romanovka-stratovolcano","category":"Mountain","country":"Russia","region":null,"city":null,"latitude":55.64331,"longitude":158.81081,"description":"Romanovka is a stratovolcano in central Kamchatka. The volcano is located at the north of Kozyrevka River in the southern Sredinny Range."},{"name":"Cotacachi","slug":"cotacachi","category":"Mountain","country":"Ecuador","region":"Imantag","city":null,"latitude":0.36083,"longitude":-78.34917,"description":"Cotacachi is a dormant volcano in the Western Cordillera of the northern Ecuadorian Andes, in the west of Imbabura Province, above the city of Cotacachi. It has a summit elevation of 4,944 m (16,220 ft) above sea level and its highest elevations are capped with snow."},{"name":"Cumbre Vieja","slug":"cumbre-vieja","category":"Mountain","country":"Spain","region":"Santa Cruz de Tenerife Province","city":null,"latitude":28.56667,"longitude":-17.83333,"description":"The Cumbre Vieja is an active volcanic ridge on the island of La Palma in the Canary Islands, Spain. The spine of Cumbre Vieja trends in an approximate north–south direction, comprising the southern half of La Palma, with both summit ridge and flanks pockmarked by dozens of craters and cones. The latest eruption began on 19 September 2021 in a forested area of Las Manchas locality known as Cabeza de Vaca."},{"name":"Mount Gede","slug":"mount-gede","category":"Mountain","country":"Indonesia","region":"Bogor","city":null,"latitude":-6.78833,"longitude":106.98167,"description":"Mount Gede is a stratovolcano in West Java, Indonesia. The volcano contains two peaks with Mount Gede as one peak and Mount Pangrango for the other one. Three major cities, Cianjur, Sukabumi, and Bogor, are located in the volcano complex at the east, south, and northwest, respectively, along with suburban growth."},{"name":"Soufrière","slug":"soufri-re","category":"Mountain","country":"France","region":"Saint-Claude","city":null,"latitude":16.0438,"longitude":-61.6634,"description":"La Grande Soufrière, or simply Soufrière, is an active stratovolcano on the French island of Basse-Terre, Guadeloupe. It is the highest mountain peak in the Lesser Antilles, rising 1,467 m (4,813 ft) high."},{"name":"Dempo","slug":"dempo","category":"Mountain","country":"Indonesia","region":"South Sumatra","city":null,"latitude":-4.03,"longitude":103.13,"description":"Mount Dempo is the highest stratovolcano in South Sumatra province that rises above Pasumah Plain near Pagar Alam and adjacent with Bengkulu Province. Seven craters are found around the summit. A 400-metre (1,300 ft) wide lake is found at the north-west end of the crater complex."},{"name":"Tangkuban Perahu","slug":"tangkuban-perahu","category":"Mountain","country":"Indonesia","region":"West Bandung","city":null,"latitude":-6.77,"longitude":107.6,"description":"Tangkuban Perahu is a stratovolcano in Lembang, West Bandung Regency, West Java, Indonesia. It erupted in 1826, 1829, 1842, 1846, 1896, 1910, 1926, 1929, 1952, 1957, 1961, 1965, 1967, 1969, 1983, 2013 and 2019. It is a popular tourist attraction where tourists hike or ride to the edge of the crater to view the hot water springs and boiling mud up close, and buy eggs cooked on the hot surface."},{"name":"Mount Haruna","slug":"mount-haruna","category":"Mountain","country":"Japan","region":"Takasaki","city":null,"latitude":36.47694,"longitude":138.87806,"description":"Mount Haruna is a dormant stratovolcano in Gunma Prefecture, in the Kantō region of eastern Honshū, Japan."},{"name":"Mount Amagi","slug":"mount-amagi","category":"Mountain","country":"Japan","region":"Higashiizu","city":null,"latitude":34.86278,"longitude":139.00167,"description":"Mount Amagi is a range of volcanic mountains in central Izu Peninsula in Shizuoka Prefecture, Japan, forming the border between Izu City and Higashi-Izu Town. It is also referred to as the Amagi Mountain Range ."},{"name":"Cold Bay Volcano","slug":"cold-bay-volcano","category":"Mountain","country":"United States","region":"Alaska","city":null,"latitude":55.0673,"longitude":-162.835,"description":"Frosty Peak Volcano, also known as Mt. Frosty, Frosty Volcano, or Cold Bay Volcano, is a 6,299 ft (1,920 m) stratovolcano at the southwest end of the Alaska Peninsula in the U.S. state of Alaska."},{"name":"Trident Volcano","slug":"trident-volcano","category":"Mountain","country":"United States","region":"Alaska","city":null,"latitude":58.235,"longitude":-155.104,"description":"Trident Volcano is an eroded volcanic complex on the Alaska Peninsula in Katmai National Park, Alaska. Up to 23 domes comprise the complex stratovolcano, with the greatest elevation of 6,115 feet (1,864 m). The most recent major activity produced a 3,599-foot (1,097 m) dome in an amphitheater on the southwest flank of the southwest peak."},{"name":"Mount Douglas","slug":"mount-douglas","category":"Mountain","country":"United States","region":"Kenai Peninsula Borough","city":null,"latitude":58.86,"longitude":-153.533,"description":"Mount Douglas is a stratovolcano located south of Kamishak Bay, near the northeasternmost part of the Alaska Peninsula. It lies in the Katmai National Park and Preserve in Kenai Peninsula Borough. The mountain was officially named in 1906 after nearby Cape Douglas based on a 1904 report by USGS geologist G. C. Martin. The Alaska Volcano Observatory currently rates Douglas as Level of Concern Color Code Not Assigned."},{"name":"Frosty Volcano","slug":"frosty-volcano","category":"Mountain","country":"United States","region":"Alaska","city":null,"latitude":55.082,"longitude":-162.814,"description":"A mountain in United States, documented on Wikipedia. Check local guides for routes, conditions and permits before you climb."},{"name":"Yantarni Volcano","slug":"yantarni-volcano","category":"Mountain","country":"United States","region":"Lake and Peninsula Borough","city":null,"latitude":57.0181,"longitude":-157.183,"description":"Yantarni Volcano is an andesitic stratovolcano in the U.S. state of Alaska. It is on the Alaska Peninsula, in the Aleutian Range, between Mount Aniakchak and Mount Chiginagak volcanoes. The volcano was not discovered until 1979 due to its remote location, lack of documented historic activity, and its rather modest summit elevation."},{"name":"Vogelsberg","slug":"vogelsberg","category":"Mountain","country":"Germany","region":"Hesse","city":null,"latitude":50.53333,"longitude":9.23333,"description":"The Vogelsberg is a large volcanic mountain range in the German Central Uplands in the state of Hesse, separated from the Rhön Mountains by the Fulda river valley. Emerging approximately 19 million years ago, the Vogelsberg is Central Europe's largest basalt formation, consisting of a multitude of layers that descend from their peak in ring-shaped terraces to the base."},{"name":"Þeistareykjarbunga","slug":"eistareykjarbunga","category":"Mountain","country":"Iceland","region":"Þingeyjarsveit","city":null,"latitude":65.88,"longitude":-16.84,"description":"Theistareykjarbunga is a shield volcano in north-eastern Iceland with two fissure vents called Þeistareykjahraun and Borgahraun, and two cones: the 370 m (1,210 ft) Stórahversmór and the 540 m (1,770 ft), 30 km3 (7.2 cu mi) Stóravíti. They both are currently extinct, although there is evidence suggesting the potential for activity such as recent localised uplift and seismicity."},{"name":"Akhtang","slug":"akhtang","category":"Mountain","country":"Russia","region":null,"city":null,"latitude":55.43,"longitude":158.65,"description":"Akhtang is a shield volcano topped by a small basaltic stratovolcano located in the Sredinny Range on the Kamchatka Peninsula, Russia southeast of the Ichinsky volcano."},{"name":"Mount Jarvis","slug":"mount-jarvis","category":"Mountain","country":"United States","region":"Alaska","city":null,"latitude":62.02345,"longitude":-143.62006,"description":"Mount Jarvis is an eroded shield volcano and stratovolcano in the Wrangell Mountains of eastern Alaska. It is located in Wrangell-Saint Elias National Park about 10 miles (16 km) east of the summit of Mount Wrangell. The mountain sits at the northeastern edge of the massive ice-covered shield of Wrangell, rising nearly 5,000 feet (1,500 m) above it in a spectacular series of cliffs and icefalls."},{"name":"Hallasan","slug":"hallasan","category":"Mountain","country":"South Korea","region":"Jeju Province","city":null,"latitude":33.35,"longitude":126.51667,"description":"Hallasan (Korean: 한라산) is a shield volcano comprising much of Jeju Island in South Korea. Its summit, at 1,947 m (6,388 ft), is the highest point in the country. The area around the mountain is a designated national park, named Hallasan National Park. Hallasan is commonly considered to be one of the three main mountains of South Korea, along with Jirisan and Seoraksan."},{"name":"Haleakalā","slug":"haleakal","category":"Mountain","country":"United States","region":"Maui County","city":null,"latitude":20.718,"longitude":-156.25,"description":"Haleakalā, or the East Maui Volcano, is a massive, active shield volcano that forms more than 75% of the Hawaiian Island of Maui. The western 25% of the island is formed by another volcano, Mauna Kahalawai, also referred to as the West Maui Mountains."},{"name":"Kohala","slug":"kohala","category":"Mountain","country":"United States","region":"Hawaii County","city":null,"latitude":20.08611,"longitude":-155.71722,"description":"Kohala is the oldest of five volcanoes that make up the island of Hawaii. Kohala is an estimated one million years old—so old that it experienced, and recorded, the reversal of Earth's magnetic field 780,000 years ago. It is believed to have breached sea level more than 500,000 years ago and to have last erupted 120,000 years ago."},{"name":"Mount Karthala","slug":"mount-karthala","category":"Mountain","country":"Comoros","region":"Comoros","city":null,"latitude":-11.76028,"longitude":43.35306,"description":"Mount Karthala or Karthola is an active shield volcano and the highest point of the Comoros at 2,361 m (7,746 ft) above sea level. It is the southernmost and larger of the two volcanoes forming Grande Comore island, the largest island in the nation of Comoros. The Karthala volcano is very active, having erupted more than 20 times since the 19th century."},{"name":"Baluran","slug":"baluran","category":"Mountain","country":"Indonesia","region":"East Java","city":null,"latitude":-7.84639,"longitude":114.36222,"description":"Baluran is a stratovolcano located on the island of Java. It is at the very northeast of the island and is overshadowed by its much larger neighbour Ijen. The mountain has not erupted in historical times, although it is considered to be of Holocene age."},{"name":"Misti","slug":"misti","category":"Mountain","country":"Peru","region":"Arequipa Department","city":null,"latitude":-16.29639,"longitude":-71.41056,"description":"Misti is a volcano in the southern Peruvian Andes, rising above Arequipa, Peru's second-largest city. It has a steep conical profile and two nested summit craters. The inner crater contains an active lava plug or dome, pierced by vents that emit volcanic gases. The summit reaches 5,822 metres (19,101 ft) above sea level, on the rim of the outer crater."},{"name":"Tatun Volcano Group","slug":"tatun-volcano-group","category":"Mountain","country":"Taiwan","region":null,"city":null,"latitude":25.17139,"longitude":121.555,"description":"The Tatun Volcanic Group or Tatun Volcano Group (TVG) constitutes a group of volcanoes located in northern Taiwan. It is located 15 km north of Taipei, and lies to the west of Keelung. It just adjoins the northern coast of the Taiwan island. The volcanic group was a result of episodic volcanism between 2.8 and 0.2 Ma. Research in the 2020s suggest that there were eruptions more recently than 0.2 Ma."},{"name":"Momotombo","slug":"momotombo","category":"Mountain","country":"Nicaragua","region":"León Department","city":null,"latitude":12.4247,"longitude":-86.5385,"description":"Momotombo is a stratovolcano in Nicaragua, located near the city of León. It stands on the shores of Lake Managua. An eruption of the volcano in 1610 forced inhabitants of León, in the Spanish Empire, to relocate about 48 kilometres (30 mi) west. The ruins of the city are preserved at León Viejo. It also erupted in 1886, 1905 and most recently on 30 November 2015 and 28 February 2016."},{"name":"Volcán Apoyeque","slug":"volc-n-apoyeque","category":"Mountain","country":"Nicaragua","region":"Managua Department","city":null,"latitude":12.24167,"longitude":-86.34167,"description":"Apoyeque is a pyroclastic shield, located in the Chiltepe Peninsula Natural Reserve in Nicaragua. It has a 2.8-km wide, 400-m-deep, lake-filled caldera."},{"name":"Nyamuragira","slug":"nyamuragira","category":"Mountain","country":"Democratic Republic of the Congo","region":"North Kivu","city":null,"latitude":-1.40833,"longitude":29.2,"description":"Nyamuragira, also known as Nyamulagira, is an active shield volcano in the Virunga Mountains of the Democratic Republic of the Congo, situated about 25 kilometres (16 mi) north of Lake Kivu. The name is derived from Mashi language."},{"name":"Rokatenda","slug":"rokatenda","category":"Mountain","country":"Indonesia","region":"Sikka","city":null,"latitude":-8.31667,"longitude":121.70833,"description":"Paluweh, also known as Rokatenda, is a stratovolcano that forms the small island of Palu'e, north of Flores Island in Sikka Regency in the province of East Nusa Tenggara, Indonesia. While the volcano rises about 3,000 m (9,840 ft) above the sea floor, its cone rises just 875 metres (2,871 ft) above sea level and is the highest point on the island."},{"name":"Mountain Patuha","slug":"mountain-patuha","category":"Mountain","country":"Indonesia","region":null,"city":null,"latitude":-7.16028,"longitude":107.4,"description":"Mount Patuha is a twin stratovolcano about 50 km to the southwest of Bandung in West Java, Indonesia. It is located in the Bandung District of West Java. It is one of numerous volcanoes in this area; others in the region include Mount Malabar, Mount Wayang, and Mount Papandayan."},{"name":"Ollagüe","slug":"ollag-e","category":"Mountain","country":"Chile","region":"Nor Lípez Province","city":null,"latitude":-21.3025,"longitude":-68.17917,"description":"Ollagüe or Ullawi is a massive andesite stratovolcano in the Andes on the Bolivia–Chile border, within the Antofagasta Region of Chile and the Potosi Department of Bolivia. Part of the Central Volcanic Zone of the Andes, its highest summit is 5,868 metres (19,252 ft) above sea level and features a summit crater that opens to the south."},{"name":"Mount Hagen","slug":"mount-hagen","category":"Mountain","country":"Papua New Guinea","region":null,"city":null,"latitude":-5.75,"longitude":144.03333,"description":"Mount Hagen, named after the German colonial officer Curt von Hagen (1859–1897), is the second highest volcano in Papua New Guinea and on the Australian continent, ranking behind only its neighbour Mount Giluwe which is roughly 35 kilometres (22 mi) to the south-west."},{"name":"Tutupaca","slug":"tutupaca","category":"Mountain","country":"Peru","region":"Tacna Department","city":null,"latitude":-17.02639,"longitude":-70.37167,"description":"Tutupaca is a volcano in the region of Tacna in Peru. It is part of the Peruvian segment of the Central Volcanic Zone, one of several volcanic belts in the Andes. Tutupaca consists of three overlapping volcanoes formed by lava flows and lava domes made out of andesite and dacite, which grew on top of older volcanic rocks."},{"name":"Mount Süphan","slug":"mount-s-phan","category":"Mountain","country":"Turkey","region":"Bitlis Province","city":null,"latitude":38.92983,"longitude":42.82959,"description":"Mount Süphan is a stratovolcano located in eastern Turkey, immediately north of Lake Van. It is the second highest volcano in Turkey, with an elevation of 4,058 metres, and has the third highest prominence of the Armenian Highlands, after Mount Ararat and Mount Aragats."},{"name":"Gamalama","slug":"gamalama","category":"Mountain","country":"Indonesia","region":"North Maluku","city":null,"latitude":0.80722,"longitude":127.33389,"description":"Gamalama is a near-conical active stratovolcano that comprises the entire Ternate island in Indonesia. The island lies off the western shore of Halmahera island in the north of the Maluku Islands. For centuries, Ternate was a center of Portuguese and Dutch forts for spice trade, which have accounted for thorough reports of Gamalama's volcanic activities."},{"name":"Snæfell","slug":"sn-fell","category":"Mountain","country":"Iceland","region":"Fljótsdalshreppur","city":null,"latitude":64.79717,"longitude":-15.5755,"description":"Snæfell at 1,833 m (6,014 ft) high, is an ice-capped stratovolcano located in the north-east part of Vatnajökull National Park, Iceland. While it has been dormant in the Holocene, it is now known to have had repose times of over 100,000 years between eruptions, so it cannot be assumed to be extinct."},{"name":"Mount Emmons","slug":"mount-emmons","category":"Mountain","country":"United States","region":"Aleutians East Borough","city":null,"latitude":55.3409,"longitude":-162.073,"description":"Mount Emmons is a post-caldera stratovolcano within the Emmons Lake caldera on the Alaska Peninsula within the Lake and Peninsula Borough, Alaska, United States."},{"name":"Gunung Patah","slug":"gunung-patah","category":"Mountain","country":"Indonesia","region":null,"city":null,"latitude":-4.27,"longitude":103.3,"description":"Mount Patah is the highest mountain in the Indonesian province of Bengkulu, it is a heavily forested quaternary age volcano southeast of Mount Dempo on Sumatra island, Indonesia. On 1 May 1989, a fumarole activity was observed by a pilot near the summit. The exact location of the crater, the date of its formation and its geologic relationship is uncertain."},{"name":"Mount Takachiho","slug":"mount-takachiho","category":"Mountain","country":"Japan","region":"Kagoshima Prefecture","city":null,"latitude":31.88639,"longitude":130.91889,"description":"Takachiho-no-mine (高千穂峰) or Mt. Takachiho (1573m) is a volcano in Kagoshima and Miyazaki Prefectures, Japan. It is part of Kirishima-Kinkowan National Park, where it is the second highest peak in the Kirishima range."},{"name":"Cerro del León","slug":"cerro-del-le-n","category":"Mountain","country":"Chile","region":null,"city":null,"latitude":-22.15,"longitude":-68.11667,"description":"Cerro del León is a stratovolcano located in El Loa province, Antofagasta Region, Chile. It is part of the Chilean Central Volcanic Zone and forms a volcanic lineament with neighbouring Paniri and Toconce that was active into the Holocene. Cerro del León itself was constructed in three stages by andesitic–dacitic lava flows and was subject to glacial erosion."},{"name":"Prestahnúkur","slug":"prestahn-kur","category":"Mountain","country":"Iceland","region":"Borgarbyggð","city":null,"latitude":64.6,"longitude":-20.58,"description":"The peak Prestahnúkur with a height of 1,223 m (4,012 ft), is in the Western Volcanic Zone to the west of the Highlands of Iceland to the west of Langjökull glacier, or to be more specific, to the west of Geitlandsjökull glacier, a part of the Langjökull. The volcano Prestahnúkur includes the terrain under the Geitlandsjökull glacier continuous to the peak and also includes fissure fields to its north and south."},{"name":"Zavodovski Island","slug":"zavodovski-island","category":"Mountain","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-56.3,"longitude":-27.58,"description":"Zavodovski Island is an uninhabited volcanic island in the Traversay Islands subgroup of the South Sandwich Islands, which are located southeast of South Georgia in the South Atlantic Ocean. Zavodovski is the northernmost of the South Sandwich Islands and consists of one major stratovolcano, Mount Curry, which is surrounded to the east by a plain formed by lava flows."},{"name":"Yunaska Island","slug":"yunaska-island","category":"Mountain","country":"United States","region":"Aleutians West Census Area","city":null,"latitude":52.63139,"longitude":-170.69694,"description":"Yunaska is an uninhabited island which is the largest of the Islands of Four Mountains group in the Aleutian Islands of southwestern Alaska, United States. It has a land area of 66.834 square miles according to the 2000 census."},{"name":"Grímsvötn","slug":"gr-msv-tn","category":"Mountain","country":"Iceland","region":"Þingeyjarsveit","city":null,"latitude":64.42,"longitude":-17.33,"description":"Grímsvötn is an active volcano with a fissure system located in Vatnajökull National Park, Iceland. The central volcano is completely subglacial and located under the northwestern side of the Vatnajökull ice cap. The subglacial caldera is at 64°25′N 17°20′W, at an elevation of 1,725 m (5,659 ft). Beneath the caldera is the magma chamber of the Grímsvötn volcano."},{"name":"Mount Garibaldi","slug":"mount-garibaldi","category":"Mountain","country":"Canada","region":"Squamish-Lillooet Regional District","city":null,"latitude":49.85056,"longitude":-123.00472,"description":"Mount Garibaldi is a dormant stratovolcano in the Garibaldi Ranges of the Pacific Ranges in southwestern British Columbia, Canada. It has a maximum elevation of 2,678 metres and rises above the surrounding landscape on the east side of the Cheakamus River in New Westminster Land District. In addition to the main peak, Mount Garibaldi has two named sub-peaks."},{"name":"Hekla","slug":"hekla","category":"Mountain","country":"Iceland","region":"Rangárþing ytra","city":null,"latitude":63.99222,"longitude":-19.66583,"description":"Hekla, or Hecla, is an active stratovolcano in the south of Iceland with a height of 1,491 m (4,892 ft). Hekla is one of Iceland's most active volcanoes; over 20 eruptions have occurred in and around the volcano since the year 1210. During the Middle Ages, the Icelandic Norse called the volcano the \"Gateway to Hell\" and the idea spread over much of Europe."},{"name":"Amasing Hill","slug":"amasing-hill","category":"Mountain","country":"Indonesia","region":"North Maluku","city":null,"latitude":-0.53222,"longitude":127.49806,"description":"Amasing Hill consists of three small andesitic stratovolcanoes. The volcanic complex is located on Bacan island at the west of Halmahera island, Indonesia. The two volcanoes, Cakasuanggi and Dua Saudara, were constructed in the southeast. The other volcano, Sibela Mountains, is a metamorphic complex of volcano."},{"name":"Mount Apo","slug":"mount-apo","category":"Mountain","country":"Philippines","region":"Davao Region","city":null,"latitude":6.9875,"longitude":125.27083,"description":"Mount Apo is the highest mountain peak in the Philippines, with an elevation of 2,954 meters (9,692 ft) above sea level. A large solfataric, dormant stratovolcano, it is part of the Apo-Talomo Mountain Range of Mindanao island."},{"name":"Cay","slug":"cay","category":"Mountain","country":"Chile","region":"Aysén Province","city":null,"latitude":-45.0625,"longitude":-72.98583,"description":"Cay is a stratovolcano in the South Volcanic Zone of the Andes in Aysén del General Carlos Ibáñez del Campo Region, Chile. The volcano is located 15 km northeast of the larger Maca Volcano and about 230 km of the Chile Trench at the intersection of NW-SE and NE-SW faults of the Liquiñe-Ofqui Fault Zone."},{"name":"Novarupta","slug":"novarupta","category":"Mountain","country":"United States","region":"Alaska","city":null,"latitude":58.26667,"longitude":-155.15667,"description":"Novarupta is a volcano located on the Alaska Peninsula on a slope of Trident Volcano in Katmai National Park and Preserve, about 290 miles (470 km) southwest of Anchorage. Novarupta was formed in 1912, during the largest volcanic eruption of the 20th century, in which it released 30 times the volume of magma of the 1980 eruption of Mount St. Helens."},{"name":"Kaiserstuhl","slug":"kaiserstuhl","category":"Mountain","country":"Germany","region":null,"city":null,"latitude":48.08333,"longitude":7.66667,"description":"The Kaiserstuhl is a range of hills in the state of Baden-Württemberg in southwest Germany with a maximum height of 556.6 metres (1,826 ft). It is of volcanic origin and located in the southwest of the state in the counties of Emmendingen and Breisgau-Hochschwarzwald. In terms of natural regions it is considered to be a part of the Upper Rhine Plain."},{"name":"Mount Yōtei","slug":"mount-y-tei","category":"Mountain","country":"Japan","region":"Niseko","city":null,"latitude":42.82722,"longitude":140.80639,"description":"Mount Yōtei is an active stratovolcano located in Shikotsu-Tōya National Park, Hokkaidō, Japan. It is also called Yezo Fuji or Ezo Fuji (蝦夷富士) because it resembles Mount Fuji; Ezo is an old name for the island of Hokkaido. The mountain is also known as Makkari Nupuri (マッカリヌプリ). It is one of the 100 Famous Japanese Mountains."},{"name":"Mount Chōkai","slug":"mount-ch-kai","category":"Mountain","country":"Japan","region":"Sakata","city":null,"latitude":39.09917,"longitude":140.04889,"description":"Mount Chōkai is an active volcano located on the border of Akita and Yamagata in the Tōhoku region of Japan, and is 2,236 m (7,336 ft) tall. Because of its (roughly) symmetrical shape and massive size, it is also variously known as Dewa Fuji (出羽富士), Akita Fuji (秋田富士) or Shōnai Fuji (庄内富士) depending on the location of the viewer."},{"name":"Mount Iwate","slug":"mount-iwate","category":"Mountain","country":"Japan","region":"Hachimantai","city":null,"latitude":39.8525,"longitude":141.00111,"description":"Mount Iwate is a stratovolcano complex in the Ōu Mountains of western Iwate Prefecture, in the Tōhoku region of northern Honshū, Japan. With an elevation of 2,038 metres (6,686 ft), it is the highest in Iwate Prefecture. It is included as one of the 100 famous mountains in Japan, a book composed in 1964 by mountaineer and author Kyūya Fukada."},{"name":"Hoherodskopf","slug":"hoherodskopf","category":"Mountain","country":"Germany","region":"Hesse","city":null,"latitude":50.511,"longitude":9.227,"description":"Hoherodskopf is a mountain peak in the Vogelsberg of Hesse, Germany. It is a Miocene basaltic extinct volcano. A telecommunications tower is sited on top of the peak."},{"name":"Mount Bosavi","slug":"mount-bosavi","category":"Mountain","country":"Papua New Guinea","region":"Southern Highlands Province","city":null,"latitude":-6.61417,"longitude":142.82667,"description":"Mount Bosavi is a mountain in the Southern Highlands province, Papua New Guinea. It is the collapsed cone of an extinct volcano on the Great Papuan Plateau, part of the Kikori River basin. The crater is approximately 4 km wide and 1 km deep; it is home to a number of endemic species."},{"name":"Mount Scenery","slug":"mount-scenery","category":"Mountain","country":"Netherlands","region":"Saba","city":null,"latitude":17.635,"longitude":-63.23917,"description":"Mount Scenery is a dormant volcano in the Caribbean Netherlands. Its lava dome forms the summit of the Saba island stratovolcano. At an elevation of 870 m (2,854 ft), it is the highest point in both the Kingdom of the Netherlands, and, since the dissolution of the Netherlands Antilles on 10 October 2010, the highest point in the Netherlands proper."},{"name":"Mount Hasan","slug":"mount-hasan","category":"Mountain","country":"Turkey","region":"Aksaray Province","city":null,"latitude":38.12652,"longitude":34.16511,"description":"Mount Hasan is a volcano in Anatolia, Turkey. It has two summits, the 3,069 metres (10,069 ft) high eastern Small Hasandağ and the 3,253 metres (10,673 ft) high Big Hasandağ, and rises about 1 kilometre (0.62 mi) above the surrounding terrain. It consists of various volcanic deposits, including several calderas, and its activity has been related to the presence of several faults in the area and to regional tectonics."},{"name":"Nerother Kopf","slug":"nerother-kopf","category":"Mountain","country":"Germany","region":"Rhineland-Palatinate","city":null,"latitude":50.1944,"longitude":6.76083,"description":"The Nerother Kopf is the conical hill of an extinct volcano near Neroth in the Eifel mountains. It is 651.7 m above sea level (NHN) and situated in the county of Vulkaneifel in the German state of Rhineland-Palatinate."},{"name":"Mount Vesuvius","slug":"mount-vesuvius","category":"Mountain","country":"Italy","region":"Metropolitan City of Naples","city":null,"latitude":40.82261,"longitude":14.42919,"description":"Mount Vesuvius is a somma–stratovolcano located on the Gulf of Naples in Campania, Italy, about 9 km (5.6 mi) east of Naples and a short distance from the shore. It is one of several volcanoes forming the Campanian volcanic arc. Vesuvius consists of a large cone partially encircled by the steep rim of a summit caldera, resulting from the collapse of an earlier, much higher structure."},{"name":"Mayon Volcano","slug":"mayon-volcano","category":"Mountain","country":"Philippines","region":"Bicol Region","city":null,"latitude":13.25667,"longitude":123.685,"description":"Mayon, also known as Mount Mayon and Mayon Volcano, is an active stratovolcano in the province of Albay in Bicol, Philippines. A popular tourist destination, it is renowned for its \"perfect cone\" owing to its symmetric conical shape, and is regarded as sacred in Philippine mythology."},{"name":"Sangay volcano","slug":"sangay-volcano","category":"Mountain","country":"Ecuador","region":"Morona-Santiago Province","city":null,"latitude":-2.0025,"longitude":-78.34083,"description":"Sangay is an active stratovolcano in central Ecuador. It exhibits mostly strombolian activity. Geologically, Sangay marks the southern boundary of the Northern Volcanic Zone, and its position straddling two major pieces of crust accounts for its high level of activity."},{"name":"Doña Juana","slug":"do-a-juana","category":"Mountain","country":"Colombia","region":null,"city":null,"latitude":1.47075,"longitude":-76.9249,"description":"Doña Juana is a stratovolcano, located within the Doña Juana-Cascabel Volcanic Complex National Natural Park in Nariño, Colombia."},{"name":"Teide","slug":"teide","category":"Mountain","country":"Spain","region":"Santa Cruz de Tenerife Province","city":null,"latitude":28.27264,"longitude":-16.64361,"description":"Teide or Mount Teide is an active stratovolcano on the Spanish island of Tenerife, part of the Canary Islands. Its summit is the highest point in Spain and the highest of any island in the Atlantic Ocean."},{"name":"Lake Erie","slug":"lake-erie","category":"Lake","country":"Canada","region":"Michigan","city":null,"latitude":42.25,"longitude":-80.99972,"description":"Lake Erie is the fourth-largest lake by surface area of the five Great Lakes in North America and the eleventh-largest globally. It is the southernmost, shallowest, and smallest by volume of the Great Lakes and also has the shortest average water residence time. At its deepest point, Lake Erie is 210 feet (64 m) deep, making it the only Great Lake whose deepest point is above sea level."},{"name":"Lake Kivu","slug":"lake-kivu","category":"Lake","country":"Democratic Republic of the Congo","region":"city hall","city":null,"latitude":-1.85306,"longitude":29.13528,"description":"Lake Kivu is one of the African Great Lakes. It lies on the border between the Democratic Republic of the Congo and Rwanda, and is in the Albertine Rift, the western branch of the East African Rift. Lake Kivu empties into the Ruzizi River, which flows southwards into Lake Tanganyika."},{"name":"Stora Le","slug":"stora-le","category":"Lake","country":"Norway","region":"Aremark Municipality","city":null,"latitude":59.16167,"longitude":11.87917,"description":"Stora Le or Lesjön in Swedish and Store Le in Norwegian is a lake in Dalsland, Sweden, the northern end of which proceeds into Norway and into Värmland, where it continues as Lake Foxen."},{"name":"Zenssee","slug":"zenssee","category":"Lake","country":"Germany","region":null,"city":null,"latitude":53.19694,"longitude":13.34111,"description":"Zenssee is a lake in Uckermark, Brandenburg, Germany. At an elevation of, its surface area is 1.1167 km2. It is located in the town of Lychen."},{"name":"Lake İznik","slug":"lake-i-znik","category":"Lake","country":"Turkey","region":"İznik","city":null,"latitude":40.44361,"longitude":29.50833,"description":"Lake İznik is a freshwater lake in the Province of Bursa, Turkey. It is around 32 km (20 mi) in length and 10 km in width with a maximum depth of about 80 m. The town of Iznik lies at its eastern end. The lake's Ancient Greek name was Askania (Ἀσκανία); the Latin name was Ascania."},{"name":"Saimaa","slug":"saimaa","category":"Lake","country":"Finland","region":"South Karelia","city":null,"latitude":61.25,"longitude":28.25,"description":"Saimaa is a lake located in the Finnish Lakeland area in southeastern Finland. With a surface area of approximately 4,279 square kilometres (1,652 sq mi), it is the largest lake in Finland, and the fourth-largest natural freshwater lake in Europe."},{"name":"Zethner See","slug":"zethner-see","category":"Lake","country":"Germany","region":"Mecklenburgische Seenplatte District","city":null,"latitude":53.20922,"longitude":12.79306,"description":"Zethner See is a lake in the Mecklenburgische Seenplatte district in Mecklenburg-Vorpommern, Germany. At an elevation of 58.5 m, its surface area is 0.35 km2."},{"name":"Ziegeleisee","slug":"ziegeleisee","category":"Lake","country":"Germany","region":"Reinickendorf","city":null,"latitude":52.61667,"longitude":13.33333,"description":"Ziegeleisee is a lake in Berlin, Germany. At an elevation of 35 m (115 ft), its surface area is 4.7 ha."},{"name":"Zierker See","slug":"zierker-see","category":"Lake","country":"Germany","region":"Neustrelitz","city":null,"latitude":53.36151,"longitude":13.03596,"description":"Zierker See is a lake in the Mecklenburg Lake District, in Germany. It is situated in the district of Mecklenburgische Seenplatte of the state of Mecklenburg-Vorpommern. The town of Neustrelitz lies at the northern end of the lake."},{"name":"Ziernsee","slug":"ziernsee","category":"Lake","country":"Germany","region":"Priepert","city":null,"latitude":53.20819,"longitude":13.07699,"description":"Ziernsee is a lake in the Mecklenburg Lake District, in Germany. Whilst most of the lake is in the district of Mecklenburgische Seenplatte in the state of Mecklenburg-Vorpommern, a portion of its southern shore is in the state of Brandenburg."},{"name":"Lake Chukchagirskoye","slug":"lake-chukchagirskoye","category":"Lake","country":"Russia","region":"Khabarovsk Krai","city":null,"latitude":51.98778,"longitude":136.57972,"description":"Lake Chukchagir is a large freshwater lake in Khabarovsk Krai, Russia. It has an area of 366 km2 (141 sq mi) and a maximum depth of 6 m (20 ft). There are no permanent settlements on the shores of the lake."},{"name":"Zieskensee","slug":"zieskensee","category":"Lake","country":"Germany","region":"Mecklenburgische Seenplatte District","city":null,"latitude":53.52888,"longitude":13.07871,"description":"Zieskensee is a lake in the Mecklenburgische Seenplatte district in Mecklenburg-Vorpommern, Germany. It is 800m long and up to 250m wide. The deepest point is 11m. It has 50m of sandy beach on its western shore. At an elevation of 46 m, its surface area is 0.172 km2."},{"name":"Metelys","slug":"metelys","category":"Lake","country":"Lithuania","region":"Lazdijai District Municipality","city":null,"latitude":54.2975,"longitude":23.77167,"description":"Lake Metelys is located in southern Lithuania's Alytus County. The lake, covering 1,292 hectares, has a maximum depth of 15 metres. It lies within the boundaries of Meteliai Regional Park. Lake Metelys formed from melted ice lump."},{"name":"Ammersee","slug":"ammersee","category":"Lake","country":"Germany","region":"Ammersee","city":null,"latitude":48.0,"longitude":11.11667,"description":"Ammersee is a Zungenbecken lake in Upper Bavaria, Germany, southwest of Munich between the towns of Herrsching and Dießen am Ammersee. With a surface area of approximately 47 square kilometres (18 sq mi), it is the sixth largest lake in Germany. The lake is at an elevation of 533 metres (1,749 ft), and has a maximum depth of 81 metres (266 ft)."},{"name":"Popradské pleso","slug":"popradsk-pleso","category":"Lake","country":"Slovakia","region":"Poprad District","city":null,"latitude":49.1531,"longitude":20.0803,"description":"Popradské pleso is a mountain lake of glacial origin located in the High Tatras, Slovakia. It is situated right on the Tatranská magistrála hiking path, at an altitude of 1,494 metres (4,902 ft)."},{"name":"Imandra","slug":"imandra","category":"Lake","country":"Russia","region":"Murmansk Oblast","city":null,"latitude":67.5542,"longitude":33.0484,"description":"Imandra is a lake in the south-western part of the Kola Peninsula in Murmansk Oblast, Russia, slightly beyond the Arctic Circle. It is located 127 m above sea level; its area is about 876 km2, maximum depth is 67 m. The shape of the shore line is complicated. There are a number of islands and the largest, Erm Island, measures 26 km2."},{"name":"Dickson Lake","slug":"dickson-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.3975,"longitude":-125.08583,"description":"Dickson Lake is a lake located north of Great Central Lake in Newcastle Land District, British Columbia. Robert Brown in 1864 on the Vancouver Island Exploring Expedition named the lake after Dr. James Dickson."},{"name":"Jack Shark Lake","slug":"jack-shark-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.6708,"longitude":-125.489,"description":"Jack Shark Lake is a lake located on Vancouver Island on the west side of Augerpoint Mountain west of Mount Albert Edward in Strathcona Provincial Park."},{"name":"Consinka Lake","slug":"consinka-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":48.95,"longitude":-124.967,"description":"Consinka Lake is a lake located on Vancouver Island is an expansion of Consinka Creek east of San Mateo Bay."},{"name":"Gun Lake","slug":"gun-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":50.8667,"longitude":-122.883,"description":"Gun Lake, often spelled Gunn Lake and also known as Big Gun Lake, is a lake and unincorporated community in the Bridge River Country of the West-Central Interior of British Columbia, Canada, located 5 miles northwest of the community of Gold Bridge."},{"name":"Bolton Lake","slug":"bolton-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.7831,"longitude":-126.417,"description":"Bolton Lake is a lake in the Pacific Ocean drainage basin on the west coast of Vancouver Island in Strathcona Regional District, British Columbia, Canada. It is about 1,200 metres (3,937 ft) long and 350 metres (1,148 ft) wide, and lies at an elevation of 127 metres (417 ft). The primary outflow is an unnamed creek to Nesook Bay on the Tlupana Inlet of the Pacific Ocean."},{"name":"Fourth Lake","slug":"fourth-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.05861,"longitude":-124.42,"description":"Fourth Lake is a lake located on Vancouver Island at the expansion of Sadie Creek south of the Nanaimo River. It is one of the Nanaimo Lakes."},{"name":"Emerald Lake","slug":"emerald-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":51.444,"longitude":-116.531,"description":"Emerald Lake is a freshwater lake in Yoho National Park, British Columbia, Canada. Yoho National Park is one of the four contiguous national parks in Canada's Rocky Mountains, along the boundary of British Columbia and Alberta Provinces."},{"name":"Howard Lake","slug":"howard-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":51.8141,"longitude":-120.802,"description":"Howard Lake is a lake in British Columbia, Canada. Situated in the hills above Canim Lake, the lake is located at a high altitude and is surrounded by dense forest. It is located approximately 50 km northeast of 100 Mile House."},{"name":"Charlie Lake","slug":"charlie-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":56.3248,"longitude":-120.975,"description":"Charlie Lake is a lake in north-eastern British Columbia, Canada, situated 8 km (5.0 mi) west from Fort St. John, along the Alaska Highway. The lake provides the water supply for the city of Fort St. John. The Charlie Lake Formation, a stratigraphical unit of the Western Canadian Sedimentary Basin is named for the lake."},{"name":"Duck Lake","slug":"duck-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.1414,"longitude":-124.657,"description":"Duck Lake is a lake located on Vancouver Island east of Lizard Lake on the south side of upper China Creek, south east of Port Alberni, The lake lies at an elevation of 928 metres (3,045 ft) above sea level in the China Creek Community Watershed."},{"name":"Hobson Lake","slug":"hobson-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":52.54444,"longitude":-120.31389,"description":"Hobson Lake is the uppermost lake on the Clearwater River in east-central British Columbia, Canada. Hobson Lake is one of the six major lakes in Wells Gray Provincial Park."},{"name":"Francis Lake","slug":"francis-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":48.95389,"longitude":-124.69889,"description":"Francis Lake is a lake located on Vancouver Island west of Little Nitinat River and 40 km south of Port Alberni."},{"name":"Helen Lake","slug":"helen-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.31139,"longitude":-125.19111,"description":"Helen Lake is a lake located on Vancouver Island north of the head of Taylor Arm, Sproat Lake."},{"name":"Kammat Lake","slug":"kammat-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.1667,"longitude":-124.567,"description":"Kammat Lake is a lake located on Vancouver Island at the head of Kammat Creek south of Cameron River."},{"name":"Krakower See","slug":"krakower-see","category":"Lake","country":"Germany","region":"Rostock District","city":null,"latitude":53.63111,"longitude":12.2975,"description":"Krakower See is a lake in the Rostock district in Mecklenburg-Vorpommern, Germany. At an elevation of 47.6 m, its surface area is 15.07 km2."},{"name":"Lac de l'Abbaye","slug":"lac-de-labbaye","category":"Lake","country":"France","region":"Jura","city":null,"latitude":46.52996,"longitude":5.91236,"description":"Lac de l'Abbaye, also known as Lac de Grandvaux or Lac de la Grande Rivière, is a glacial lake in the commune of Grande-Rivière, in the Jura department of France. It is located at an altitude of 879 m (2,884 ft), on the edge of Jura Mountains, 7 km (4.3 mi) south of Saint-Laurent-en-Grandvaux."},{"name":"Lake Chaubunagungamaug","slug":"lake-chaubunagungamaug","category":"Lake","country":"United States","region":"Webster","city":null,"latitude":42.0425,"longitude":-71.84333,"description":"Lake Chaubunagungamaug, also known as Webster Lake, is a lake in the New England town of Webster, Massachusetts. The lake is located near the border with Connecticut and has a surface area of 1,442 acres (2.253 mi2)."},{"name":"Lake Ontario","slug":"lake-ontario","category":"Lake","country":"Canada","region":"New York","city":null,"latitude":43.72889,"longitude":-78.10639,"description":"Lake Ontario is one of the five Great Lakes of North America. It is bounded on the north, west, and southwest by the Canadian province of Ontario, and on the south and east by the U.S. state of New York. The Canada–United States border spans the centre of the lake. On the Canadian side, the major cities are Kingston, Mississauga, Toronto, Hamilton, and St. Catharines."},{"name":"Lake Champlain","slug":"lake-champlain","category":"Lake","country":"Canada","region":null,"city":null,"latitude":44.53,"longitude":-73.33,"description":"Lake Champlain is a large natural freshwater lake in North America. With a length of 107 mi (172 km) and surface area over 500 sq mi (1,295 km2), it lies mostly between the U.S. states of New York and Vermont, but also extends north into the Canadian province of Quebec."},{"name":"Tornowsee","slug":"tornowsee","category":"Lake","country":"Germany","region":"Brandenburg","city":null,"latitude":53.02668,"longitude":12.79609,"description":"Lake Tornow is a lake in Ruppin Switzerland in Brandenburg, Germany. It is located east of Kunsterspring and south of Binenwalde and not far from the residential area of Tornow. It lies completely within the municipal boundaries of Neuruppin. The lake is a state waterway. It is 2.18 km (1.35 mi) wide and 1.57 km (0.98 mi) long, with an area of 124 ha and a maximum depth of 12 m (39 ft)."},{"name":"Lake Idro","slug":"lake-idro","category":"Lake","country":"Italy","region":"Province of Brescia","city":null,"latitude":45.7745,"longitude":10.511,"description":"Lake Idro is an Italian prealpine lake of glacial origin situated largely within the Province of Brescia (Lombardy) and in part in Trentino."},{"name":"Lago di Annone","slug":"lago-di-annone","category":"Lake","country":"Italy","region":null,"city":null,"latitude":45.81194,"longitude":9.34944,"description":"Lake Annone, also called Lake Oggiono, is a lake in the Province of Lecco, Lombardy, Italy. It borders the municipalities of Annone di Brianza, Suello, Civate, Galbiate and Oggiono. It covers 5.7 square kilometres."},{"name":"Lake of Pusiano","slug":"lake-of-pusiano","category":"Lake","country":"Italy","region":"Province of Como","city":null,"latitude":45.80194,"longitude":9.27083,"description":"Lake Pusiano, also called Casletto or Eupili, is a lake located between the provinces of Como and Lecco, in Brianza, Lombardy."},{"name":"Lake Coleridge","slug":"lake-coleridge","category":"Lake","country":"New Zealand","region":"Selwyn District","city":null,"latitude":-43.291,"longitude":171.499,"description":"Lake Coleridge is in inland Canterbury, New Zealand's South Island. It is located 35 kilometres (22 mi) northwest of Methven and has a surface area of 47 square kilometres (18 sq mi). The lake is situated in an over-deepened valley formed by a glacier over 20,000 years ago in the Pleistocene era. It currently has no natural outflows. There is a small settlement at the lake."},{"name":"Caspian Sea","slug":"caspian-sea","category":"Lake","country":"Russia","region":null,"city":null,"latitude":42.0,"longitude":50.5,"description":"The Caspian Sea is the world's largest inland body of water, also described as the world's largest lake and usually referred to as a full-fledged sea. An endorheic basin, it is situated in both Europe and Asia: east of the Caucasus, west of the broad steppe of Central Asia, south of the fertile plains of Southern Russia in Eastern Europe, and north of the mountainous Iranian Plateau."},{"name":"Lake Albert","slug":"lake-albert","category":"Lake","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":1.68333,"longitude":30.91667,"description":"Lake Albert, originally known as Lake Mwitanzige by the Banyoro, Nam Ovoyo Bonyo by the Alur, and temporarily as Lake Mobutu Sese Seko, is a lake located in Uganda and the Democratic Republic of the Congo. It is Africa's sixth-largest lake and the second biggest of Uganda's Great Lakes."},{"name":"Lake Michigan","slug":"lake-michigan","category":"Lake","country":"United States","region":"Michigan","city":null,"latitude":44.00787,"longitude":-86.75645,"description":"Lake Michigan is one of the five Great Lakes of North America. It is the second-largest of the Great Lakes by volume and depth after Lake Superior and the third-largest by surface area, after Lake Superior and Lake Huron."},{"name":"Lake Huron","slug":"lake-huron","category":"Lake","country":"Canada","region":"Michigan","city":null,"latitude":44.59258,"longitude":-82.75629,"description":"Lake Huron is one of the five Great Lakes of North America. It is shared on the north and east by the Canadian province of Ontario and on the south and west by the U.S. state of Michigan. The name of the lake is derived from early French explorers who named it for the indigenous people they knew as Huron (Wyandot) inhabiting the region."},{"name":"Lake Chad","slug":"lake-chad","category":"Lake","country":"Chad","region":"Far North","city":null,"latitude":13.09789,"longitude":14.53381,"description":"Lake Chad is an endorheic freshwater lake located at the junction of four countries: Nigeria, Niger, Chad, and Cameroon, in western and central Africa respectively, with a catchment area in excess of 1,000,000 km2 (390,000 sq mi). It is an important wetland ecosystem in West-Central Africa. The lake is rich in aquatic resources and is one of the important freshwater fish-producing areas in Africa."},{"name":"Frillen-See","slug":"frillen-see","category":"Lake","country":"Germany","region":"Inzell","city":null,"latitude":47.76583,"longitude":12.81722,"description":"Frillensee is a lake near Inzell in the Chiemgau Alps of Bavaria, Germany. It lies at an elevation of about 922–923 metres and is regarded as the coldest lake in Germany and one of the coldest lakes in Central Europe. The lake covers 4.30 hectares and is about 280 metres long and 165 metres wide."},{"name":"Zeller See","slug":"zeller-see","category":"Lake","country":"Germany","region":"Baden-Württemberg","city":null,"latitude":47.71917,"longitude":8.98583,"description":"The Zeller See is part of the Lower Lake, the lower part of Lake Constance. It lies in the bay of Radolfzell, and between the peninsula of Mettnau to the north and the peninsula of Höri to the south. To the west it is bounded by the ried of the Radolfzeller Aach."},{"name":"Lake Zell","slug":"lake-zell","category":"Lake","country":"Austria","region":"Zell am See","city":null,"latitude":47.31667,"longitude":12.8,"description":"Lake Zell is a small freshwater lake in the Austrian Alps. It takes its name from the city of Zell am See, which is located on a small delta protruding into the lake. The lake is 4 kilometres (2.5 mi) long and 1.5 kilometres (0.93 mi) across at its widest. It is up to 73 metres deep and at an elevation of 750 metres above sea level."},{"name":"Vättern","slug":"v-ttern","category":"Lake","country":"Sweden","region":"Ödeshög Municipality","city":null,"latitude":58.4,"longitude":14.6,"description":"Vättern is the second-largest lake in Sweden, after Vänern, and the sixth-largest lake in Europe. It is a long, finger-shaped body of fresh water in south central Sweden, to the southeast of Vänern, pointing at the tip of Scandinavia."},{"name":"Bacon Lake","slug":"bacon-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.9667,"longitude":-125.633,"description":"Bacon Lake is a lake located in British Columbia, Canada, located north of Upper Campbell Lake. The name is thought to be for H.N. Bacon, who was \"guide for the province's exploratory survey of Strathcona Park\"."},{"name":"Horne Lake","slug":"horne-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.3333,"longitude":-124.7,"description":"Horne Lake is a lake in Canada's central Vancouver Island, situated between Mount Mark to the north and Mount Horne and Mount Wesley to the south. Its size is approximately 815 hectares."},{"name":"Goldberger See","slug":"goldberger-see","category":"Lake","country":"Germany","region":"Ludwigslust-Parchim District","city":null,"latitude":53.61111,"longitude":12.125,"description":"Goldberger See is a lake in Ludwigslust-Parchim, Mecklenburg-Vorpommern, Germany. At an elevation of 46.5 m, its surface area is 7.7 km²."},{"name":"Cass Lake","slug":"cass-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.0361,"longitude":-124.963,"description":"Cass Lake is a lake located on Vancouver Island on the west side Alberni Inlet, south of the Nahmint River."},{"name":"Beaufort Lake","slug":"beaufort-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.5,"longitude":-125.05,"description":"Beaufort Lake is a small lake located south east of southern end of Comox Lake. This lake is a widening of Beaufort Creek, which in turn takes its name from the Beaufort Range."},{"name":"Lake Errock","slug":"lake-errock","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.2267,"longitude":-122.011,"description":"Lake Errock is a lake at the community of the same name, located between Chehalis and Deroche in the Upper Fraser Valley of the Lower Mainland region of British Columbia, Canada. It lies southwest of Harrison Bay, a sidewater of the Harrison River west of Chehalis, and is separated from the nearby Fraser River by a large rocky hill."},{"name":"Carter Lake","slug":"carter-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.62417,"longitude":-125.71111,"description":"Carter Lake is a lake located on Vancouver Island south of Schjelderup Lake and south east of Golden Hinde in Strathcona Provincial Park."},{"name":"Horsefly Lake","slug":"horsefly-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":52.3833,"longitude":-121.167,"description":"Horsefly Lake is a lake in the eastern Cariboo region of the Central Interior of British Columbia, Canada. With a maximum depth of 632 feet (193 m), it is one of the Cariboo's deepest lakes."},{"name":"Kildonan Lake","slug":"kildonan-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.0333,"longitude":-124.967,"description":"Kildonan Lake is a lake located on Vancouver Island as an expansion of Cass Creek, north east of Uchucklesit Inlet."},{"name":"Junior Lake","slug":"junior-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.25,"longitude":-124.683,"description":"Junior Lake is a lake located on Vancouver Island north of Great Central Lake, north east of Oshinow Lake."},{"name":"Elk Lake","slug":"elk-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":48.52972,"longitude":-123.39861,"description":"Elk Lake is a large lake located in Elk/Beaver Lake Regional Park in Saanich, British Columbia. Elk Lake and Beaver Lake are actually one lake as a shallow channel connects them. Elk/Beaver lake was known as the \"Freshwater Playground of Victoria\" in its heyday, the 1930s and 1940s."},{"name":"Elsay Lake","slug":"elsay-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.417,"longitude":-122.939,"description":"Elsay Lake is a lake 15 kilometres (9.3 mi) North East of the City of North Vancouver, located near the Centre of Mount Seymour Provincial Park in the District of North Vancouver, British Columbia. Originally named Mystery Lake and still known to some as such. It has subsequently been renamed Lake Elsay, after nearby Elsay Creek."},{"name":"Divers Lake","slug":"divers-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.7333,"longitude":-125.358,"description":"Divers Lake is a lake on Vancouver Island, British Columbia, Canada on the north side of Forbidden Plateau in Strathcona Provincial Park."},{"name":"Greig Lake","slug":"greig-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.65056,"longitude":-125.62694,"description":"Greig Lake is a lake on Vancouver Island west of Buttle Lake in Strathcona Provincial Park."},{"name":"Ilthpaya Lake","slug":"ilthpaya-lake","category":"Lake","country":"Canada","region":"British Columbia","city":null,"latitude":49.1167,"longitude":-125.617,"description":"Ilthpaya Lake is a lake located on Vancouver Island west of Clayoquot Arm and north of Kennedy River."},{"name":"Lake Winnipeg","slug":"lake-winnipeg","category":"Lake","country":"Canada","region":"Manitoba","city":null,"latitude":52.11667,"longitude":-97.25,"description":"Lake Winnipeg is a 24,514-square-kilometre (9,465-square-mile) lake in North America, in the Canadian province of Manitoba. Its southern end is about 55 kilometres north of the namesake city, Winnipeg. It is the 12th largest lake on Earth, Canada's sixth-largest freshwater lake, and the third-largest freshwater lake contained entirely within Canada. It is relatively shallow, with a mean depth of 12 metres [39 feet]."},{"name":"Müritz","slug":"m-ritz","category":"Lake","country":"Germany","region":"Mecklenburgische Seenplatte District","city":null,"latitude":53.41667,"longitude":12.68333,"description":"The Müritz is a lake in Mecklenburg-Vorpommern, northern Germany. Its area is 117 km2 (45 sq mi), which makes it the second largest lake in Germany and the largest lake located entirely within German territory."},{"name":"Chiemsee","slug":"chiemsee","category":"Lake","country":"Germany","region":"Chiemsee","city":null,"latitude":47.89,"longitude":12.47,"description":"Chiemsee is a freshwater lake in Bavaria, Germany, near Rosenheim. It is often called \"the Bavarian Sea\". The rivers Tiroler Achen and Prien flow into the lake from the south, and the river Alz flows out towards the north. The Alz flows into the Inn which then merges with the Danube. The Chiemsee is divided into the bigger, north section, in the northeast, called Weitsee, and the Inselsee, in the southwest."},{"name":"Lake Poteriteri","slug":"lake-poteriteri","category":"Lake","country":"New Zealand","region":"Southland Region","city":null,"latitude":-46.02,"longitude":167.114,"description":"Lake Poteriteri is the southernmost of the large lakes in Fiordland National Park in New Zealand's South Island. Only Lakes Hakapoua and Innes lie further south on the southern of New Zealand's two main islands. It is located 40 kilometres (25 mi) to the west of the town of Tuatapere."},{"name":"Lake Waikaremoana","slug":"lake-waikaremoana","category":"Lake","country":"New Zealand","region":"Hawke's Bay Region","city":null,"latitude":-38.76667,"longitude":177.08333,"description":"Lake Waikaremoana is located in Te Urewera in the North Island of New Zealand, 60 kilometres (37 mi) northwest of Wairoa and 80 kilometres (50 mi) west-southwest of Gisborne. It covers an area of 54 square kilometres (21 sq mi). From the Māori Waikaremoana translates as 'sea of rippling waters'."},{"name":"Lake Brunner / Moana","slug":"lake-brunner-moana","category":"Lake","country":"New Zealand","region":"Grey District","city":null,"latitude":-42.615,"longitude":171.45,"description":"Lake Brunner is the largest lake in the West Coast Region of New Zealand, located 31 km (19 mi) southeast of Greymouth. The main settlement, Moana, is on its northern shore. It is an important settlement and waystation for local Māori. The first Europeans in the area were loggers, and sawmills were an important early industry."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 2: % places added', added;
end $$;

-- batch 3 of 6: 150 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Lake Trasimeno","slug":"lake-trasimeno","category":"Lake","country":"Italy","region":"province of Perugia","city":null,"latitude":43.14,"longitude":12.1,"description":"Lake Trasimene, is a lake in the province of Perugia, in the Umbria region of Italy on the border with Tuscany. The lake has a surface area of 128 km2 (49.4 sq mi), making it the fourth largest in Italy, slightly smaller than Lake Como. Only two minor streams flow directly into the Lake and none flows out."},{"name":"Dobbertiner See","slug":"dobbertiner-see","category":"Lake","country":"Germany","region":"Ludwigslust-Parchim District","city":null,"latitude":53.61389,"longitude":12.06889,"description":"The Dobbertiner See is a lake within the Sternberger Seenlandschaft in Mecklenburg-Vorpommern, Germany. It is situated immediately to the south of the municipality of Dobbertin, and is about 200 kilometres (120 mi) northwest of Berlin."},{"name":"Lake Superior","slug":"lake-superior","category":"Lake","country":"Canada","region":"Michigan","city":null,"latitude":47.52882,"longitude":-87.76002,"description":"Lake Superior is a lake in central North America. The northernmost, westernmost, and highest of the Great Lakes, Lake Superior straddles the Canada–United States border with the Canadian province of Ontario to the north and east and the U.S. states of Minnesota to the west and Michigan and Wisconsin to the south."},{"name":"Sasthamcotta Lake","slug":"sasthamcotta-lake","category":"Lake","country":"India","region":"Kerala","city":null,"latitude":9.03,"longitude":76.63,"description":"Sasthamcotta Lake or Sasthamkotta Lake, also categorized as a wetland, is the largest fresh water lake in Kerala, a state of India on the south of the West Coast. The lake is named after the ancient Sastha temple located on its bank. It meets the drinking water needs of half million people of the Quilon district and also provides fishing resources."},{"name":"Lai da Nalps","slug":"lai-da-nalps","category":"Lake","country":"Switzerland","region":"Tujetsch","city":null,"latitude":46.6325,"longitude":8.76333,"description":"Lai da Nalps is a reservoir in the municipality of Tujetsch, Grisons, Switzerland. It has a capacity of 45 million m³ and a surface area of 0.91 km². The reservoir is connected to Lai da Sontga Maria and Lai da Curnera in neighboring valleys."},{"name":"Kandawgyi Lake","slug":"kandawgyi-lake","category":"Lake","country":"Myanmar","region":null,"city":null,"latitude":16.79549,"longitude":96.16656,"description":"Kandawgyi Lake is one of two major lakes in Yangon, Myanmar. Located east of the Shwedagon Pagoda, the lake is artificial; water from Inya Lake is channeled through a series of pipes to Kandawgyi Lake. It was created to provide a clean water supply to the city during the British colonial administration. It is approximately 3 miles (4.8 km) in circumference, and has a depth of 20–45 inches (510–1,140 mm)."},{"name":"Lake Salagou","slug":"lake-salagou","category":"Lake","country":"France","region":"Hérault","city":null,"latitude":43.65912,"longitude":3.36813,"description":"Lake Salagou is a reservoir formed by the Salagou Dam. It is located in the central part of the Hérault department in southern France, on the Salagou river, a tributary of the Lergue River, which in turn flows into the Hérault River."},{"name":"Lago Nicoletti","slug":"lago-nicoletti","category":"Lake","country":"Italy","region":"Free Municipal Consortium of Enna","city":null,"latitude":37.61,"longitude":14.34,"description":"Nicoletti Lake is a lake in the Province of Enna, Sicily, Italy. It was constructed in the early 1970s by damming the Dittaino river. At an elevation of 388 m, its surface area is 1.8 km² and it has an average depth of 12.9 m."},{"name":"lake Arnen","slug":"lake-arnen","category":"Lake","country":"Switzerland","region":"Gsteig bei Gstaad","city":null,"latitude":46.38821,"longitude":7.21678,"description":"Arnensee is a lake in canton of Bern, Switzerland. The lake in the municipality of Gsteig is used as a reservoir by Romande Energie. The dam was built in 1942. Its volume is 10.5 million m3 and surface area 0.456 km2."},{"name":"Llyn Eigiau","slug":"llyn-eigiau","category":"Lake","country":"United Kingdom","region":"Conwy County Borough","city":null,"latitude":53.18222,"longitude":-3.86472,"description":"Llyn Eigiau is a lake on the edge of the Carneddau range of mountains in Snowdonia, Conwy, Wales. The name Eigiau is thought to refer to the shoals of fish which once lived here. Early maps refer to it as Llynyga. It is thought that a small number of Arctic char exist in the lake after they were transferred here from Llyn Peris, and certainly it is one of the few lakes in Wales to have its own natural brown trout."},{"name":"Lac de Pérolles","slug":"lac-de-p-rolles","category":"Lake","country":"Switzerland","region":"Canton of Fribourg","city":null,"latitude":46.79592,"longitude":7.1626,"description":"Lac de Pérolles, a reservoir formed by Maigrauge Dam, is a reservoir on the Saane/Sarine river at Fribourg, in western Switzerland. Its surface area is 0.35 square kilometres. The dam was built in 1872, and its height was increased by 2.5 metres (8.2 ft) in 1910. The watershed is 1,250 square kilometres (480 sq mi). The Maigrauge Dam has a gated spillway."},{"name":"Lac des Settons","slug":"lac-des-settons","category":"Lake","country":"France","region":"Château-Chinon (Ville)","city":null,"latitude":47.18131,"longitude":4.06389,"description":"The Lac des Settons is a reservoir in the Nièvre department, France, with a surface area of 3.67 km2 (1.42 sq mi). Supplied mainly by the River Cure, it is situated in the heart of Morvan Regional Natural Park. The lake is found south of the town Montsauche-les-Settons. It is one of the Great Lakes of the Morvan."},{"name":"Lake Diefenbaker","slug":"lake-diefenbaker","category":"Lake","country":"Canada","region":"Saskatchewan","city":null,"latitude":51.0,"longitude":-107.36667,"description":"Lake Diefenbaker is a reservoir and bifurcation lake in the southern part of the Canadian province of Saskatchewan. It was formed by the construction of the Gardiner Dam and the Qu'Appelle River Dam across the South Saskatchewan and Qu'Appelle Rivers respectively. Construction began in 1959 and the lake was filled in 1967."},{"name":"Akkajaure","slug":"akkajaure","category":"Lake","country":"Sweden","region":"Gällivare Municipality","city":null,"latitude":67.63528,"longitude":17.64139,"description":"Akkajaure is one of the largest reservoirs in Sweden. It lies at the headwaters of the Lule River in Norrbotten County, in Swedish Lappland, within the Stora Sjöfallet national park. The lake formed after the construction of the first Suorva dam in 1913–1923. The rim of the current dam is at an elevation of 453 m (1,486 ft)."},{"name":"Gjersjøen","slug":"gjersj-en","category":"Lake","country":"Norway","region":"Ås Municipality","city":null,"latitude":59.78333,"longitude":10.78333,"description":"Gjersjøen is a lake in the municipalities Nordre Follo and Ås in Akershus county, Norway. It has a surface area of 2.6 km2 (1.0 sq mi), and is 40 m above sea level. The lake drains through Gjersjøelva to Bunnefjorden."},{"name":"Nøklevann","slug":"n-klevann","category":"Lake","country":"Norway","region":"Oslo Municipality","city":null,"latitude":59.87528,"longitude":10.87694,"description":"Nøklevann is a lake in Østmarka in Oslo, Norway. It has a surface area of 0.8 km2, and is 163 meters above sea level. The lake drains through Ljanselva to Bunnefjorden. It is a former drinking water supply for Oslo."},{"name":"Lieps","slug":"lieps","category":"Lake","country":"Germany","region":"Mecklenburg-Vorpommern","city":null,"latitude":53.45111,"longitude":13.15722,"description":"Lieps is a lake in Mecklenburg-Vorpommern, Germany. At an elevation of 14.8 m, its surface area is 4.31 km²."},{"name":"Ziegelsee","slug":"ziegelsee","category":"Lake","country":"Germany","region":null,"city":null,"latitude":53.65472,"longitude":11.42333,"description":"Ziegelsee is a lake in Nordwestmecklenburg, Mecklenburg-Vorpommern, Germany. At an elevation of 37.8 metres (124 ft), its surface covers 3 square kilometres (1.2 mi2)."},{"name":"Lake Cuitzeo","slug":"lake-cuitzeo","category":"Lake","country":"Mexico","region":"Michoacán","city":null,"latitude":19.93333,"longitude":-101.08333,"description":"Lake Cuitzeo is a lake in the central part of Mexico, in the state of Michoacán. It has an area of 300–400 km2 (120–150 sq mi). The lake is astatic, meaning the volume and level of water in the lake fluctuates frequently. It is the second-largest freshwater lake in Mexico."},{"name":"Erhai Lake","slug":"erhai-lake","category":"Lake","country":"People's Republic of China","region":"Dali","city":null,"latitude":25.76333,"longitude":100.1875,"description":"Erhai or Er Lake, is an alpine fault lake in Dali City, Dali Prefecture, Yunnan province, China. Erhai was also known as Yeyuze (叶榆泽) or Kunming Lake (昆明池) in ancient times."},{"name":"Dian Lake","slug":"dian-lake","category":"Lake","country":"People's Republic of China","region":"Yunnan","city":null,"latitude":24.80056,"longitude":102.67139,"description":"Dian Lake, also known as Dianchi, Dianchi Lake, Lake Dian and Kunming Lake, is a fault lake located on the Puduhe-Xishan fault in Kunming, Yunnan, China at 24°23′–26°22′ N, 102°10′–103°40′ E. Its nickname is the \"Sparkling Pearl Embedded in a Highland\". It is the model for the Kunming Lake in Beijing's Summer Palace. Its name is the source of Yunnan's Chinese abbreviation 滇."},{"name":"Ch'iyar Quta","slug":"chiyar-quta","category":"Lake","country":"Bolivia","region":"La Paz Department","city":null,"latitude":-16.195,"longitude":-68.24389,"description":"Ch'iyar Quta is a lake in the Cordillera Real of Bolivia situated in the La Paz Department, Los Andes Province, Pucarani Municipality, Huayna Potosí Canton. It is situated at a height of about 4,700 metres (15,400 ft) near the peaks of Kunturiri and east of the lake Juri Quta."},{"name":"Lanker See","slug":"lanker-see","category":"Lake","country":"Germany","region":"Plön District","city":null,"latitude":54.20778,"longitude":10.2925,"description":"The Lanker See is a lake in the region of Holstein Switzerland in North Germany. It lies south of the town of Preetz in the district of Plön, and is crossed from south to north by the River Schwentine."},{"name":"Lake Tana","slug":"lake-tana","category":"Lake","country":"Ethiopia","region":"Amhara Region","city":null,"latitude":12.0,"longitude":37.25,"description":"Lake Tana is the largest lake in Ethiopia and a source of the Blue Nile. Located in Amhara Region in the north-western Ethiopian Highlands, the lake is approximately 84 kilometres long and 66 kilometres wide, with a maximum depth of 15 metres, and an elevation of 1,788 metres. Lake Tana is fed by the Gilgel Abay, Reb and Gumara rivers."},{"name":"Suttle Lake","slug":"suttle-lake","category":"Lake","country":"United States","region":"Oregon","city":null,"latitude":44.42156,"longitude":-121.74084,"description":"Suttle Lake is a natural lake near the crest of the Cascade Range in central Oregon, United States, covering 253 acres (1.02 km2). It was named in honor of John Settle, whose name was misspelled when the lake was officially recorded as a geographic feature."},{"name":"Berglsteiner See","slug":"berglsteiner-see","category":"Lake","country":"Austria","region":"Breitenbach am Inn","city":null,"latitude":47.4726,"longitude":11.9125,"description":"Berglsteiner See is a lake of Tyrol, Austria. The lake is located on 713 m height in Breitenbach am Inn in a depression of the south slope of the Voldöppberg, which is part of the Brandenberg Alps."},{"name":"Zengena Lake","slug":"zengena-lake","category":"Lake","country":"Ethiopia","region":"Amhara Region","city":null,"latitude":10.9139,"longitude":36.9667,"description":"Zengena Lake is a crater lake located at 10°54′50″N 36°58′00″E in the Awi Zone of the Amhara Region in Ethiopia. It is situated between the towns of Injibara and Kessa, only 200 m from the Addis Ababa-Bahir Dar highway at an elevation of 2500 m. The diameter of the lake is roughly 1 km. With a maximum depth of 166 m, it is the second deepest lake in Ethiopia after Lake Shala."},{"name":"Paravani Lake","slug":"paravani-lake","category":"Lake","country":"Georgia","region":"Samtskhe–Javakheti","city":null,"latitude":41.44444,"longitude":43.81222,"description":"Paravani lake is a volcanic lake in Georgia, located in Javakheti Plateau between Abul-Samsari and Javakheti Ranges."},{"name":"Grüner See","slug":"gr-ner-see","category":"Lake","country":"Germany","region":"Witzenhausen","city":null,"latitude":51.2956,"longitude":9.85417,"description":"Grüner See is a lake in Hundelshausen, Hesse, Germany. At an elevation of 220 metres (720 ft), its surface area is ca. 5,000 m2."},{"name":"Llyn Cerrig Bach","slug":"llyn-cerrig-bach","category":"Lake","country":"United Kingdom","region":"Llanfair-yn-Neubwll","city":null,"latitude":53.25885,"longitude":-4.54029,"description":"Llyn Cerrig Bach is a small lake located between Rhosneigr and Valley in the west of Anglesey, Wales."},{"name":"Lake Edward","slug":"lake-edward","category":"Lake","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":-0.33333,"longitude":29.6,"description":"Lake Edward is one of the smaller African Great Lakes. It is located in the Albertine Rift, the western branch of the East African Rift, on the border between the Democratic Republic of the Congo (DRC) and Uganda, with its northern shore a few kilometres south of the equator."},{"name":"Lago di Luzzone","slug":"lago-di-luzzone","category":"Lake","country":"Switzerland","region":"Canton of Ticino","city":null,"latitude":46.5675,"longitude":8.97694,"description":"Lago di Luzzone is a reservoir in Ticino, Switzerland. The reservoir has a volume of 108 million m³ and a surface area of 1.27 km2 (0.49 sq mi). It is located in the upper Blenio valley, in the municipalities of Ghirone and Aquila."},{"name":"Rybinsk Reservoir","slug":"rybinsk-reservoir","category":"Lake","country":"Russia","region":"Vologda Oblast","city":null,"latitude":58.36667,"longitude":38.43333,"description":"Rybinsk Reservoir, informally called the Rybinsk Sea, is a water reservoir on the Volga River and its tributaries the Sheksna and Mologa, formed by Rybinsk Hydroelectric Station dam, located in the Tver, Vologda, and Yaroslavl Oblasts. At the time of its construction, it was the largest man-made body of water on Earth. It is the northernmost point of the Volga. The Volga–Baltic Waterway starts from there."},{"name":"Lago dei Cavagnöö","slug":"lago-dei-cavagn","category":"Lake","country":"Switzerland","region":"Canton of Ticino","city":null,"latitude":46.45472,"longitude":8.50111,"description":"Lago dei Cavagnöö is a lake in the municipality of Bignasco, Ticino, Switzerland. Its surface area is 0.46 km2 (0.18 sq mi)."},{"name":"Lago del Narèt","slug":"lago-del-nar-t","category":"Lake","country":"Switzerland","region":"Switzerland","city":null,"latitude":46.47722,"longitude":8.56889,"description":"Lago del Narèt is a lake in Val Sambuco, Ticino, Switzerland. Its surface area is 86 ha. It is located in the municipality of Lavizzara. The closest village is Fusio."},{"name":"Lai da Marmorera","slug":"lai-da-marmorera","category":"Lake","country":"Switzerland","region":"Canton of the Grisons","city":null,"latitude":46.49972,"longitude":9.63694,"description":"Lai da Marmorera is a reservoir in the Grisons, Switzerland. It is part of the Parc Ela nature park."},{"name":"Helenesee","slug":"helenesee","category":"Lake","country":"Germany","region":"Frankfurt (Oder)","city":null,"latitude":52.27111,"longitude":14.4875,"description":"Helenesee is a lake in Brandenburg, Germany. Its surface area is ca. 250 ha. With a depth of 56.63 m, the Helenseee is the second deepest lake in Brandenburg, only surpassed by the lake Großer Stechlinsee. It is situated approximately 8 kilometers in the south of Frankfurt (Oder). It was formed after the flooding of a former open-pit mining which started in 1958."},{"name":"Lake Żarnowiec","slug":"lake-arnowiec","category":"Lake","country":"Poland","region":"Gmina Gniewino","city":null,"latitude":54.763,"longitude":18.053,"description":"Lake Żarnowiec is located in the Pomorze Voivodeship. It is 7.6 km (4.7 mi) long, 2.6 km (1.6 mi) wide and has a depth of 16 m (52 ft). The river Piaśnica cuts through it. The Żarnowiec Nuclear Power Plant was supposed to be built next to it. It now serves as the lower reservoir for the Żarnowiec Pumped Storage Power Station."},{"name":"Zarrenthiner Kiessee","slug":"zarrenthiner-kiessee","category":"Lake","country":"Germany","region":"Vorpommern-Greifswald District","city":null,"latitude":53.93113,"longitude":13.31371,"description":"Zarrenthiner Kiessee is a lake in the Vorpommern-Greifswald district in Mecklenburg-Vorpommern, Germany. At an elevation of 7.2 m, its surface area is 0.54 km2."},{"name":"Storsjön","slug":"storsj-n","category":"Lake","country":"Sweden","region":"Sandviken Municipality","city":null,"latitude":60.55917,"longitude":16.74222,"description":"Storsjön is a lake in Gävle Municipality and Sandviken Municipality in Gästrikland and is a part of Gavleån. Storsjön has an area of a 70.6 km2 (27.3 sq mi), a greatest depth of 15 metres (49 ft), and is approximately 62 metres (203 ft) above sea level. The lake is drained by Gavleån. Experimental fishing has proved that there are many different varieties of fish here, such as perch, bream, sea bream and ruffe."},{"name":"Senftenberger See","slug":"senftenberger-see","category":"Lake","country":"Germany","region":"Senftenberg","city":null,"latitude":51.5,"longitude":14.01667,"description":"Lake Senftenberg is an artificial lake in Landkreis Oberspreewald-Lausitz, Brandenburg, Germany. It is located in the Lusatian Lake District, a chain of artificial lakes. The lake is located on the border of Lower and Upper Lusatia between the southern Brandenburg city of Senftenberg and its districts Niemtsch and Großkoschen."},{"name":"Lake Ohrid","slug":"lake-ohrid","category":"Lake","country":"North Macedonia","region":null,"city":null,"latitude":41.03333,"longitude":20.71667,"description":"Lake Ohrid is a lake which straddles the mountainous border between the southwestern part of North Macedonia and eastern Albania. It is one of Europe's deepest and oldest lakes, with a unique aquatic ecosystem of worldwide importance, with more than 200 endemic species."},{"name":"Gampriner Seele","slug":"gampriner-seele","category":"Lake","country":"Liechtenstein","region":"Liechtenstein","city":null,"latitude":47.225,"longitude":9.50917,"description":"Gampriner Seele or Gampriner Seelein is the only lake in Liechtenstein. It was created by a flood of the Rhine River with enormous erosion in 1927. The lake lies at 435 metres above sea level in the village of Bendern–Gamprin."},{"name":"Königssee","slug":"k-nigssee","category":"Lake","country":"Germany","region":"Schönau am Königsee","city":null,"latitude":47.55,"longitude":12.975,"description":"The Königssee is a natural lake in the southeast Berchtesgadener Land district of the German state of Bavaria, near the Austrian border. Most of the lake is within the Berchtesgaden National Park."},{"name":"Dojran Lake","slug":"dojran-lake","category":"Lake","country":"Greece","region":"Dojran Municipality","city":null,"latitude":41.21667,"longitude":22.75,"description":"Doiran Lake, also spelled Dojran Lake is a lake with an area of 43.1 km2 (16.6 sq mi) shared between North Macedonia and Greece."},{"name":"Oreti Beach","slug":"oreti-beach","category":"Beach","country":"New Zealand","region":null,"city":null,"latitude":-46.44842,"longitude":168.23009,"description":"Oreti Beach is the central bay of three lying on the Foveaux Strait coast of Southland, New Zealand, the others being Te Waewae Bay and Toetoes Bay. Twenty-six kilometres in length, the bay lies between the town of Riverton and the outflow of the Aparima River in the northwest, and the estuary of the Ōreti River in the southeast."},{"name":"Rialto Beach","slug":"rialto-beach","category":"Beach","country":"United States","region":"Washington","city":null,"latitude":47.92103,"longitude":-124.63955,"description":"Rialto Beach is a public beach located on the Pacific Ocean in Washington state. It is adjacent to Mora Campground in the Olympic National Park near the mouth of the Quillayute River, and is composed of an ocean beach and coastal forest. The many miles of seaside topography offer views of sea stacks and rock formations in the Pacific Ocean."},{"name":"Plages du Prado","slug":"plages-du-prado","category":"Beach","country":"France","region":"Provence-Alpes-Côte d'Azur","city":null,"latitude":43.26278,"longitude":5.37139,"description":"The Plages du Prado are the beaches in the south neighborhood of Marseille, France. The seaside park is an artificial coastal development created in the late 1970s by Gaston Defferre. They were built with the fill coming from the construction of the two Marseille metro lines."},{"name":"Hietaniemi beach","slug":"hietaniemi-beach","category":"Beach","country":"Finland","region":"Helsinki","city":null,"latitude":60.17342,"longitude":24.90537,"description":"Hietaniemi beach is a popular sand beach in central Helsinki, Finland. It is located in the Töölö district, next to the Hietaniemi Cemetery and is the most popular beach in central Helsinki."},{"name":"Daaibooi","slug":"daaibooi","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.21222,"longitude":-69.08444,"description":"Daaibooi is a beach on the Caribbean island of Curaçao, located close to the village of Sint Willibrordus, a 30 minutes drive to the north-west of Willemstad. The beach is in a secluded bay, surrounded by cliffs. The loggerhead sea turtle is known to nestle here. The beach is used as a starting point for scuba diving. There is a basic restaurant."},{"name":"Playa Kalki","slug":"playa-kalki","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.37556,"longitude":-69.15778,"description":"Playa Kalki is a beach on the Caribbean island of Curaçao, also known as Alice in Wonderland due to mushroom-shaped coral formations. The name Kalki is unrelated to the Avatar Kalki, but comes from the local Papiamentu word for the white coral rock and limestone, which is abundant on the beach and surrounding cliffs."},{"name":"Mozambique Beach","slug":"mozambique-beach","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.50119,"longitude":-48.4019,"description":"Mozambique Beach is the longest beach on Santa Catarina Island in Brazil at 13.5 km in length. The beach is located to the north of Barra da Lagoa in the east of the island."},{"name":"Canasvieiras","slug":"canasvieiras","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.42694,"longitude":-48.45546,"description":"Canasvieiras is a neighbourhood and beach located in southern Brazil, approximately 27 kilometres (17 mi) north-east of the city of Florianópolis on the northern part of Santa Catarina Island. Nearby beaches include Jurerê and Cachoeira do Bom Jesus. The population is 10,129, and the area is 29.0 km²."},{"name":"Falesia Beach","slug":"falesia-beach","category":"Beach","country":"Portugal","region":"Albufeira","city":null,"latitude":37.08667,"longitude":-8.17,"description":"Falésia Beach is a beach in Albufeira, Algarve, southern Portugal. It has a cliff that begins in the Barranco das Belharucas Beach and extends to Vilamoura."},{"name":"Guincho Beach","slug":"guincho-beach","category":"Beach","country":"Portugal","region":"Alcabideche","city":null,"latitude":38.73315,"longitude":-9.4727,"description":"Praia do Guincho is an Atlantic beach located on Portugal's Estoril coast, 5 km from the town of Cascais, and is located in the municipality of Cascais, more precisely in the parishes of Cascais e Estoril and Alcabideche, in the District of Lisbon. Guincho is situated close to several small villages, including Areia, Charneca, Figueira do Guincho and Biscaia."},{"name":"Whitehaven Beach","slug":"whitehaven-beach","category":"Beach","country":"Australia","region":null,"city":null,"latitude":-20.28268,"longitude":149.03491,"description":"Whitehaven Beach is on Whitsunday Island, Queensland, Australia. The island is accessible by boat, seaplane, or helicopter from Airlie Beach, as well as from Hamilton Island. It lies across from Stockyard Beach, also known as Chalkie's Beach, on Haslewood Island. The beach is seven kilometres in length and is famous for its white silica sands and turquoise water."},{"name":"Jurerê","slug":"jurer","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.43714,"longitude":-48.49872,"description":"Jurerê is a beach-side neighbourhood on the northern shore of the island of Florianópolis in Santa Catarina, Brazil. The Jurerê Internacional resort is located in Jurerê."},{"name":"Revere Beach","slug":"revere-beach","category":"Beach","country":"United States","region":"Revere","city":null,"latitude":42.40784,"longitude":-70.99084,"description":"Revere Beach is a public beach in Revere, Massachusetts, measuring over three miles (4.8 km) long and located about five miles (8 km) north of downtown Boston. In 1875, a rail link was constructed to the beach, leading to its increasing popularity as a summer recreation area."},{"name":"Rincon Beach County Park","slug":"rincon-beach-county-park","category":"Beach","country":"United States","region":"Santa Barbara County","city":null,"latitude":34.37806,"longitude":-119.48167,"description":"Rincon (Spanish, \"angle\" or \"corner\") is a surf spot located at the Ventura and Santa Barbara County line in Southern California, United States. Also known as the \"Queen of the Coast\", Rincon is one of the most famous surf spots in California, known around the world for its well-formed waves and long rides. The book 100 Best Surf Spots in the World rates Rincon at 24."},{"name":"Bay Shore Beach","slug":"bay-shore-beach","category":"Beach","country":"United States","region":"Virginia","city":null,"latitude":37.0547,"longitude":-76.2858,"description":"Bay Shore Beach was a beach that existed adjacent to Buckroe Beach in Hampton, Virginia in the 20th century. It was founded in 1898 by several African-American businessmen. The beach was one of the most popular resort and vacation destinations in the Mid-Atlantic region for African-Americans. In addition to standard beach activities, hotels, and restaurants, Bay Shore also had an amusement park."},{"name":"Baía do Refugo","slug":"ba-a-do-refugo","category":"Beach","country":"Portugal","region":"Azores","city":null,"latitude":38.645,"longitude":-27.118,"description":"Terceira is a volcanic island in the Azores archipelago of Portugal, 1,181 km (734 mi) due west of Lisbon. It is one of the larger islands of the archipelago, with a population of 53,311 inhabitants in an area of approximately 396.75 km2 (153.19 sq mi)."},{"name":"Doctor's Cave Beach Club","slug":"doctors-cave-beach-club","category":"Beach","country":"Jamaica","region":"Saint James Parish","city":null,"latitude":18.48708,"longitude":-77.92943,"description":"Doctor's Cave Beach Club, located in Montego Bay, Jamaica, is a beach. It is part of the protected Montego Bay Marine Park."},{"name":"Dominical","slug":"dominical","category":"Beach","country":"Costa Rica","region":"Osa Canton","city":null,"latitude":9.25,"longitude":-83.86667,"description":"Dominical is a beach-front town in Bahía Ballena District, of the Osa canton in the province of Puntarenas in Costa Rica, approximately 45 km south of Quepos. It is well known for large, year-round waves and is popular among surfers in Costa Rica. The town began as a small fishing village but has since grown into a tourist attraction, most notably for surfers."},{"name":"Doran Regional Park","slug":"doran-regional-park","category":"Beach","country":"United States","region":"Bodega Bay","city":null,"latitude":38.314,"longitude":-123.043,"description":"Doran Regional Park is a regional park south of Bodega Bay, California, U.S.A. that is maintained by the Sonoma County Regional Parks Department. It covers an area of 127 acres (51 ha). It is located at 38.314°N 123.0428°W on the sand spit separating Bodega Harbor from Bodega Bay. The park address is 201 Doran Beach Road, Bodega Bay, CA."},{"name":"Double Bluff Beach","slug":"double-bluff-beach","category":"Beach","country":"United States","region":"Washington","city":null,"latitude":47.9985,"longitude":-122.505,"description":"Double Bluff Beach is a beach and headland on Whidbey Island in the U.S. state of Washington. The beach tidelands themselves comprise Double Bluff State Park. The uplands and access areas are operated by Island County, Washington as Double Bluff County Park and Beach Access."},{"name":"Druif Beach","slug":"druif-beach","category":"Beach","country":"Aruba","region":"Aruba","city":null,"latitude":12.532,"longitude":-70.057,"description":"Druif Beach, is situated in Oranjestad, Aruba and spans approximately 300 metres (980 ft) in length."},{"name":"Umupuia Beach","slug":"umupuia-beach","category":"Beach","country":"New Zealand","region":"Auckland Region","city":null,"latitude":-36.90428,"longitude":175.06967,"description":"Duders Beach, also known as Umupuia Beach, is located in the Auckland Region of New Zealand, to the east of Maraetai on the North Road from Clevedon. Duder Regional Park is on the headland immediately to the east."},{"name":"Duxbury Beach","slug":"duxbury-beach","category":"Beach","country":"United States","region":null,"city":null,"latitude":42.04177,"longitude":-70.63559,"description":"Duxbury Beach is a barrier beach in the town of Duxbury, Massachusetts. It is six miles long and is accessed by the Powder Point Bridge from Duxbury, or Gurnet Road from Marshfield. Since 1975, approximately 4.5 miles of the beach is owned by Duxbury Beach Reservation, Inc, which annually leases a substantial portion of the beach—excepting the Duxbury Beach Park area—to the town of Duxbury."},{"name":"Eagle Beach","slug":"eagle-beach","category":"Beach","country":"Aruba","region":null,"city":null,"latitude":12.5492,"longitude":-70.0579,"description":"Eagle Beach is a beach and neighbourhood of Oranjestad, Aruba. The neighbourhood is famous for its many low-rise resorts and wide public beach. It is the widest beach of Aruba. and has soft white sand. It has been rated one of the best beaches in the world."},{"name":"East Beach","slug":"east-beach","category":"Beach","country":"United States","region":"Santa Barbara","city":null,"latitude":34.4142,"longitude":-119.682,"description":"East Beach located in Santa Barbara, California, United States, is often the first beach seen upon entering the city limits. East Beach is separated from West Beach by Stearn's Wharf, and is proximal to downtown Santa Barbara. East Beach is the primary beach for tourists, as some of the major Santa Barbara hotels face this beach. Cabrillo Bathhouse and Gym are also located on East Beach."},{"name":"East Beach State Beach","slug":"east-beach-state-beach","category":"Beach","country":"United States","region":"Rhode Island","city":null,"latitude":41.3451,"longitude":-71.68229,"description":"East Beach or East State Beach is a seaside public recreation area on Quonochontaug Neck, the narrow barrier island that separates Block Island Sound and Ninigret Pond, in the town of Charlestown, Rhode Island, United States. The state beach encompasses three miles (4.8 km) of oceanfront and abuts Ninigret National Wildlife Refuge."},{"name":"East Matunuck State Beach","slug":"east-matunuck-state-beach","category":"Beach","country":"United States","region":"South Kingstown","city":null,"latitude":41.3778,"longitude":-71.5264,"description":"East Matunuck State Beach is a public recreation area encompassing 144 acres (58 ha) on the shore of Block Island Sound in the town of South Kingstown, Rhode Island. The state beach offers picnicking, ocean swimming, and beach activities. It is open seasonally."},{"name":"Eastern Beach","slug":"eastern-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.1475,"longitude":144.3735,"description":"Eastern Beach is a popular swimming and recreation area in Geelong, Victoria, Australia, on the shores of Corio Bay. Built during the 1930s in the Art Deco style, a shark-proof sea bath is provided, as well as a children's swimming pool, kiosk, and dressing room pavilion. A number of Art Deco buildings in the area are listed on the Victorian Heritage Register."},{"name":"El Porto Beach","slug":"el-porto-beach","category":"Beach","country":"United States","region":"California","city":null,"latitude":33.905,"longitude":-118.423,"description":"El Porto Beach is a California public beach managed by the County of Los Angeles, located in Santa Monica Bay beside El Porto, which is now part of the City of Manhattan Beach, between the beaches of El Segundo Beach and Manhattan Beach, and is protected under the state park system. The entrance to El Porto's large parking lot, which has meters, is at the west end of 45th Street from Highland Avenue."},{"name":"Ela Beach","slug":"ela-beach","category":"Beach","country":"Papua New Guinea","region":null,"city":null,"latitude":-9.47965,"longitude":147.15616,"description":"Ela Beach, formerly known as Era Kone, meaning 'Turtle Beach' in the Motuan dialect of the Papuan region of Papua New Guinea, is Port Moresby's primary public beach."},{"name":"Elbow Beach, Bermuda","slug":"elbow-beach-bermuda","category":"Beach","country":"Bermuda","region":null,"city":null,"latitude":32.2724,"longitude":-64.7775,"description":"Elbow Beach is one of the most popular beaches on the main island of Bermuda. Located at 60 South Shore Road, Paget Parish, PG 04 on the southern coast of Paget Parish, it is also home to one of Bermuda's most famous resorts, the Elbow Beach Hotel. Part of the beach is privately owned by the hotel for use by its guests; there is public access to the rest of the beach."},{"name":"Elouera Beach","slug":"elouera-beach","category":"Beach","country":"Australia","region":"New South Wales","city":null,"latitude":-34.046,"longitude":151.16,"description":"Elouera Beach or Elouera is a patrolled beach on Bate Bay, in Cronulla, Sydney, New South Wales, Australia. The Wall is the local name given to the area between North Cronulla Beach and Elouera."},{"name":"Redonda Beach","slug":"redonda-beach","category":"Beach","country":"Portugal","region":"Póvoa de Varzim","city":null,"latitude":41.37933,"longitude":-8.76914,"description":"Redonda Beach or Praia Redonda in Portuguese, meaning Round, is a beach on the southwestern coast of Póvoa de Varzim, Portugal, bordering the Atlantic Ocean. It is adjacent to Passeio Alegre, in Póvoa de Varzim City Center. The Avenida dos Banhos runs alongside the beach, and the Diana Bar beach library, a nightclub and Café Guarda-sol are located on the beach."},{"name":"Praia de Santa Mónica","slug":"praia-de-santa-m-nica","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":15.97778,"longitude":-22.83194,"description":"Praia de Santa Mónica is a sandy beach in the southwestern part of the island of Boa Vista in Cape Verde. The nearest village is Povoação Velha, 5 km to the north. The beach is adjacent to the protected area Morro de Areia Nature Reserve, which is important for endemic birds and turtles. Praia de Santa Mónica is part of a tourism development zone."},{"name":"Esteiro Beach","slug":"esteiro-beach","category":"Beach","country":"Portugal","region":null,"city":null,"latitude":41.40135,"longitude":-8.77892,"description":"Esteiro Beach or Praia do Esteiro in Portuguese, meaning tidal creek, is a beach on the southwestern coast of Póvoa de Varzim, Portugal, bordering the Atlantic Ocean. It is adjacent to Aver-o-Mar and the beach has medium to fine sand, with a recovering grey dune ecosystem."},{"name":"Praia do Futuro","slug":"praia-do-futuro","category":"Beach","country":"Brazil","region":"Regional Executive Secretariat 7","city":null,"latitude":-3.75189,"longitude":-38.44754,"description":"Fortaleza is the state capital of Ceará, located in Northeastern Brazil. It is Brazil's fourth-largest city—Fortaleza surpassed Salvador in the 2024 census, with a population of slightly over 2.5 million—and 12th-largest among cities with the highest gross domestic product. It forms the core of the Fortaleza metropolitan area, which is home to almost 4 million people."},{"name":"Praia do Norte","slug":"praia-do-norte","category":"Beach","country":"Portugal","region":"Nazaré","city":null,"latitude":39.60442,"longitude":-9.08558,"description":"Praia do Norte is a beach located in Nazaré, Portuguese Oeste region, which due to its giant white breaking waves is famed for its surfing conditions. Nazaré's waves were listed on the Guinness Book of Records for the biggest waves ever surfed and have also been featured multiple times on the Billabong XXL awards in the categories of Biggest Wave and Ride of the Year."},{"name":"Praia do Túnel","slug":"praia-do-t-nel","category":"Beach","country":"Portugal","region":null,"city":null,"latitude":37.0864,"longitude":-8.25379,"description":"Praia do Túnel is a beach on the Atlantic south coast of the Algarve, in the town of Albufeira which is within the Municipality of Albufeira, Portugal. The beach is also known as Praia do Peneco and is one of the two beaches which front the town of Albufeira with Praia do Túnel at the western end and Praia dos Pescadores lying to the eastern end of the towns seafront."},{"name":"Milanesia Beach","slug":"milanesia-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.75167,"longitude":143.31278,"description":"Milanesia Beach is a remote ocean beach on the Great Ocean Road coast of south-western Victoria, Australia. The beach occupies an open bay between Lion Headland and Bowker Point and extends for approximately 1.8 kilometres (1.1 mi). It is backed by steep forested slopes and private farmland, while offshore reefs partly shelter the shoreline from direct Southern Ocean swell."},{"name":"Glenaire Beach","slug":"glenaire-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.80806,"longitude":143.46389,"description":"Glenaire Beach is an exposed ocean beach at the mouth of the Aire River on the Great Ocean Road coast of south-western Victoria, Australia. The beach faces south-west toward the Southern Ocean and is bordered by coastal sand dunes, rocky shoreline and the lower Aire River lagoon. A smaller adjoining beach, Glenaire East Beach, lies immediately to the east."},{"name":"Front Beach","slug":"front-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.33507,"longitude":144.32505,"description":"Torquay Front Beach is a popular patrolled beach located in Torquay, Victoria, Australia. The beach faces due east and stretches for 1 kilometre from Yellow Bluff at its northern end to Point Danger to its south. The beach is popular with families, as the surf is comparably calmer than its counterpart, the adjacent surf beach, with an even calmer section of the beach protected by Point Danger known as Cosy Corner."},{"name":"Clifton Beach","slug":"clifton-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.67806,"longitude":143.12417,"description":"Clifton Beach is a small, isolated ocean beach on the Great Ocean Road coast of south-western Victoria, Australia. The beach lies beneath steep coastal cliffs and is reached by a walking track descending from the surrounding bluff. It is unpatrolled and exposed to the high-energy conditions of the Southern Ocean, with hazards including deep water, strong currents and rough surf."},{"name":"Bancoora Beach","slug":"bancoora-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.29125,"longitude":144.40791,"description":"Bancoora Beach is a patrolled coastal beach facing the Bass Strait in Breamlea, Victoria, Australia. The beach, named after the SS Bancoora which ran aground on the adjacent Breamlea Beach in 1891, is a popular destination for holidaymakers in the summer, owing to the nearby caravan park, as well as the low-to-moderate surf conditions. The beach area is Public land managed by the City of Greater Geelong."},{"name":"Addiscot Beach","slug":"addiscot-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.38306,"longitude":144.25556,"description":"Addiscot Beach, also known as Addis Beach or Point Addis Beach, is an unpatrolled beach located near Bells Beach, Victoria, Australia. The beach is a popular tourist stop along the Great Ocean Road, and sees many swimmers and surfers in the summer months. The beach is also notable for its dominating cliffs, reaching as high as 80 metres, and geology."},{"name":"Taroona Beach","slug":"taroona-beach","category":"Beach","country":"Australia","region":"Tasmania","city":null,"latitude":-42.9525,"longitude":147.35194,"description":"Taroona Beach is a popular beach destination along the River Derwent in Taroona, Hobart, Tasmania. The south facing beach looks directly out to Storm Bay and the Tasman Sea, with views of the Derwent estuary, the City of Clarence on the eastern shore, Opossum Bay, South Arm, the Alum Cliffs and northern tip of Bruny Island."},{"name":"Praia dos Ingleses","slug":"praia-dos-ingleses","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.43516,"longitude":-48.39126,"description":"Praia dos Ingleses is a beach located in the neighborhood of Ingleses do Rio Vermelho, in the north of the Santa Catarina Island 31 km from the Centro downtown district of Florianópolis the capital of the state of Santa Catarina, Brazil."},{"name":"Cala Pada","slug":"cala-pada","category":"Beach","country":"Spain","region":"Santa Eulària des Riu","city":null,"latitude":38.98722,"longitude":1.57333,"description":"Cala Pada is a beach on the south east seaboard of the Spanish island of Ibiza. It is in the municipality of Santa Eulària des Riu and is 2.7 miles (4.3 km) east of the town of Santa Eulària des Riu, and 1.9 miles (3.1 km) south west of the beach resort of Es Canar."},{"name":"Platja des Niu Blau","slug":"platja-des-niu-blau","category":"Beach","country":"Spain","region":"Santa Eulària des Riu","city":null,"latitude":38.9925,"longitude":1.5525,"description":"Platja des Niu Blau is a beach in the south east seaboard of the Spanish island of Ibiza. It is part of the municipality of Santa Eulària des Riu and is located 1.4 miles (2.3 km) east of the town of Santa Eulària des Riu, and 2.0 miles (3.2 km) west of the beach resort of Es Canar. It is a small, sheltered sandy cove, fringed by pine forests."},{"name":"Platja S'Estanyol","slug":"platja-sestanyol","category":"Beach","country":"Spain","region":"Santa Eulària des Riu","city":null,"latitude":38.92528,"longitude":1.48667,"description":"Platja S'Estanyol is a beach on the south east seaboard of the Spanish island of Ibiza. It is in the municipality of Santa Eulària des Riu and is 9.4 miles (15.1 km) south west of the town of Santa Eulària des Riu, and 1.8 miles (2.9 km) west of the village of Jesús."},{"name":"Cala de Sant Vicent","slug":"cala-de-sant-vicent","category":"Beach","country":"Spain","region":"Sant Joan de Labritja","city":null,"latitude":39.07608,"longitude":1.59192,"description":"Cala de Sant Vicent is a beach resort village on the Spanish island of Ibiza. The resort is in the municipality of Sant Joan de Labritja. The resort is reached along the designated roads EI-321 east from Sant Joan de Labritja, and on the EI-200 north from Santa Eulària des Riu. The resort is 18.9 miles (30.4 km) north east of Ibiza Town and 23.5 miles (37.8 km) of Ibiza Airport."},{"name":"Cala Violina","slug":"cala-violina","category":"Beach","country":"Italy","region":"Scarlino","city":null,"latitude":42.85561,"longitude":10.77433,"description":"Cala Violina is a coastal inlet in the Maremma region of southern Tuscany, Italy, located within the municipality of Scarlino. It opens onto the Tyrrhenian Sea and is part of the protected natural area of the Bandite di Scarlino."},{"name":"Olympiaki Akti","slug":"olympiaki-akti","category":"Beach","country":"Greece","region":"Katerini Municipality","city":null,"latitude":40.24,"longitude":22.584,"description":"Olympiaki Akti is a village in the Katerini municipality, Greece. It is also still domestically known by its initial name Katerinoskala (Κατερινόσκαλα) which can be literally expressed as \"Katerini's staircase\"."},{"name":"Capocotta","slug":"capocotta","category":"Beach","country":"Italy","region":"Rome","city":null,"latitude":41.66458,"longitude":12.40297,"description":"The beach of Capocotta is the area of the Roman coast between Castel Porziano and Torvaianica, one of the best preserved stretches of dunes in Italy. With an extension of 45 hectares, since 1996 it is part of the Litorale Romano State Nature Reserve."},{"name":"The Silver Strand","slug":"the-silver-strand","category":"Beach","country":"Ireland","region":"Gleann Cholm Cille","city":null,"latitude":54.6643,"longitude":-8.77528,"description":"The Silver Strand is a horse-shoe shaped beach situated at Malin Beg, near Glencolmcille, in the south-west of County Donegal in Ulster, the northern province in Ireland. Several 'wee burns' flow into Donegal Bay at Silver Strand."},{"name":"Seaquarium Beach","slug":"seaquarium-beach","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.08611,"longitude":-68.89861,"description":"Seaquarium Beach is a beach on the Caribbean island of Curaçao, located to the south of Willemstad. The beach is named after Curaçao Sea Aquarium, located nearby. The beach is open to the public, but an access fee must be paid. There are several bars, clubs and restaurants."},{"name":"Playa de Las Teresitas","slug":"playa-de-las-teresitas","category":"Beach","country":"Spain","region":"Santa Cruz de Tenerife","city":null,"latitude":28.50861,"longitude":-16.18583,"description":"The Playa de Las Teresitas is an artificial, white sand, tourist beach located north of the village of San Andrés, Santa Cruz de Tenerife in Tenerife, Spain."},{"name":"Jomtien","slug":"jomtien","category":"Beach","country":"Thailand","region":"Na Chom Thian","city":null,"latitude":12.88233,"longitude":100.89372,"description":"Jomtien or Jomtien Beach is a town on the east coast of the Gulf of Thailand about 165 km (103 mi) south-east of Bangkok in Bang Lamung District, Chonburi Province. It is about 3 km (1.9 mi) south of Pattaya and is home to high-rise condominiums, beach side hotels, beaches, and restaurants."},{"name":"Playa Kanoa","slug":"playa-kanoa","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.17222,"longitude":-68.86306,"description":"Playa Kanoa is a beach on the Caribbean island of Curaçao, located to the north of Willemstad. It is one of the few beaches on the northern side of the island. Surfing is a popular activity on the beach. There is a snack bar as well as a fish restaurant, and there is a nearby fisherman's village."},{"name":"Navagio","slug":"navagio","category":"Beach","country":"Greece","region":"Zakynthos Regional Unit","city":null,"latitude":37.8596,"longitude":20.62487,"description":"Navagio Beach, or Shipwreck Beach, is an exposed cove, sometimes referred to as \"Smugglers Cove\", on the coast of Zakynthos, in the Ionian Islands of Greece. It is one of the most famous and photographed beaches in the world."},{"name":"Praia Brava","slug":"praia-brava","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.399,"longitude":-48.413,"description":"Praia Brava is an upscale neighborhood located in the north of Santa Catarina Island, in the municipality of Florianópolis, the capital of the Brazilian state of Santa Catarina. The beach offers clean, crystal-clear water, natural beauty, and excellent waves for surfing and bodyboarding."},{"name":"Praia Formosa","slug":"praia-formosa","category":"Beach","country":"Portugal","region":"São Martinho","city":null,"latitude":32.6405,"longitude":-16.95275,"description":"The Praia Formosa is a beach on the Portuguese island of Madeira. It is the fashionable district of Funchal and a popular beach location."},{"name":"Praia Inhame","slug":"praia-inhame","category":"Beach","country":"São Tomé and Príncipe","region":"Caué","city":null,"latitude":0.0248,"longitude":6.5197,"description":"Praia Inhame is a beach in the southernmost part of the island of São Tomé in São Tomé and Príncipe. It lies directly east of the southernmost point of the island, Ponta Homem da Capa, and 2 km southwest of the village Porto Alegre. There is an eco lodge near the beach. The Canal das Rolas separates it from Ilhéu das Rolas."},{"name":"Praia Pesqueira","slug":"praia-pesqueira","category":"Beach","country":"São Tomé and Príncipe","region":"Caué","city":null,"latitude":0.0981,"longitude":6.6226,"description":"Praia Pesqueira is a seaside village in Caué District on São Tomé Island in São Tomé and Príncipe. Its population is 201. The locality is located just south of Dona Augusta and 5 km southwest of São João dos Angolares."},{"name":"Praia da Balaia","slug":"praia-da-balaia","category":"Beach","country":"Portugal","region":null,"city":null,"latitude":37.0881,"longitude":-8.21069,"description":"Praia da Balaia is a small satellite beach at the eastern end of its larger neighbour, Praia Santa Eulália, on the Atlantic south coast of the Algarve. It is within the municipality of Albufeira and is 3.1 kilometres (1.9 mi) east of the town of Albufeira and 1.7 kilometres (1.1 mi) west of the coastal village of Olhos de Água."},{"name":"Grote Knip","slug":"grote-knip","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.35167,"longitude":-69.15167,"description":"Grote Knip is a beach on the Caribbean island of Curaçao, located at the western side of the island, between the villages of Westpunt and Lagun. The beach gives way to a small lagune between high rocks. It is freely accessible to the public. The beach is used as a starting point for snorkeling, due to the presence of a coral reef nearby."},{"name":"Playa Gipy","slug":"playa-gipy","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.39028,"longitude":-69.15583,"description":"Playa Gipy is a beach on the Caribbean island of Curaçao, located on the northern tip of the island, close to the village of Westpunt. The beach is small and rocky, and the waterfront is difficult to reach. There are no facilities. The beach is visited by loggerhead sea turtles."},{"name":"As Catedrais beach","slug":"as-catedrais-beach","category":"Beach","country":"Spain","region":"A Devesa, Ribadeo","city":null,"latitude":43.55389,"longitude":-7.15722,"description":"Praia das Catedrais is on the northwest coast of Spain. It is the name given by the tourism industry to Praia de Augas Santas. The beach is located in the Ribadeo municipality, in the province of Lugo (Galicia), on the Cantabric coast, and it lies about ten kilometres to the west of the town of Ribadeo. Its name is derived from its cliff formations."},{"name":"Playa Santa Cruz","slug":"playa-santa-cruz","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.30611,"longitude":-69.145,"description":"Playa Santa Cruz is a beach on the Caribbean island of Curaçao, located to the south of the village of Lagun. It is a wide, sandy beach. There are beach cabins and a snack bar that opens irregularly during weekends."},{"name":"Whatipu Beach","slug":"whatipu-beach","category":"Beach","country":"New Zealand","region":"Auckland Region","city":null,"latitude":-37.03,"longitude":174.48,"description":"Whatipu is a remote beach on the west coast of the Auckland Region in the North Island of New Zealand. The Whatipu area has been managed as a scientific reserve by the Auckland Regional Council since 2002. The road to it is unsealed. To the south of Whatipu is Manukau Harbour. To the north is Karekare. Whatipu is located at the southern end of the Waitākere Ranges."},{"name":"Lazurnaya Bay","slug":"lazurnaya-bay","category":"Beach","country":"Russia","region":null,"city":null,"latitude":43.19556,"longitude":132.11806,"description":"Lazurnaya Bay is a bay on the east side of the Muravyov-Amursky Peninsula in Russia. It lies to the northeast of Vladivostok and to the southwest from the Three Little Pigs Bay. The Lazurnaya Bay forms part of the Ussuri Bay in the Sea of Japan."},{"name":"Sardinero","slug":"sardinero","category":"Beach","country":"Spain","region":"Santander","city":null,"latitude":43.47417,"longitude":-3.7875,"description":"Sardinero is a popular beach located in the Spanish city of Santander, Cantabria. The beach is divided in two by the gardens of Piquio about one-quarter the way along its length, stretching from the Magdalena Peninsula to Mataleñas; two further adjacent beaches are also sometimes included."},{"name":"Dueodde","slug":"dueodde","category":"Beach","country":"Denmark","region":"Bornholm regional municipality","city":null,"latitude":54.9877,"longitude":15.07941,"description":"Dueodde is a beach in Denmark on Bornholm's southernmost tip. It is known for its very fine white sand. The area around Dueodde was originally a large sandy area. In the eighteenth century it was planted with pines, as well as Ammophila and Leymus grasses to reduce sand drift. Today, Dueodde is a protected area. The sand at Dueodde moves easily with the wind to form dunes."},{"name":"Praia dos Açores","slug":"praia-dos-a-ores","category":"Beach","country":"Brazil","region":"Florianópolis","city":null,"latitude":-27.78428,"longitude":-48.52307,"description":"Praia dos Açores is a beach-side district on the south side of the Island of Santa Catarina in the state of Santa Catarina in Brazil. The beach is 31 km from the Centro downtown region of Florianópolis."},{"name":"Kleine Knip","slug":"kleine-knip","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.34083,"longitude":-69.15278,"description":"Kleine Knip is a beach on the Caribbean island of Curaçao. It is located at the western side of the island, between the villages of Westpunt and Lagún, at 50 mins drive from Willemstad. It is a small beach, located at a bay between rocks. There are only few facilities. The parking is right next to the beach."},{"name":"Ponta Negra","slug":"ponta-negra","category":"Beach","country":"Brazil","region":"Ponta Negra","city":null,"latitude":-5.88111,"longitude":-35.17111,"description":"Ponta Negra is a beach and neighborhood located in the Brazilian city of Natal, the capital of the state of Rio Grande do Norte. Located in the extreme south of the beach is the Morro do Careca, a large dune and a landmark of the city."},{"name":"Porto de Galinhas beach","slug":"porto-de-galinhas-beach","category":"Beach","country":"Brazil","region":"Ipojuca","city":null,"latitude":-8.50417,"longitude":-35.00111,"description":"Porto de Galinhas is a beach in the municipality of Ipojuca, Pernambuco, Brazil. Porto de Galinhas is a major tourist destination. The beach is famous for its bright-water beaches and the natural pools. It is part of the municipality of Ipojuca, and located 60 kilometers (37 mi) south of the state capital, Recife. The municipality of Ipojuca, where Porto de Galinhas lies, was established on November 12, 1895."},{"name":"Ocean Beach","slug":"ocean-beach","category":"Beach","country":"United States","region":"San Francisco","city":null,"latitude":37.75944,"longitude":-122.51083,"description":"Ocean Beach is a beach on the west coast of San Francisco, California, United States. Bordering the Pacific Ocean, the beach is 3.5 miles long, and it is known for its strong currents, surf culture, foggy weather in the late spring and summer, and lack of high rise buildings."},{"name":"Playa Porto Marie","slug":"playa-porto-marie","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.21917,"longitude":-69.08639,"description":"Playa Porto Marie is a beach on the Caribbean island of Curaçao, located near the village of Sint Willibrordus, at the Porto Marie Bay. The beach is used as a starting point for scuba diving and snorkeling."},{"name":"Sudan Beach","slug":"sudan-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.3167,"longitude":-36.45,"description":"Greene Peninsula is a mountainous peninsula within Cumberland East Bay, separating Moraine Fjord to the west from the main arm of Cumberland East Bay, on the north coast of South Georgia Island. The entire area was charted by the Swedish Antarctic Expedition (SAE), 1901–04, under Otto Nordenskjöld."},{"name":"Papua Beach","slug":"papua-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.25,"longitude":-36.5667,"description":"Papua Beach is a beach 1.5 nautical miles (2.8 km) long on the southeast shore of Cumberland West Bay, South Georgia. The name derives from \"Papua Cove,\" a now-obsolete name given to a minor recession of the shore of Papau Beach by the Swedish Antarctic Expedition under Nordenskjold (1901–04) after members of the expedition noticed a colony of gentoo penguins there."},{"name":"Binder Beach","slug":"binder-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.0167,"longitude":-37.7167,"description":"Right Whale Bay is a bay 1.5 miles (2.4 km) wide, entered between Craigie Point and Nameless Point along the north coast of South Georgia Island. The bay is named for the southern right whales found in the area. South Georgia has historically been well known for whaling. The bay is linked to Morsa Bay on the island's south coast by a mountain pass called Ernesto Pass."},{"name":"Balsam Beach","slug":"balsam-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.3167,"longitude":-36.4333,"description":"A beach in United Kingdom, documented on Wikipedia. Check local guides for access, swimming conditions and facilities before you go."},{"name":"Paul Beach","slug":"paul-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.0667,"longitude":-37.4,"description":"The Bay of Isles is a bay 9 miles (14 km) wide and 3 miles (5 km) deep, lying between Cape Buller and Cape Wilson along the north coast of South Georgia. It was discovered in 1775 by a British expedition under James Cook and so named by him because numerous islands lie in the bay. Of South Georgia's 31 breeding bird species, 17 are found here."},{"name":"Bonner Beach","slug":"bonner-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.8333,"longitude":-36.0167,"description":"Bonner Beach is a small, flat beach on the south shore of Larsen Harbor in the southeast part of South Georgia. It is the only place in South Georgia where Weddell seals breed. The area was mapped by DI personnel in 1927 and by the South Georgia Survey in the period 1951–57, and named by the UK Antarctic Place-Names Committee in 1957 for William Nigel Bonner, Falkland Islands Dependencies Survey biologist who worked."},{"name":"Brighton Beach","slug":"brighton-beach","category":"Beach","country":"United Kingdom","region":"South Georgia and the South Sandwich Islands","city":null,"latitude":-54.1167,"longitude":-37.1667,"description":"Possession Bay is a bay 2 miles (3.2 km) wide on the north coast of South Georgia, an island in the southern Atlantic Ocean. It recedes southwest for 5 miles (8 km), and is separated from Cook Bay to the north by Black Head promontory. It is connected to King Haakon Bay by Shackleton Gap, a mountain pass."},{"name":"Melville Beach","slug":"melville-beach","category":"Beach","country":"Canada","region":"Saskatchewan","city":null,"latitude":50.61396,"longitude":-102.7249,"description":"Melville Beach is a resort village in the Canadian province of Saskatchewan within Census Division No. 5. It is on the shores of Crooked Lake in the Rural Municipality of Grayson No. 184."},{"name":"Dumas Beach","slug":"dumas-beach","category":"Beach","country":"India","region":"Choryasi Taluka","city":null,"latitude":21.07917,"longitude":72.71528,"description":"Dumas Beach is a rural beach along the Arabian Sea, located 21 kilometres (13 mi) southwest of the city of Surat in the Indian state of Gujarat. It is a popular tourist destination in South Gujarat. It is said to be haunted and was a burial site."},{"name":"Princetown Beach","slug":"princetown-beach","category":"Beach","country":"Australia","region":"Victoria","city":null,"latitude":-38.70685,"longitude":143.15896,"description":"Princetown Beach is a beach at the mouth of the Gellibrand River outside of Princetown, on the Great Ocean Road in south-western Victoria, Australia. The beach lies immediately east of Point Ronald and forms the westernmost part of a series of beaches extending for approximately 3 kilometres (1.9 mi) along the coast."},{"name":"Poetto","slug":"poetto","category":"Beach","country":"Italy","region":"Cagliari","city":null,"latitude":39.20169,"longitude":9.16083,"description":"Poetto is the main beach of Cagliari in Sardinia, Italy. It stretches for about 8 km, from Sella del Diavolo up to the coastline of Quartu Sant'Elena. Poetto is also the name of the district located on the western stretch of the strip between the beach and Molentargius - Saline Regional Park."},{"name":"Espiguette","slug":"espiguette","category":"Beach","country":"France","region":"Le Grau-du-Roi","city":null,"latitude":43.5,"longitude":4.12,"description":"The Pointe de l'Espiguette is a vast dune system located on the Mediterranean coast of the Gard department in France."},{"name":"Jaz Beach","slug":"jaz-beach","category":"Beach","country":"Montenegro","region":"Budva Municipality","city":null,"latitude":42.28333,"longitude":18.80472,"description":"Jaz is a beach in the Budva municipality in Montenegro. It is located 2.5 km west of central Budva. It consists of two areas, one of which measures about 850 metres and the other, formerly a nudist beach, stretches around 450 metres (0.45 km). It is unique in that it is a pebble beach; there is a campground along the main section of the beach as well, with an availability of 2,000 lots."},{"name":"Beach of A Lanzada","slug":"beach-of-a-lanzada","category":"Beach","country":"Spain","region":"Sanxenxo","city":null,"latitude":42.4494,"longitude":-8.8771,"description":"The A Lanzada beach is one of the most famous beaches in Galicia (Spain). It is located in the municipalities of O Grove and Sanxenxo in the province of Pontevedra. The blue flag has been flying there for a long time."},{"name":"Playa de Las Canteras","slug":"playa-de-las-canteras","category":"Beach","country":"Spain","region":"Canary Islands","city":null,"latitude":28.14,"longitude":-15.43611,"description":"The Playa de Las Canteras is the main urban beach of the city of Las Palmas de Gran Canaria, on the island of Gran Canaria in the Canary Islands. It is considered one of the most prominent beaches in the archipelago."},{"name":"Encuentro Beach, Dominican Republic","slug":"encuentro-beach-dominican-republic","category":"Beach","country":"Dominican Republic","region":"Cabarete","city":null,"latitude":19.7831,"longitude":-70.45135,"description":"Encuentro Beach is an isolated stretch of beach in the Puerto Plata province of the Dominican Republic. Located between the more heavily populated cities of Sosúa and Cabarete this popular surfing beach is accessible to the public via dirt roads."},{"name":"Sam Son Beach","slug":"sam-son-beach","category":"Beach","country":"Vietnam","region":null,"city":null,"latitude":19.73454,"longitude":105.90194,"description":"Sam Son beach is a resort beach in Vietnam. It’s located in Sầm Sơn city, Thanh Hóa Province, Bac Trung Bo region, Vietnam, 16 km east of Thanh Hoa City. The Sầm Sơn beach became a resort beach in 1906 when French colonists began to build facilities here. The beach is 6 km long, extending from estuary of Lạch Hới to the foot of Trường Lệ mount."},{"name":"Salar del Hombre Muerto","slug":"salar-del-hombre-muerto","category":"Beach","country":"Argentina","region":"Catamarca Province","city":null,"latitude":-25.35,"longitude":-67.07,"description":"Salar del Hombre Muerto is a salt pan in Argentina, in the Antofagasta de la Sierra Department on the border between the Salta and Catamarca Provinces. It covers an area of 600 square kilometres (230 sq mi) and is in part covered by debris. During the Pleistocene it was sometimes a lake, but today only parts of the salt pan are covered by perennial water bodies; its major tributary is the Río de los Patos."},{"name":"Pantai Senggigi","slug":"pantai-senggigi","category":"Beach","country":"Indonesia","region":"West Lombok","city":null,"latitude":-8.49972,"longitude":116.0475,"description":"Senggigi used to be the main tourist strip of the Indonesian island of Lombok, stretched out along several kilometers of the beachfront just to the north of the capital, Mataram. The site of a building frenzy in the late 1990s when Lombok was hyped to be the next Bali, the communal violence of 2000 and the 2002 Bali bombing dealt Senggigi a severe blow, with tourist numbers declining precipitously and many."},{"name":"Lara","slug":"lara","category":"Beach","country":"Turkey","region":"Muratpaşa","city":null,"latitude":36.84921,"longitude":30.81293,"description":"Lara is a district of Antalya city, Turkey. Lara is a balneoclimatic and balneoclimateric location bordering the Mediterranean Sea. It is home to many luxury-themed hotels, mainly at the popular Lara Beach area which includes the Aksu and Muratpaşa municipalities of Antalya province. Most of the hotels are replicas of famous places around the world, luxury design hotels and theme hotels with All inclusive concept."},{"name":"Santa Barbara Beach, Curaçao","slug":"santa-barbara-beach-cura-ao","category":"Beach","country":"Curaçao","region":null,"city":null,"latitude":12.05833,"longitude":-68.83333,"description":"Santa Barbara Beach is a private beach on the Dutch Caribbean island of Curaçao, located at the southeast of island."},{"name":"Sa Caleta","slug":"sa-caleta","category":"Beach","country":"Spain","region":"Sant Josep de sa Talaia","city":null,"latitude":38.86889,"longitude":1.33472,"description":"Sa Caleta is a cove on the south west seaboard of the Spanish island of Ibiza. The cove is in the municipality of Sant Josep de sa Talaia and is 6.8 miles (10.9 km) west of the town of Ibiza town. The village of Sant Josep de sa Talaia is 5.7 miles (9.2 km) east of the cove.61562871399953"},{"name":"Playa de Levante","slug":"playa-de-levante","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.18991,"longitude":-5.33137,"description":"Playa de Levante is a beach in the municipality of La Línea de la Concepción, in the Province of Cádiz, Andalusia, Spain, located to the north of Gibraltar. It has a length of about 2.2 kilometres (1.4 mi) and average width of about 30 metres (98 ft). It is a busy beach promenade enclosed by the city and on the south by the Playa de Santa Bárbara and the north of Playa de La Atunara."},{"name":"Playa de Santa Bárbara","slug":"playa-de-santa-b-rbara","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.16754,"longitude":-5.33704,"description":"Playa de Santa Bárbara is a beach in the municipality of La Línea de la Concepción, in the Province of Cádiz, Andalusia, Spain, located to the north of Gibraltar. It has a length of about 700 metres (2,300 ft) and average width of about 40 metres (130 ft)."},{"name":"Playa de Poniente","slug":"playa-de-poniente","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.16203,"longitude":-5.35736,"description":"Playa de Poniente is a beach in the municipality of La Línea de la Concepción, in the Province of Cádiz, Andalusia, Spain, located to the northwest of Gibraltar. It has a length of about 800 metres (2,600 ft) and average width of about 20 metres (66 ft)."},{"name":"La Alcaidesa beach","slug":"la-alcaidesa-beach","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.23306,"longitude":-5.31447,"description":"Playa de La Alcaidesa is a beach in the municipalities of La Línea de la Concepción and San Roque, in the Province of Cádiz, Andalusia, Spain. It is a blue flag beach with calm waters, unspoilt vegetation, and relatively low-medium occupancy. The beach is accessed from the nearby coastal town of La Alcaidesa. It has a length of about 4.3 kilometres (2.7 mi) and average width of about 60 metres (200 ft)."},{"name":"Playa de Torrenueva","slug":"playa-de-torrenueva","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.20647,"longitude":-5.32579,"description":"Playa de Torrenueva is a beach in the municipality of La Línea de la Concepción, in the Province of Cádiz, Andalusia, Spain, located to the northeast of Gibraltar. It has a length of about 1,250 metres (4,100 ft) and average width of about 120 metres (390 ft). It is a busy little beach north of the city and bordered on the south by the Playa de La Atunara and north by the Playa de La Hacienda."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 3: % places added', added;
end $$;

-- batch 4 of 6: 150 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Playa de La Hacienda","slug":"playa-de-la-hacienda","category":"Beach","country":"Spain","region":"La Línea de la Concepción","city":null,"latitude":36.2323,"longitude":-5.31363,"description":"Playa de La Hacienda is a beach in the municipality of La Línea de la Concepción, in the Province of Cádiz, Andalusia, Spain. It has a length of about 4.3 kilometres (2.7 mi) and average width of about 90 metres (300 ft). It is a busy beach north of the city and bordered to the south with the Playa de Torrenueva and to the north with the Playa de La Alcaidesa."},{"name":"Blackpool Sands","slug":"blackpool-sands","category":"Beach","country":"United Kingdom","region":"Blackpool","city":null,"latitude":53.816,"longitude":-3.058,"description":"Blackpool is a seaside town in Lancashire, England. It is located on the Irish Sea coast of the Fylde peninsula, approximately 27 miles (43 km) north of Liverpool and 14 miles (23 km) west of Preston. It is the main settlement in the borough of the same name."},{"name":"Blosseville Coast","slug":"blosseville-coast","category":"Beach","country":"Greenland","region":"Sermersooq","city":null,"latitude":68.75,"longitude":-26.41667,"description":"The Blosseville Coast is a long stretch of coastline in King Christian IX Land, eastern Greenland. Administratively it belongs to the Sermersooq Municipality."},{"name":"Bluefields Beach","slug":"bluefields-beach","category":"Beach","country":"Jamaica","region":"Westmoreland Parish","city":null,"latitude":18.17142,"longitude":-78.0305,"description":"Bluefields Beach Park is a public beach in Bluefields in the south-east of Westmoreland, Jamaica. It gets very busy at weekends and holidays."},{"name":"Boat Harbour","slug":"boat-harbour","category":"Beach","country":"Australia","region":"New South Wales","city":null,"latitude":-34.0378,"longitude":151.201,"description":"Boat Harbour is a small beach located on the southern side of the Botany Bay National Park in Kurnell, Sydney, New South Wales, Australia."},{"name":"Boiçucanga","slug":"boi-ucanga","category":"Beach","country":"Brazil","region":"São Sebastião","city":null,"latitude":-23.78306,"longitude":-45.62444,"description":"Boiçucanga is a beach and neighborhood in the city of São Sebastião, Brazil, located on São Paulo state's northern coastline. The name comes from the Tupiniquim Indian language. Boi means snake. Açu means big and Canga means head. The sea at the beach is calm and has thick, yellowish sand. The water is a crystal turquoise color."},{"name":"Bolata","slug":"bolata","category":"Beach","country":"Bulgaria","region":"Kavarna","city":null,"latitude":43.38194,"longitude":28.47083,"description":"Bolata is a small cove and Nature reserve located in the Northern Bulgarian Black Sea Coast."},{"name":"Boulder Beach","slug":"boulder-beach","category":"Beach","country":"New Zealand","region":"Dunedin City","city":null,"latitude":-45.8971,"longitude":170.613,"description":"Boulder Beach is a rocky beach on the Pacific Ocean, located on the south side of Otago Peninsula, some 15.7 kilometres (9.8 mi) by road east from central Dunedin, New Zealand. In addition to being relatively difficult to access physically due to the steepness of the surrounding country, it is closed to the public in the summer months (November–February) to protect the yellow-eyed penguins that nest on it."},{"name":"Jones Beach","slug":"jones-beach","category":"Beach","country":"Australia","region":"New South Wales","city":null,"latitude":-34.64,"longitude":150.855,"description":"Jones Beach, also known as Boyds Beach, is a beach on the south-eastern coast of Australia, facing the Tasman Sea. The beach is east of the settlement of Kiama Downs and about 2 kilometres (1.2 mi) south by east of the settlement of Minnamurra in the Illawarra and South Coast regions of New South Wales."},{"name":"Brandy Cove","slug":"brandy-cove","category":"Beach","country":"United Kingdom","region":"Bishopston","city":null,"latitude":51.5672,"longitude":-4.04194,"description":"Brandy Cove is a very small beach in the Gower Peninsula, south Wales, that is much less accessible than Caswell Bay immediately to the east. It is set at the end of a valley from Bishopston village. It is reachable by footpath from Bishopston or from Caswell Bay over some steep cliffs."},{"name":"Amazon rainforest","slug":"amazon-rainforest","category":"Forest","country":"France","region":null,"city":null,"latitude":-3.16,"longitude":-60.03,"description":"The Amazon rainforest, also called the Amazon jungle, Amazonia, or simply the Amazon, is a moist broadleaf tropical rainforest in the Amazon biome that covers most of the Amazon basin of South America. This basin encompasses 7 million km2 (2.7 million sq mi), of which 6 million km2 (2.3 million sq mi) are covered by the rainforest."},{"name":"Beijing Xishan National Forest Park","slug":"beijing-xishan-national-forest-park","category":"Forest","country":"People's Republic of China","region":"Sijiqing","city":null,"latitude":39.9754,"longitude":116.1866,"description":"Beijing West Mountain National Forest Park is located in Beijing's western suburbs, spanning across Haidian, Shijingshan, and Mentougou Districts. With a total area of 59.7-square-kilometre (23.1 sq mi), it is recognized as a National Forest Park and a AAA-level tourist attraction."},{"name":"Coromandel Forest Park","slug":"coromandel-forest-park","category":"Forest","country":"New Zealand","region":"Thames-Coromandel District","city":null,"latitude":-37.04556,"longitude":175.66028,"description":"Coromandel Forest Park is a protected area and conservation park administered by the Department of Conservation, covering 71,899 hectares of the Coromandel Peninsula, in the Thames Coromandel District of the Waikato Region."},{"name":"North-west Nelson Forest Park","slug":"north-west-nelson-forest-park","category":"Forest","country":"New Zealand","region":"Tasman District","city":null,"latitude":-40.781,"longitude":172.433,"description":"North-west Nelson Forest Park, also spelled Northwest Nelson Forest Park and North West Nelson Forest Park, is a forest park that was initially very large and managed by the New Zealand Forest Service until the Department of Conservation was formed in 1987. It existed in its initial form from 1970 until 1996, when most of it became Kahurangi National Park."},{"name":"Grmoščica Forest Park","slug":"grmo-ica-forest-park","category":"Forest","country":"Croatia","region":"Stenjevec","city":null,"latitude":45.81761,"longitude":15.917,"description":"Grmoščica or Grmošćica is a hill on Medvednica mountain in central Croatia, just north of Zagreb. Its highest peak is 239 m."},{"name":"Brierley Forest Park","slug":"brierley-forest-park","category":"Forest","country":"United Kingdom","region":"Ashfield","city":null,"latitude":53.134,"longitude":-1.286,"description":"Brierley Forest Park, Sutton in Ashfield was designated a Local Nature Reserve in 2006. It contains Calcareous grassland, sown grassland, wildflower meadows with hoary ragwort, yellow-wort, wild carrot and lesser trefoil. There are four wetland feature areas, Brierley Waters, a reed swamp, Rooley Brook and the visitor centre pond. There are species rich hedgerows, woodland and semi natural vegetation."},{"name":"Deuchny Wood","slug":"deuchny-wood","category":"Forest","country":"United Kingdom","region":"Perth and Kinross","city":null,"latitude":56.39768,"longitude":-3.37456,"description":"Deuchny Wood is a Forestry and Land Scotland site in Perth, Scotland. 350.36 acres (141.79 ha) in size, it is adjacent to Kinnoull Hill Woodland Park, of which Deuchny Hill is one of the five constituent hills."},{"name":"Nopporo Shinrin Kouen Prefectural Natural Park","slug":"nopporo-shinrin-kouen-prefectural-natural-park","category":"Forest","country":"Japan","region":"Ebetsu","city":null,"latitude":43.0525,"longitude":141.50056,"description":"Nopporo Shinrin Kōen Prefectural Natural Park is a Prefectural Natural Park in western Hokkaidō, Japan. Established in 1968, the park spans the municipalities of Ebetsu, Kitahiroshima, and Sapporo."},{"name":"Hokkaido Maruseppu Recreation Forest Park Railway","slug":"hokkaido-maruseppu-recreation-forest-park-railway","category":"Forest","country":"Japan","region":"Engaru","city":null,"latitude":43.93142,"longitude":143.33614,"description":"The Hokkaido Maruseppu Recreation Forest Park Railway or Maruseppu Forest Park Ikoi-no-Mori Railway is an approximately 1.24 miles (2.00 km) long narrow gauge heritage railway with a track gauge of 2 ft 6 in near the Japanese City of Engaru near Mombetsu in the Okhotsk Subprefecture on the island Hokkaidō."},{"name":"Musashi Kyūryō National Government Park","slug":"musashi-ky-ry-national-government-park","category":"Forest","country":"Japan","region":"Namegawa","city":null,"latitude":36.0863,"longitude":139.37,"description":"Musashi Kyūryō National Government Park is a national government park located on the Hiki Hills of the town of Namegawa, Saitama Prefecture, Japan. It is also known as a National forest park. In 1974, it opened as the first National Government Park. The park covers a vast area of forest and offers opportunities for various outdoor activities."},{"name":"Aichiken Forest Park","slug":"aichiken-forest-park","category":"Forest","country":"Japan","region":"Owariasahi","city":null,"latitude":35.2352,"longitude":137.052,"description":"Aichiken Forest Park is a forest park located in the area encompassing Owariasahi and Moriyama-ku, Nagoya, Aichi. In its vast forest of about 468 hectares, it also includes a botanical garden and various sports facilities, such as tennis courts, baseball and archery fields, a horse riding course, a golf course, and sports plazas."},{"name":"Higashitakane Site","slug":"higashitakane-site","category":"Forest","country":"Japan","region":"Shiboku-Honchō","city":null,"latitude":35.60444,"longitude":139.58639,"description":"The Higashitakane site is an archaeological site with the traces of a settlement group existing from the Yayoi to Kofun period, located in Miyamae-ku, Kawasaki, Kanagawa Prefecture in the Kantō region of Japan. It was designated a Kanagawa Prefecture Historic Site in 1971."},{"name":"Jingyuetan National Forest Park","slug":"jingyuetan-national-forest-park","category":"Forest","country":"People's Republic of China","region":"Jilin","city":null,"latitude":43.78278,"longitude":125.45833,"description":"Jingyuetan National Forest Park is a forest park and tourist attraction in Changchun, Jilin. 18km southeast of the city, the park covers over 100 square kilometers. The park was created in 1934, approved as a forest park in 1989 and the lake was listed as a key national scenic area in 1998. According to the government of Changchun, the park is the largest man-made forest in Asia."},{"name":"Nanling National Forest Park","slug":"nanling-national-forest-park","category":"Forest","country":"People's Republic of China","region":"Ruyuan Yao Autonomous County","city":null,"latitude":24.91329,"longitude":113.08273,"description":"Nanling National Forest Park is located in Ruyuan Yao Autonomous County, Shaoguan City, Guangdong Province, China, near Mangshan in Hunan Province. It lies in the core area of the Nanling Mountains and is the largest nature reserve in Guangdong Province, with a total area of approximately 273 square kilometers."},{"name":"Nazhvan Forest Park","slug":"nazhvan-forest-park","category":"Forest","country":"Iran","region":"Isfahan","city":null,"latitude":32.64111,"longitude":51.605,"description":"The Nazhvan Forest Park is one of the few gardens in Isfahan, which has been rather safe from expansion and development of the city and freshens the air of Isfahan. The word nazhvan consists of two words nazh, which means \"poplar\" in Persian and van, which is a Persian suffix for place. Therefore nazhvan means \"a place for poplars\". Nazhvan has an area of 1200 ha and is located in the western part of the city."},{"name":"Sustipan","slug":"sustipan","category":"Forest","country":"Croatia","region":"Meje","city":null,"latitude":43.501,"longitude":16.425,"description":"Sustipan is a small peninsula located in the southwestern part of Split. In Middle Ages there was a Benedictine monastery and a church. In the 19th century one of the most beautiful cemeteries of the whole Croatia was built in Sustipan. The cemetery was removed in the 20th century by the Communist authorities, the reason why they did that was never found."},{"name":"Mount Guanyin (Dongguan)","slug":"mount-guanyin-dongguan","category":"Forest","country":"People's Republic of China","region":null,"city":null,"latitude":22.91152,"longitude":114.10341,"description":"The Mount Guanyin also known as the National Forest Park of Mount Guanyin, is a 488-metre (1,601 ft) mountain on the border of Dongguan and Shenzhen in Zhangmutou Town of Dongguan, south China's Guangdong province. On December 28, 2009, it has been categorized as a 4A level tourist site by the National Tourism Administration."},{"name":"Sorkheh Hesar National Park","slug":"sorkheh-hesar-national-park","category":"Forest","country":"Iran","region":"Tehran Province","city":null,"latitude":35.65833,"longitude":51.575,"description":"Sorkheh Hesar National Park lies with an area of 9,380 hectares and stands at an altitude of 1,547 metres (5,075 ft) above sea-level, near by Ray - Tehran 20th District, Tehran, Iran. The whole of this forest park, except the northeastern part has been managed by Iran Environmental Protection Organization since 1980. The major portion of this territory is a base for migrating birds during winter."},{"name":"Maksimir Park","slug":"maksimir-park","category":"Forest","country":"Croatia","region":"Maksimir","city":null,"latitude":45.82964,"longitude":16.02047,"description":"Maksimir Park is a 316-hectares (780-acres), historic public park in Maksimir, Zagreb. Often called Hyde Park or Central Park of Zagreb, it is the oldest and largest of the parks and green spaces founded by Bishop Maksimilijan Vrhovac, which was named after him. Situated in the eastern part of the city, it spans approximately 316 hectares of landscaped grounds, woodlands, meadows, and five artificial lakes."},{"name":"Pardisan Park","slug":"pardisan-park","category":"Forest","country":"Iran","region":"District 2","city":null,"latitude":35.74556,"longitude":51.35417,"description":"Pardisan Park is a complex covering more than 270 hectares, located in the northwest of Tehran, Iran. It is connected to Hemmat Expressway in the north, and to Sheikh Nouri Expressway in the east."},{"name":"Marjan","slug":"marjan","category":"Forest","country":"Croatia","region":"Varoš","city":null,"latitude":43.50855,"longitude":16.40934,"description":"Marjan is a hill on the peninsula of the city of Split, the second largest city of Croatia. It is covered in a dense Mediterranean pine forest and completely surrounded by the city and the sea, making it a unique sight. Originally used as a park by the citizens as early as the 3rd century, it is a favorite weekend excursion destination and a recreational center for the city."},{"name":"Gongqing Forest Park","slug":"gongqing-forest-park","category":"Forest","country":"People's Republic of China","region":"Yangpu District","city":null,"latitude":31.32182,"longitude":121.54577,"description":"Gongqing Forest Park is the second-largest park in the city of Shanghai. It is located in the Yangpu District in the north section of the city. To reach the park you can take line 8 on the metro to Shiguang Road. From the metro station the park is a less than 1 km; walk or take a very short taxi ride to it. Being further out the park is somewhat less crowded than Century Park, the largest park of the city."},{"name":"Chitgar Park","slug":"chitgar-park","category":"Forest","country":"Iran","region":"District 22","city":null,"latitude":35.73,"longitude":51.2083,"description":"Chitgar Park is a forest park situated in western Tehran, Iran. It covers an area of about 14.5 square kilometer."},{"name":"Curraghchase Forest Park","slug":"curraghchase-forest-park","category":"Forest","country":"Ireland","region":null,"city":null,"latitude":52.58565,"longitude":-8.88972,"description":"Curraghchase is a 774-acre (3 km2) forest park located in County Limerick. It is 20 km from the city of Limerick, between the towns of Adare and Askeaton. The land was the Hunt/de Vere family estate for 300 years (1657–1957), including the period of the de Vere baronets, also serving as the home of renowned poet and critic Aubrey Thomas De Vere."},{"name":"Galloway Forest Park","slug":"galloway-forest-park","category":"Forest","country":"United Kingdom","region":"Dumfries and Galloway","city":null,"latitude":55.12386,"longitude":-4.4239,"description":"Galloway Forest Park is a forest park operated by Forestry and Land Scotland, principally covering woodland in the historic counties of Kirkcudbrightshire and Wigtownshire in the administrative area of Dumfries and Galloway. It is claimed to be the largest forest in the UK. The park was granted Dark Sky Park status in November 2009, being the first area in the UK to be so designated."},{"name":"Lavizan Forest Park","slug":"lavizan-forest-park","category":"Forest","country":"Iran","region":"District 4","city":null,"latitude":35.76883,"longitude":51.50994,"description":"Lavizan is a forest park located in Shemiranat County in Tehran Province, Iran. Lavizan Forest Park is a recreation area used by people from Lavizan and Tehran. Its area is about 1100 hectares."},{"name":"Kuhsar Forest Park","slug":"kuhsar-forest-park","category":"Forest","country":"Iran","region":"District 5","city":null,"latitude":35.78111,"longitude":51.28389,"description":"Koohsar Shahran Park is a forest park located in shahran, northern Tehran, Iran. It covers an area of about 10 square kilometers, and includes ramps and facilities for cycling and skating. Koohsar Shahran Park has 2 main entrances, One on Koohsar Boulevard and another on Shahran Boulevard. Also, Koohsar Shahran is Tehran's largest forest park."},{"name":"New Caledonia dry forests","slug":"new-caledonia-dry-forests","category":"Forest","country":"France","region":"New Caledonia","city":null,"latitude":-21.5,"longitude":165.2,"description":"The New Caledonia dry forests is a tropical dry broadleaf forest ecoregion in New Caledonia, an overseas territory of France located in the South Pacific Ocean. The dry forests cover the western side of Grand Terre, New Caledonia's largest island."},{"name":"Nijinomatsubara","slug":"nijinomatsubara","category":"Forest","country":"Japan","region":"Karatsu","city":null,"latitude":33.44664,"longitude":130.02832,"description":"The Nijinomatsubara (虹之松原) is a pine forest stretching along the sand dunes of Matsuragata, in the innermost part of Karatsu Bay, which faces the Genkai Sea in northern Kyushu. Located in the city of Karatsu, Saga Prefecture, it is considered one of Japan's three great pine groves, along with Miho no Matsubara and Amanohashidate, and is a nationally designated Special Place of Scenic Beauty."},{"name":"Barm Plain","slug":"barm-plain","category":"Forest","country":"Iran","region":"Dasht-e Barm Rural District","city":null,"latitude":29.55,"longitude":51.9,"description":"Dasht-e Barm Forest, also known as Mian Kotal Recreation Area, is the largest oak forest in Iran and the Middle East. It is located in the central district of Kazerun County, southwestern Iran. The forest is part of the Arjan and Parishan Protected Area, listed by UNESCO as a Biosphere Reserve."},{"name":"St. Gobnet's Wood","slug":"st-gobnets-wood","category":"Forest","country":"Ireland","region":null,"city":null,"latitude":51.9414,"longitude":-9.16667,"description":"St Gobnet's Wood is a protected area of oak woodland at Baile Bhuirne, County Cork, Ireland. It is on the north-east side of a hill immediately south of the village, and takes its name from the church of Saint Gobnait which is also nearby. Along with Cascade Wood, St Gobnet's Wood is included in a fragmented Special Area of Conservation."},{"name":"Carballeira de San Xusto","slug":"carballeira-de-san-xusto","category":"Forest","country":"Spain","region":"San Xurxo de Sacos","city":null,"latitude":42.51694,"longitude":-8.51111,"description":"The Carballeira de San Xusto is an oak forest located in the parish of San Xurxo de Sacos (Cerdedo-Cotobade), on a hill above the Lérez River, near the Ria de Pontevedra, in Galicia, Spain."},{"name":"Salonga National Park","slug":"salonga-national-park","category":"Forest","country":"Democratic Republic of the Congo","region":"Kasaï-Occidental","city":null,"latitude":-2.0,"longitude":21.0,"description":"Salonga National Park is a national park in the Democratic Republic of the Congo located in the Congo River basin. It is Africa's largest tropical rainforest reserve covering about 36,000 km2 or 3,600,000 hectares. It extends into the provinces of Mai Ndombe, Equateur, Kasaï and Sankuru."},{"name":"Forest of Retz","slug":"forest-of-retz","category":"Forest","country":"France","region":"Corcy","city":null,"latitude":49.2593,"longitude":3.09242,"description":"The Forest of Retz is one of the largest forests of France, covering some 13,000 hectares in the Aisne about 80 km northeast of Paris. It is a national forest in the former Picardy region."},{"name":"Forest of Saint-Germain-en-Laye","slug":"forest-of-saint-germain-en-laye","category":"Forest","country":"France","region":"Yvelines","city":null,"latitude":48.93949,"longitude":2.09652,"description":"The Forest of Saint-Germain-en-Laye or Forêt de Saint-Germain-en-Laye, is a dominial forest of 35 km2 (14 sq mi) in area which lies in a meander of the River Seine, France. Situated 20 km (12 mi) West of Paris, between Saint-Germain-en-Laye, Maisons-Laffitte, Achères and Poissy, It is situated entirely within the commune of Saint-Germain."},{"name":"Pays-de-Monts National Forest","slug":"pays-de-monts-national-forest","category":"Forest","country":"France","region":null,"city":null,"latitude":46.73083,"longitude":-1.98444,"description":"The Pays-de-Monts national forest, also known as the Monts forest, is a French national forest stretching over the dunes of the northern Vendée coast."},{"name":"Forest of la Coubre","slug":"forest-of-la-coubre","category":"Forest","country":"France","region":"Saint-Augustin","city":null,"latitude":45.75,"longitude":-1.2,"description":"The Forest of la Coubre is a large forest in the region of Nouvelle-Aquitaine, France, near the city of Royan. Its area is roughly 7916 hectares, making it the third largest forêt domaniale of the north of the region, behind forest of la Double and the forest d'Horte."},{"name":"Rainforests of the Atsinanana","slug":"rainforests-of-the-atsinanana","category":"Forest","country":"Madagascar","region":"Atsinanana","city":null,"latitude":-14.45972,"longitude":49.7025,"description":"The Rainforests of the Atsinanana is a World Heritage Site that was inscribed in 2007 and consists of 13 specific areas in six national parks in the eastern part of Madagascar:Marojejy National Park Masoala National Park Zahamena National Park Ranomafana National Park Andringitra National Park Andohahela National Park"},{"name":"Three Parallel Rivers National Park","slug":"three-parallel-rivers-national-park","category":"Forest","country":"People's Republic of China","region":null,"city":null,"latitude":27.895,"longitude":98.40639,"description":"The Three Parallel Rivers of Yunnan Protected Areas is a UNESCO World Heritage Site in Yunnan province, China. It lies within the drainage basins of the upper reaches of the Jinsha (Yangtze), Lancang (Mekong) and Nujiang (Salween) rivers, in the Yunnan section of the Hengduan Mountains."},{"name":"Osun-Osogbo Grove","slug":"osun-osogbo-grove","category":"Forest","country":"Nigeria","region":"Osun State","city":null,"latitude":7.75491,"longitude":4.55063,"description":"Osun-Osogbo is a sacred grove along the banks of the Osun river just outside the city of Osogbo, Osun State of Nigeria."},{"name":"Gondwana Rainforests of Australia","slug":"gondwana-rainforests-of-australia","category":"Forest","country":"Australia","region":"New South Wales","city":null,"latitude":-29.6,"longitude":149.6,"description":"The Gondwana Rainforests of Australia, formerly known as the Central Eastern Rainforest Reserves, are a World Heritage Site, encompassing 41 rainforest reserves with a total area of approximately 370,000 ha in north-east New South Wales and south-east Queensland. The site was added to the World Heritage List in 1986 and was expanded in 1994."},{"name":"Ituri rainforest","slug":"ituri-rainforest","category":"Forest","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":1.55712,"longitude":28.4491,"description":"The Ituri Rainforest is a rainforest located in the Ituri Province of northeastern Democratic Republic of the Congo. The forest's name derives from the nearby Ituri River which flows through the rainforest, connecting firstly to the Aruwimi River and finally into the Congo."},{"name":"Fraser Plateau and Basin complex","slug":"fraser-plateau-and-basin-complex","category":"Forest","country":"Canada","region":null,"city":null,"latitude":54.0,"longitude":-126.0,"description":"The Fraser Plateau and Basin Complex is an ecoregion defined by the World Wildlife Fund. It encompasses the middle reaches of the watershed of the Fraser River as it traverses the northern part of the Interior Plateau of British Columbia. The WWF ecoregion is similar in description to two of the ecoregions within Environment Canada's Montane Cordillera Ecozone: The Fraser Basin and the Fraser Plateau."},{"name":"Hoh Rainforest","slug":"hoh-rainforest","category":"Forest","country":"United States","region":"Washington","city":null,"latitude":47.8614,"longitude":-123.925,"description":"Hoh Rainforest is one of the largest temperate rainforests in the United States, located on the Olympic Peninsula in western Washington state. It encompasses 24 square miles (62 km2) of low elevation forest along the Hoh River, ranging from 394 to 2,493 feet. The rainforest receives an average of 140 inches (360 cm) of annual precipitation—among the rainiest places in the United States."},{"name":"El Yunque National Forest","slug":"el-yunque-national-forest","category":"Forest","country":"United States","region":"Puerto Rico","city":null,"latitude":18.31667,"longitude":-65.78333,"description":"El Yunque National Forest, most commonly known as El Yunque, is a tropical rainforest with cultural, historical, ecological, scientific, and recreational features in the Sierra de Luquillo mountain subrange in the northeast of the main island of Puerto Rico, managed by the U.S. Forest Service since 1903."},{"name":"Congo","slug":"congo","category":"Forest","country":"Angola","region":"Republic of the Congo","city":null,"latitude":-5.0,"longitude":20.0,"description":"The Congo Basin is the sedimentary basin of the Congo River. The Congo Basin is located in Central Africa, in a region known as west equatorial Africa. The region is sometimes known simply as the Congo. It contains some of the largest tropical rainforests in the world and is an important source of water used in agriculture and energy generation."},{"name":"Caledonian Forest","slug":"caledonian-forest","category":"Forest","country":"United Kingdom","region":"Scotland","city":null,"latitude":57.12,"longitude":-4.71,"description":"The Caledonian Forest is the ancient (old-growth) temperate forest of Scotland. The forest today is a reduced-extent version of the pre-human-settlement forest, existing in several dozen remnant areas."},{"name":"Great Bear Rainforest","slug":"great-bear-rainforest","category":"Forest","country":"Canada","region":"British Columbia","city":null,"latitude":54.57142,"longitude":-129.96316,"description":"The Great Bear Rainforest is a temperate rain forest on the Pacific coast of British Columbia, comprising 6.4 million hectares. It is part of the larger Pacific temperate rainforest ecoregion, which is the largest coastal temperate rainforest in the world."},{"name":"Scandinavian coastal conifer forests","slug":"scandinavian-coastal-conifer-forests","category":"Forest","country":"Norway","region":null,"city":null,"latitude":60.55,"longitude":5.53333,"description":"The Scandinavian coastal conifer forests or Norwegian coastal conifer forest is a Palearctic ecoregion in the temperate coniferous forests biome, located along the coast of Norway. Within it are a number of small areas with botanical features and a local climate consistent with a temperate rainforest."},{"name":"Alberta-British Columbia foothills forests","slug":"alberta-british-columbia-foothills-forests","category":"Forest","country":"Canada","region":null,"city":null,"latitude":55.0,"longitude":-120.0,"description":"The Alberta–British Columbia foothills forests are a temperate coniferous forests ecoregion of Western Canada, as defined by the World Wildlife Fund (WWF) categorization system. This ecoregion borders Canada's taiga and contains a mix of subarctic forest and temperate forest species as a result. This makes the region an ecotone region, or a region that acts as a buffer between two other biomes."},{"name":"Alberta Mountain forests","slug":"alberta-mountain-forests","category":"Forest","country":"Canada","region":null,"city":null,"latitude":53.0,"longitude":-118.0,"description":"The Alberta Mountain forests are a temperate coniferous forests ecoregion of Western Canada, as defined by the World Wildlife Fund (WWF) categorization system."},{"name":"North Central Rockies forest","slug":"north-central-rockies-forest","category":"Forest","country":"United States","region":null,"city":null,"latitude":49.0,"longitude":-115.0,"description":"The North Central Rockies forests is a temperate coniferous forest ecoregion of Canada and the United States. This region overlaps in large part with the North American inland temperate rainforest and gets more rain on average than the South Central Rockies forests and is notable for containing the only inland populations of many species from the Pacific coast."},{"name":"Western Himalayan subalpine conifer forests","slug":"western-himalayan-subalpine-conifer-forests","category":"Forest","country":"India","region":null,"city":null,"latitude":28.0,"longitude":84.0,"description":"The Western Himalayan subalpine conifer forests is a temperate coniferous forests ecoregion of the middle and upper elevations of the western Middle Himalayas of Nepal, India, and Pakistan."},{"name":"Dresden Heath","slug":"dresden-heath","category":"Forest","country":"Germany","region":"Dresden","city":null,"latitude":51.09556,"longitude":13.83806,"description":"The Dresden Heath is a large forest in the city of Dresden, Germany. The heath is the most important recreation area in the city and is also actively forested. Approximately 6,133 hectares of the Dresden Heath are designated as a nature preserve, making it one of the largest municipal forests in Germany by area."},{"name":"Kurapaty","slug":"kurapaty","category":"Forest","country":"Belarus","region":"Minsk District","city":null,"latitude":53.9655,"longitude":27.61133,"description":"Kurapaty is a wooded area on the outskirts of Minsk, Belarus, where a vast number of people were executed between 1937 and 1941 during the Great Purge by the Soviet secret police, the NKVD and in particular, during the Soviet repressions in Belarus."},{"name":"Cedars of God","slug":"cedars-of-god","category":"Forest","country":"Lebanon","region":"Zgharta District","city":null,"latitude":34.24361,"longitude":36.04833,"description":"The Cedars of God is a forest in the Kadisha Valley of Bsharre, Lebanon. It is a vestige of the extensive forests of the Lebanon cedar that thrived across Mount Lebanon in antiquity. Early modern travelers' accounts of the wild cedars appear to refer to the ones in Bsharri; the Christian monks of the monasteries in the Kadisha Valley venerated the trees for centuries."},{"name":"Khimki Forest","slug":"khimki-forest","category":"Forest","country":"Russia","region":"Moscow Oblast","city":null,"latitude":55.935,"longitude":37.44667,"description":"Khimki Forest is a forest near the Russian city of Moscow covering about 1000 hectares. It is part of the so-called \"Green Belt\" around Moscow. An $8 billion high speed road, the Moscow–Saint Petersburg motorway (M11), was proposed in the aughts to go through the forest to connect Moscow and Saint Petersburg. The proposed road called for the removal of a swath of the forest."},{"name":"Veldensteiner Forst","slug":"veldensteiner-forst","category":"Forest","country":"Germany","region":"Bayreuth","city":null,"latitude":49.6844,"longitude":11.5192,"description":"The Veldenstein Forest lies in the east of the Franconian Switzerland-Veldenstein Forest Nature Park between the towns of Pegnitz and Plech."},{"name":"De Zeezuiper","slug":"de-zeezuiper","category":"Forest","country":"Netherlands","region":"Bergen op Zoom","city":null,"latitude":51.4943,"longitude":4.32883,"description":"De Zeezuiper is a wetland and former peat-extraction area east of Bergen op Zoom, in the Dutch province of North Brabant. The area originated from medieval peat extraction and later became a large body of water. Its name refers to its capacity to absorb large quantities of water, described as being able to “drink up” water like the sea."},{"name":"Mariposa Grove","slug":"mariposa-grove","category":"Forest","country":"United States","region":"Mariposa County","city":null,"latitude":37.50972,"longitude":-119.60169,"description":"Mariposa Grove is a sequoia grove located near Wawona, California, United States, in the southernmost part of Yosemite National Park. It is the largest grove of giant sequoias in the park, with several hundred mature specimens. Two of its trees are among the 30 largest giant sequoias in the world. The grove attracts about one million visitors annually."},{"name":"Belgrad Forest","slug":"belgrad-forest","category":"Forest","country":"Turkey","region":"Istanbul Province","city":null,"latitude":41.1947,"longitude":28.9514,"description":"Belgrad Forest is a mixed deciduous forest lying adjacent to Istanbul, Turkey. It is named after the village next to the forest, settled by thousands of Serbs who were deported to the capital Constantinople from the city of Belgrade in 1521, when it fell to the Ottomans. Geographically, the forest is located at the easternmost point of the Thracian Peninsula."},{"name":"Slieveanorra Forest","slug":"slieveanorra-forest","category":"Forest","country":"United Kingdom","region":"County Antrim","city":null,"latitude":55.0425,"longitude":-6.21167,"description":"Slieveanorra Forest is situated in the rural north of County Antrim, Northern Ireland, near the villages of Corkey and Newtown Crommelin. The forest is a vast conifer forest, and the summit of Orra Mountain offers panoramic views. The forest is a working forest, and there are many types of plant and wildlife in the area. The forest has a memorial at the site of a 1942 airplane crash that killed ten people."},{"name":"Carson National Forest","slug":"carson-national-forest","category":"Forest","country":"United States","region":"New Mexico","city":null,"latitude":36.51038,"longitude":-106.07511,"description":"Carson National Forest is a national forest in northern New Mexico, United States. It encompasses 6,070 square kilometers and is administered by the United States Forest Service. The Forest Service's \"mixed use\" policy allows for its use for recreation, grazing, and resource extraction."},{"name":"Buena Vista State Forest","slug":"buena-vista-state-forest","category":"Forest","country":"United States","region":"Beltrami County","city":null,"latitude":47.56778,"longitude":-94.69139,"description":"The Buena Vista State Forest is a state forest located in Beltrami County, Minnesota. The Minnesota Department of Natural Resources manages 18,693 acres (7,565 ha) of state lands, with the majority of the forest split between private and other public ownership. The eastern half of the forest falls within the Chippewa National Forest, where Federal lands are managed by the United States Forest Service."},{"name":"Burntside State Forest","slug":"burntside-state-forest","category":"Forest","country":"United States","region":"St. Louis County","city":null,"latitude":47.9197,"longitude":-92.1014,"description":"The Burntside State Forest is a state forest located near the town of Ely in Lake and Saint Louis counties, Minnesota. 82% of the forest land falls within the limits of the Boundary Waters Canoe Area Wilderness to the north which belongs to the Superior National Forest, and thus falls under the federal jurisdiction of the United States Forest Service."},{"name":"Chengwatana State Forest","slug":"chengwatana-state-forest","category":"Forest","country":"United States","region":"Pine County","city":null,"latitude":45.8411,"longitude":-92.7919,"description":"The Chengwatana State Forest is a state forest located in Pine and Chisago counties in Minnesota. Its name is derived from the Ojibwe: Zhingwaadena, meaning white-pine town, after the nearby ghost town and township. Eastern White Pine was historically the dominant tree species in the surrounding forest prior to intensive logging at the end of the nineteenth century."},{"name":"Finnskogen","slug":"finnskogen","category":"Forest","country":"Sweden","region":"Trysil Municipality","city":null,"latitude":60.5,"longitude":12.75,"description":"Finnskogen is a forest area of Norway and Sweden situated in the counties of Innlandet and Värmland respectively, so named because of immigration of Finnish people in the 17th century, the so-called Forest Finns."},{"name":"Malheur National Forest","slug":"malheur-national-forest","category":"Forest","country":"United States","region":"Oregon","city":null,"latitude":44.2832,"longitude":-118.784,"description":"The Malheur National Forest is a National Forest in the U.S. state of Oregon. It contains more than 1.4 million acres (5,700 km2) in the Blue Mountains of eastern Oregon. The forest consists of high desert grasslands, sage, juniper, pine, fir, and other tree species. Elevations vary from about 4,000 feet (1,200 m) to the 9,038-foot (2,755 m) peak of Strawberry Mountain."},{"name":"Muskau Heath","slug":"muskau-heath","category":"Forest","country":"Germany","region":"Görlitz District","city":null,"latitude":51.45,"longitude":14.71667,"description":"The Muskau Heath, is a natural region in Saxony that lies south of the town of Bad Muskau. It has an area of 400 square kilometres."},{"name":"Flathead National Forest","slug":"flathead-national-forest","category":"Forest","country":"United States","region":"Montana","city":null,"latitude":48.02857,"longitude":-113.80539,"description":"The Flathead National Forest is a national forest in the western part of the U.S. state of Montana. The forest lies primarily in Flathead County, south of Glacier National Park. The forest covers 2,404,935 acres of which about 1 million acres (4,000 km2) is designated wilderness. It is named after the Flathead Native Americans who live in the area."},{"name":"Hollwinkel Wood","slug":"hollwinkel-wood","category":"Forest","country":"Germany","region":"North Rhine-Westphalia","city":null,"latitude":52.3275,"longitude":8.54222,"description":"Hollwinkel Wood is a woodland area that lies mainly on the territory of the borough of Preußisch Oldendorf in the North German county of Minden-Lübbecke. Within the wood the terrain is almost entirely level, lying between 50 and 52 metres above sea level (NN). A negligible piece of woodland in the south of only about 0.58 hectares belongs to the town of Lübbecke."},{"name":"Skuleskogen National Park","slug":"skuleskogen-national-park","category":"Forest","country":"Sweden","region":"Örnsköldsvik Municipality","city":null,"latitude":63.11098,"longitude":18.48417,"description":"Skuleskogen National Park is a Swedish national park in Västernorrland County, on the coast of the Baltic Sea, in northern Sweden. It covers 30.62 km2 (11.82 mi2), constituting the eastern part of the Forest of Skule."},{"name":"Kolmården","slug":"kolm-rden","category":"Forest","country":"Sweden","region":"Östergötland County","city":null,"latitude":58.6653,"longitude":16.4664,"description":"Kolmården is a long and wide densely forested rocky ridge that separates the Swedish provinces of Södermanland and Östergötland, two of the country's main agricultural areas, from each other, and in historic times, along with Tylöskog and Tiveden, formed the border between the land of the Swedes and the land of the Geats."},{"name":"Tiveden","slug":"tiveden","category":"Forest","country":"Sweden","region":null,"city":null,"latitude":58.78333,"longitude":14.63333,"description":"Tiveden is a long and wide densely forested rocky ridge in Sweden, throughout history notorious for its wilderness and dangers; historically a hiding place for outlaws. In historic times it, along with Tylöskog and Kolmården, formed the border between the land of the Swedes and the land of the Geats."},{"name":"Eastern Himalayan subalpine conifer forests","slug":"eastern-himalayan-subalpine-conifer-forests","category":"Forest","country":"Bhutan","region":null,"city":null,"latitude":28.0,"longitude":84.0,"description":"The Eastern Himalayan subalpine conifer forests is a temperate coniferous forests ecoregion which is found in the middle and upper elevations of the eastern Middle Himalayas, in western Nepal, Bhutan, northern Indian states including Arunachal Pradesh and Sikkim and adjacent Myanmar and China."},{"name":"Barton's Bush","slug":"bartons-bush","category":"Forest","country":"New Zealand","region":"Wellington Region","city":null,"latitude":-41.1308,"longitude":175.02915,"description":"Barton's Bush, in Trentham Memorial Park, is the largest remaining area of lowland podocarp/broadleaf mixed forest in the Hutt Valley of New Zealand. Named after Richard Barton who settled in the area in 1841, it was his desire that this section of the native forest should remain whilst the city of Upper Hutt gradually took shape and land was cleared for farming and settling."},{"name":"Fletchers Glen","slug":"fletchers-glen","category":"Forest","country":"Australia","region":"New South Wales","city":null,"latitude":-33.517,"longitude":151.367,"description":"Fletchers Glen is a small but mature temperate rainforest in Bouddi National Park in New South Wales, Australia. It provides habitat for two threatened plant species — the magenta lily pilly and the paperbark as well as the only locally known population of snowwood."},{"name":"Chimalapas montane forests","slug":"chimalapas-montane-forests","category":"Forest","country":"Mexico","region":"Oaxaca","city":null,"latitude":16.98004,"longitude":-94.43043,"description":"The Chimalapas montane forests is a tropical moist broadleaf forest ecoregion in southern Mexico. It includes the montane tropical forests of the Chimalapas region on the boundary between Chiapas and Oaxaca."},{"name":"Passa Quatro National Forest","slug":"passa-quatro-national-forest","category":"Forest","country":"Brazil","region":"Passa Quatro","city":null,"latitude":-22.38926,"longitude":-44.94684,"description":"The Passa Quatro National Forest is a national forest in the state of Minas Gerais, Brazil. It contains an area of Atlantic Forest."},{"name":"Purus National Forest","slug":"purus-national-forest","category":"Forest","country":"Brazil","region":"Amazonas","city":null,"latitude":-8.295,"longitude":-67.61444,"description":"The Purus National Forest is a national forest in the state of Amazonas, Brazil. It surrounds the shamanic-Christian community of Céu do Mapiá."},{"name":"Tefé National Forest","slug":"tef-national-forest","category":"Forest","country":"Brazil","region":"Uarini","city":null,"latitude":-3.50972,"longitude":-64.97833,"description":"The Tefé National Forest is a national forest in Amazonas, Brazil. It protects a relatively well-preserved area of Amazon rainforest to the south of the town of Tefé on the Solimões River . The resident population, scattered in small communities along the rivers, are engaged in sustainable farming, fishing and extraction of forest products."},{"name":"São Francisco de Paula National Forest","slug":"s-o-francisco-de-paula-national-forest","category":"Forest","country":"Brazil","region":"São Francisco de Paula","city":null,"latitude":-29.42278,"longitude":-50.38639,"description":"The São Francisco de Paula National Forest is a national forest in the state of Rio Grande do Sul, Brazil."},{"name":"Três Barras National Forest","slug":"tr-s-barras-national-forest","category":"Forest","country":"Brazil","region":"Três Barras","city":null,"latitude":-26.21944,"longitude":-50.305,"description":"The National Forest of Três Barras is a Federal Conservation Unit of sustainable use, managed by the Chico Mendes Institute for Biodiversity Conservation - ICMBio, in the municipality of Três Barras, Santa Catarina, Brazil."},{"name":"Rohrwald","slug":"rohrwald","category":"Forest","country":"Austria","region":"Lower Austria","city":null,"latitude":48.425,"longitude":16.325,"description":"The Rohrwald is a forest complex in the Weinviertel area of Lower Austria. With a total area of approx. 24 sq km, it represents the third largest closed forest complex in the district of Korneuburg after the Tulln Basin-Danube floodplains and the Ernstbrunn Forest."},{"name":"Zitter Forest","slug":"zitter-forest","category":"Forest","country":"Belgium","region":"Liege","city":null,"latitude":50.42167,"longitude":6.48743,"description":"The Zitter Forest is located in the Eifel region in the German district of Euskirchen and in the Belgian province of Liège (Wallonia). Its highest point is 692 m above sea level (NN)."},{"name":"bois de Boulogne","slug":"bois-de-boulogne","category":"Forest","country":"France","region":"16th arrondissement of Paris","city":null,"latitude":48.86472,"longitude":2.25083,"description":"The Bois de Boulogne is a large public park that is the western half of the 16th arrondissement of Paris, near the suburb of Boulogne-Billancourt and Neuilly-sur-Seine. The land was ceded to the city of Paris by the Emperor Napoleon III to be turned into a public park in 1852."},{"name":"forest of Fontainebleau","slug":"forest-of-fontainebleau","category":"Forest","country":"France","region":"Essonne","city":null,"latitude":48.40196,"longitude":2.66272,"description":"The forest of Fontainebleau is a mixed deciduous forest lying sixty kilometres (37 mi) southeast of Paris, France. It is located primarily in the arrondissement of Fontainebleau in the southwestern part of the department of Seine-et-Marne."},{"name":"Sierra National Forest","slug":"sierra-national-forest","category":"Forest","country":"United States","region":"California","city":null,"latitude":37.4167,"longitude":-119.167,"description":"Sierra National Forest is a U.S. national forest located on the western slope of the central Sierra Nevada in California, bounded on the northwest by Yosemite National Park and on the south by Kings Canyon National Park. The forest is known for its mountain scenery and beautiful lakes. Forest headquarters are located in Clovis, California. There are local ranger district offices in North Fork and Prather."},{"name":"Nyungwe Forest","slug":"nyungwe-forest","category":"Forest","country":"Rwanda","region":"Rwanda","city":null,"latitude":-2.52822,"longitude":29.27585,"description":"The Nyungwe Forest is located in southwestern Rwanda, on the border with Burundi, where it is contiguous with the Kibira National Park to the south, and Lake Kivu and the Democratic Republic of the Congo to the west. The Nyungwe rainforest is most likely the best preserved montane rainforest in Africa."},{"name":"Sacred Mijikenda Kaya Forests","slug":"sacred-mijikenda-kaya-forests","category":"Forest","country":"Kenya","region":"Coast Province","city":null,"latitude":-3.93194,"longitude":39.59611,"description":"A kaya is a sacred site of the Mijikenda people in the former Coast Province of Kenya. Often located within sacred forests, a kaya is considered to be an intrinsic source of ritual power and the origin of cultural identity; it is also a place of prayer for members of the Mijikenda ethnic group. The settlement, ritual centre, and fortified enclosure associated with the forest are also part of the kaya."},{"name":"Parforceheide","slug":"parforceheide","category":"Forest","country":"Germany","region":"Brandenburg","city":null,"latitude":52.3833,"longitude":13.1667,"description":"The Parforceheide between the south of Berlin and the east of Potsdam is one of the last large contiguous forest areas in the Berlin-Brandenburg metropolitan region. Although located in Brandenburg, part of the forest is owned by the state of Berlin. The basis for this was created by the permanent forest contract or century contract of 1915."},{"name":"Store Dyrehave","slug":"store-dyrehave","category":"Forest","country":"Denmark","region":"Hillerød Municipality","city":null,"latitude":55.91611,"longitude":12.3575,"description":"Store Dyrehave is a forest located to the east of the village Ny Hammersholt immediately south of Hillerød, on both sides of Københavnsvej, in North Zealand, Denmark. Consisting of conifers and beech, it was enclosed with stone walls in 1619–28 as a royal deer park for hunting. In 1680, Christian V introduced a geometrical system of roads forming a star with eight branches for par force hunting."},{"name":"Kakamega Forest","slug":"kakamega-forest","category":"Forest","country":"Kenya","region":null,"city":null,"latitude":0.26675,"longitude":34.89439,"description":"Kakamega Forest is a tropical rainforest situated in the Kakamega, Vihiga, and Nandi counties of Kenya, northwest of the capital Nairobi, and near the border with Uganda. It is Kenya's only tropical rainforest and is said to be Kenya's last remnant of the ancient Guineo-Congolian rainforest that once spanned the continent."},{"name":"Inyo National Forest","slug":"inyo-national-forest","category":"Forest","country":"United States","region":"Madera County","city":null,"latitude":37.8528,"longitude":-118.286,"description":"Inyo National Forest is a United States National Forest covering parts of the eastern Sierra Nevada of California and the White Mountains of California and Nevada. The forest hosts several superlatives, including Mount Whitney, the highest point in the contiguous United States; Boundary Peak, the highest point in Nevada; and the Ancient Bristlecone Pine Forest, which protects the oldest living trees in the world."},{"name":"Lichtenfels Forest","slug":"lichtenfels-forest","category":"Forest","country":"Germany","region":null,"city":null,"latitude":50.2,"longitude":11.03333,"description":"The Lichtenfels Forest is a forest northwest of the town of Lichtenfels in Upper Franconia in northern Bavaria, Germany."},{"name":"Kiffing","slug":"kiffing","category":"Forest","country":"Germany","region":"Wesertal","city":null,"latitude":51.60833,"longitude":9.60028,"description":"The Kiffing is a range of hills, relatively small in area and up to 344.1 m above sea level (NN), in the district of Kassel in the German state of Hesse."},{"name":"Fairy Tale Forest","slug":"fairy-tale-forest","category":"Forest","country":"Netherlands","region":"Loon op Zand","city":null,"latitude":51.65081,"longitude":5.04672,"description":"The Fairytale Forest is a 15-acre (61,000 m2) wooded section of the amusement park Efteling in the Netherlands, where a number of well-known fairy tales and fairy tale figures are depicted by animatronics and buildings. Most of the figures are inspired by the Brothers Grimm, Hans Christian Andersen, and Charles Perrault."},{"name":"Krokskogen","slug":"krokskogen","category":"Forest","country":"Norway","region":"Ringerike","city":null,"latitude":60.10001,"longitude":10.47789,"description":"Krokskogen is a forested area which located outside of Oslo, Norway. It is a part of Oslomarka and is situated between Bærumsmarka, Vestmarka and Nordmarka."},{"name":"Kondelwald","slug":"kondelwald","category":"Forest","country":"Germany","region":"Rhineland-Palatinate","city":null,"latitude":50.0461,"longitude":7.04172,"description":"The Kondelwald, also known as the Kondel, is a forest, about 2,500 hectares in area and up to 477.5 m above sea level (NHN), that forms part of the Moselle Eifel. It lies within the counties of Bernkastel-Wittlich and Cochem-Zell in the German state of Rhineland-Palatinate. It used to belong to the imperial Carolingian estate of Kröver Reich."},{"name":"Kottenforst","slug":"kottenforst","category":"Forest","country":"Germany","region":"Bonn","city":null,"latitude":50.66109,"longitude":7.08359,"description":"The Kottenforst is a large forest, about 40 km2 in area, to the south, west and north of the city of Bonn in Germany. It is part of the Rhineland Nature Park (1,045 km2) and forms its eastern side."},{"name":"Landes forest","slug":"landes-forest","category":"Forest","country":"France","region":"Nouvelle-Aquitaine","city":null,"latitude":44.18,"longitude":-0.5822,"description":"The Landes forest in the Landes de Gascogne, in the historic Gascony natural region of southwestern France now known as Aquitaine, is the largest man-made woodland in Western Europe. The French word landes and Gascon lanas mean 'moors' or 'heaths', from Transalpine Gaulish *landa ; compare Irish lann, Welsh llan (“enclosure”)."},{"name":"Murrhardt Forest","slug":"murrhardt-forest","category":"Forest","country":"Germany","region":"Baden-Württemberg","city":null,"latitude":48.9736,"longitude":9.50278,"description":"The Murrhardt Forest in the Baden-Württemberg county of Rems-Murr-Kreis is part of the natural region known as the Swabian-Franconian Forest. It reaches a maximum height of 572 m above sea level (NHN). It takes its name from the town of Murrhardt in the centre."},{"name":"Leipzig Riverside Forest","slug":"leipzig-riverside-forest","category":"Forest","country":"Germany","region":"Leipzig","city":null,"latitude":51.31719,"longitude":12.35654,"description":"Leipzig Riverside Forest is one of the largest lowland Riparian forests in Central Europe, lying mostly within the city limits of Leipzig city in Germany. The nature reserve is partially covered with bottomland forest and contains a large variety of endangered species."},{"name":"Liebenwerda Heath","slug":"liebenwerda-heath","category":"Forest","country":"Germany","region":"Brandenburg","city":null,"latitude":51.5145,"longitude":13.5185,"description":"The Liebenwerda Heath, formerly also the Liebenwerda District Heath, is a forest region in the south of the German state of Brandenburg in Elbe-Elster Land that in earlier times was mainly used for forestry and hunting. It is located east of the spa town of Bad Liebenwerda between the villages of Dobra in the west and Gorden in the east."},{"name":"Lillomarka","slug":"lillomarka","category":"Forest","country":"Norway","region":"Oslo Municipality","city":null,"latitude":59.99167,"longitude":10.83333,"description":"Lillomarka is an area located to the northeast of Oslo, Norway. It is a part of Oslomarka and serves as a popular recreational area. Lillomarka is bordered by Maridalen and Nordmarka in the west, Nittedal and Gjelleråsen in the east, the suburbs Bjerke and Grorud in the south and the Gjøvik rail line and Movatn in the north."},{"name":"Neigembos","slug":"neigembos","category":"Forest","country":"Belgium","region":"Ninove","city":null,"latitude":50.81163,"longitude":4.06457,"description":"The Neigembos is a 72-hectare nature and forest area in Meerbeke (Ninove) that is protected in Europe as part of the Natura 2000 Habitats Directive area 'Forests of the Flemish Ardennes and other South Flemish forests'. It is, just like the Sonian Forest, a remnant of the old Coal Forest."},{"name":"Romincka Forest","slug":"romincka-forest","category":"Forest","country":"Poland","region":null,"city":null,"latitude":54.37153,"longitude":22.52131,"description":"Romincka Forest, also known as Krasny Les or Rominte Heath, is an extended forest and heath landscape stretching from the southeast of Russian Kaliningrad Oblast to the northeast of Polish Warmian-Masurian Voivodeship."},{"name":"Münstereifel Forest","slug":"m-nstereifel-forest","category":"Forest","country":"Germany","region":"Euskirchen","city":null,"latitude":50.53903,"longitude":6.82294,"description":"Münstereifel Forest is a densely wooded region in the northern part of the Eifel mountains in North Rhine-Westphalia, Germany. In the south, it borders the state of Rhineland-Palatinate. It has an area of 237 km² and an elevation between 200 and 500 m above sea level (NHN)."},{"name":"Chernyayevsky Forest","slug":"chernyayevsky-forest","category":"Forest","country":"Russia","region":"Perm","city":null,"latitude":57.98444,"longitude":56.15222,"description":"Chernyayevsky Forest is a forest in the city of Perm, Russia, in Industrialny and Dzerzhinsky city districts. The total area of forest in 2003 was 689.9 ha. The forest is under direction of Municipal Establishment \"Perm City Forestry\"."},{"name":"Neuburg Forest","slug":"neuburg-forest","category":"Forest","country":"Germany","region":"Bavaria","city":null,"latitude":48.5528,"longitude":13.3467,"description":"The Neuburg Forest is a largely forested hill ridge and natural region in Lower Bavaria in the county of Passau and the borough of Passau. It is named after the village of Neuburg am Inn."},{"name":"Debar Mountain Wild Forest","slug":"debar-mountain-wild-forest","category":"Forest","country":"United States","region":"Franklin County","city":null,"latitude":44.58215,"longitude":-74.22599,"description":"The Debar Mountain Wild Forest is a 83,405-acre (337.53 km2) tract designated as Wild Forest by the New York State Department of Environmental Conservation in the northeastern Adirondack Park, just north of Paul Smiths, in Franklin County. The area includes 61,500 acres (249 km2) of state land and 60,600 acres (245 km2) of conservation easement land. The area is served by state routes NY-3, NY-30 and NY-458."},{"name":"Takata Matsubara","slug":"takata-matsubara","category":"Forest","country":"Japan","region":"Rikuzentakata","city":null,"latitude":39.00344,"longitude":141.62514,"description":"Takata Matsubara (高田松原) or Takata Pine Forest was a pine grove located on the Pacific seashore of the city of Rikuzentakata, Iwate Prefecture, Japan. It was designated a nationally designated Place of Scenic Beauty in 1940 and one of the 100 Landscapes of Japan during the Shōwa era. After the grove was destroyed during the 2011 Tōhoku earthquake and tsunami, tree planting efforts commenced in 2017 and 2018."},{"name":"Soto de Viñuelas","slug":"soto-de-vi-uelas","category":"Forest","country":"Spain","region":"Community of Madrid","city":null,"latitude":40.61024,"longitude":-3.6878,"description":"Soto de Viñuelas is a meadow-oak forest north of the city of Madrid, south of Tres Cantos and San Agustín del Guadalix, east of the Monte de El Pardo and west of San Sebastián de los Reyes, all municipalities are parts of the Community of Madrid, Spain. Much of it is a fenced property of 3,000 hectares, which includes important ecological values, landscape and art."},{"name":"Lake George Wild Forest","slug":"lake-george-wild-forest","category":"Forest","country":"United States","region":null,"city":null,"latitude":43.64,"longitude":-73.58,"description":"The Lake George Wild Forest is a 71,133-acre (287.87 km2) tract designated as Wild Forest by the New York State Department of Environmental Conservation in the southeastern Adirondacks in the towns of Bolton, Chester, Hague, Horicon, Lake George, Lake Luzerne, Queensbury, and Warrensburg, in Warren County, and the towns of Dresden, Fort Ann, and Putnam, in Washington County."},{"name":"Moose River Plains Wild Forest","slug":"moose-river-plains-wild-forest","category":"Forest","country":"United States","region":"New York","city":null,"latitude":43.729,"longitude":-74.701,"description":"The Moose River Plains Wild Forest is a 64,322-acre tract in the Adirondack Park in Hamilton and Herkimer counties in the state of New York in the United States of America; it is designated as Wild Forest by the New York State Department of Environmental Conservation."},{"name":"Maletsunyane Falls","slug":"maletsunyane-falls","category":"Waterfall","country":"Lesotho","region":null,"city":null,"latitude":-29.86861,"longitude":28.05167,"description":"Maletsunyane Falls is a 192-metre-high (630 ft) waterfall in the Southern African country Lesotho. It is located near the town of Semonkong, which is also named after the falls. The waterfall is on the Maletsunyane River and it falls from a ledge of Triassic-Jurassic basalt."},{"name":"Tinkisso Falls","slug":"tinkisso-falls","category":"Waterfall","country":"Guinea","region":"Dabola Prefecture","city":null,"latitude":10.7291,"longitude":-11.17,"description":"Tinkisso Falls is a waterfall on the Tinkisso River located near Dabola in central Guinea. The falls are 70 m (230 ft) wide and 45 m (148 ft) high. The flow is highest during the rainy season, when the river flows close to ten times as strongly as in the dry season."},{"name":"Ouzoud Falls","slug":"ouzoud-falls","category":"Waterfall","country":"Morocco","region":"Ouzoud","city":null,"latitude":32.01528,"longitude":-6.71889,"description":"Ouzoud Falls is the collective name for several waterfalls in Azilal Province, Morocco. The waterfalls empty into the El-Abid River's gorge. A popular tourism destination, they are located 36 kilometres (22 mi) from the town of Azilal and 150 kilometres (93 mi) from Marrakesh. 'Ouzoud' means \"the act of grinding grain\" in Berber."},{"name":"Boyoma Falls","slug":"boyoma-falls","category":"Waterfall","country":"Democratic Republic of the Congo","region":"Kisangani","city":null,"latitude":0.49111,"longitude":25.20639,"description":"Boyoma Falls, formerly known as Stanley Falls, is a series of seven cataracts, each no more than 5 m (16 ft) high, extending over more than 100 km (62 mi) along a curve of the Lualaba River between the river port towns of Ubundu and Kisangani in the Orientale Province of the Democratic Republic of the Congo. The seven cataracts have a total drop of 61 m (200 ft)."},{"name":"El-Ourit Waterfalls","slug":"el-ourit-waterfalls","category":"Waterfall","country":"Algeria","region":"Tlemcen","city":null,"latitude":34.86256,"longitude":-1.26725,"description":"El-Ourit Waterfalls are located seven kilometers from the city of Tlemcen, near the National Road of Algeria in a mountainous area covered with pine trees. Seven stepped cascades form the natural site of Oued El-Ourit, which remained dry for 40 years before reappearing in 2009."},{"name":"Inga Falls","slug":"inga-falls","category":"Waterfall","country":"Democratic Republic of the Congo","region":"Kongo Central","city":null,"latitude":-5.53306,"longitude":13.60639,"description":"Inga Falls is a rapid 40 kilometres (25 mi) from Matadi in the Democratic Republic of the Congo where the Congo River drops 96 metres (315 ft) over the course of 15 kilometres (9.3 mi). The falls are part of a larger group of rapids in the lower Congo River. Livingstone Falls are located upstream closer to the Pool Malebo."},{"name":"Yellala Falls","slug":"yellala-falls","category":"Waterfall","country":"Democratic Republic of the Congo","region":"Kongo Central","city":null,"latitude":-5.72565,"longitude":13.54408,"description":"The Yellala Falls are a series of waterfalls and rapids on the Congo River just upstream from Matadi in the Democratic Republic of the Congo. The falls are the lowest of a long series of rapids that render the river unnavigable, forcing colonial explorers to travel by foot as far as the Stanley Pool 350 kilometres (220 mi) upstream."},{"name":"Victoria Falls","slug":"victoria-falls","category":"Waterfall","country":"Zambia","region":"Matabeleland North Province","city":null,"latitude":-17.92478,"longitude":25.85806,"description":"Victoria Falls is a waterfall on the Zambezi River, located on the border between Zambia and Zimbabwe. It is one of the world's largest waterfalls, with a width of 1,708 m (5,604 ft). The region around it has a high degree of biodiversity in both plants and animals."},{"name":"Epupa Falls","slug":"epupa-falls","category":"Waterfall","country":"Angola","region":null,"city":null,"latitude":-17.0,"longitude":13.25,"description":"Epupa Falls is a series of large waterfalls formed by the Cunene River on the border of Angola and Namibia, in the Kaokoland area of the Kunene Region. The river is about 0.5 kilometres (1,600 ft) wide in this area and drops in a series of waterfalls across a length of 1.5 kilometres (0.93 mi), with the greatest single drop being 37 metres (121 ft). The settlement near the falls is also called Epupa."},{"name":"Tugela Falls","slug":"tugela-falls","category":"Waterfall","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-28.7522,"longitude":28.8941,"description":"Tugela Falls is a complex of seasonal waterfalls located in the Drakensberg of Royal Natal National Park in KwaZulu-Natal Province, Republic of South Africa. According to some measurements, it is the world's tallest waterfall. A revisited validation of waterfall measurements is not available and there is still uncertainty whether Tugela or Venezuela's Angel Falls is the tallest."},{"name":"Lofoi Falls","slug":"lofoi-falls","category":"Waterfall","country":"Democratic Republic of the Congo","region":"Katanga Province","city":null,"latitude":-10.26028,"longitude":27.60639,"description":"Lofoi Falls is a waterfall in Kundelungu National Park, Haut-Katanga Province, Democratic Republic of the Congo. Plunging down for an unbroken 340 m (1,120 ft), it is one of the largest waterfalls in Central Africa. The waters of the Lofoi are a tributary of the Lufira River. The falls shrink quite a bit during the drier season of June to October, but are quite dramatic during the rest of the year."},{"name":"Augrabies Falls","slug":"augrabies-falls","category":"Waterfall","country":"South Africa","region":"Northern Cape","city":null,"latitude":-28.59139,"longitude":20.34083,"description":"The Augrabies Falls is a waterfall on the Orange River, the largest river in South Africa. Since 1966 the waterfall, set in a desolate and rugged milieu, is enclosed by the Augrabies Falls National Park. The falls are around 56 metres (184 ft) in height."},{"name":"Derna waterfalls","slug":"derna-waterfalls","category":"Waterfall","country":"Libya","region":"Derna","city":null,"latitude":32.7181,"longitude":22.6147,"description":"Derna waterfalls is a fresh-water waterfall in the Jebel Akhdar Mountains, south of the city of Derna, in the northern Cyrenaica region of eastern Libya."},{"name":"Bawa Falls","slug":"bawa-falls","category":"Waterfall","country":"South Africa","region":"Eastern Cape","city":null,"latitude":-32.39333,"longitude":28.12861,"description":"Bawa Falls are horsetail waterfalls, situated in the Transkei region of the Eastern Cape province, South Africa. The falls have a single drop of 103 m (338 ft) with an average width of 1.5 m (5 ft)."},{"name":"Chutes de la Kagera","slug":"chutes-de-la-kagera","category":"Waterfall","country":"Burundi","region":"Burunga","city":null,"latitude":-3.83,"longitude":30.08,"description":"The Chutes de la Karera are a spectacular series of waterfalls in southeastern Burundi. They are located to the south of Rutana. The falls occupy over 142 hectares, being made up of six branches divided on three landings."},{"name":"Mambatuta Falls","slug":"mambatuta-falls","category":"Waterfall","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":-12.36667,"longitude":29.2,"description":"The Mambatuta Falls is a steep waterfall on the Luapula River, which originates in Lake Bangweulu and flows through Zambia and along the border with the Democratic Republic of the Congo into Lake Mweru."},{"name":"Ripon Falls","slug":"ripon-falls","category":"Waterfall","country":"Uganda","region":null,"city":null,"latitude":0.43391,"longitude":33.19352,"description":"Ripon Falls were a series of waterfalls formerly located at the northern shore of Lake Victoria, near Jinja, in eastern Uganda. The falls marked the point where Lake Victoria drained into the Victoria Nile and were long regarded as the traditional source of the Nile River. Ripon Falls were submerged in the mid 20th century following the construction of the Nalubaale Dam."},{"name":"Murchison Falls","slug":"murchison-falls","category":"Waterfall","country":"Uganda","region":"Uganda","city":null,"latitude":2.27833,"longitude":31.68556,"description":"Murchison Falls, also known as Kabalega Falls, is a waterfall in Uganda, located at the apex of Lake Albert on the White Nile. At the top of Murchison Falls, the Nile forces its way through a gap in the rocks, only 7 m (23 ft) wide, and tumbles 43 m (141 ft), before flowing westward into Lake Albert."},{"name":"Lisbon Falls","slug":"lisbon-falls","category":"Waterfall","country":"South Africa","region":"Mpumalanga","city":null,"latitude":-24.86056,"longitude":30.83528,"description":"The Lisbon Falls are falls in the Lisbon Creek, a right bank tributary of the Blyde River. They are situated a short distance north of Graskop beside the R532 road, and are the highest waterfalls in Mpumalanga, South Africa. The waterfalls are 94 metres (308 ft) high and were named for the Lisbon Creek and the Farm Lisbon, on which the falls are located."},{"name":"Farin Ruwa Falls","slug":"farin-ruwa-falls","category":"Waterfall","country":"Nigeria","region":"Nasarawa State","city":null,"latitude":9.14806,"longitude":8.7575,"description":"Farin Ruwa Falls is a waterfall found in the central region of Nigeria. It is among the highest waterfalls in Nigeria. It is significant among Africa's falls when the total height covered by the waterfall is considered."},{"name":"Gauthiot Falls","slug":"gauthiot-falls","category":"Waterfall","country":"Chad","region":"Mayo-Kebbi Ouest Region","city":null,"latitude":9.71889,"longitude":14.55944,"description":"The Gauthiot Falls are a series of cascade waterfalls considered a natural wonder in Chad. They are situated about halfway down the course of the Mayo Kébbi river, found in southern Chad. Downstream from the falls, the flow of the Mayo Kébbi joins the Benue River, which itself is a tributary of the Niger River, which ultimately flows into the Atlantic Ocean."},{"name":"Chavuma Falls","slug":"chavuma-falls","category":"Waterfall","country":"Zambia","region":"Northwestern Province","city":null,"latitude":-13.09583,"longitude":22.68556,"description":"Chavuma Falls is a small waterfall on the Zambezi River in northwestern Zambia close to the town of Chavuma, lying immediately south of the border with Angola. During the wet season, the waterfalls are generally overwhelmed by the flow of the river but become visible as the dry season progresses. The falls have a mean annual discharge of 555 m3/s and are only a few meters high."},{"name":"Livingstone Falls","slug":"livingstone-falls","category":"Waterfall","country":"Republic of the Congo","region":"Pool Department","city":null,"latitude":-4.83333,"longitude":14.5,"description":"Livingstone Falls, named for British explorer David Livingstone, are a succession of enormous rapids on the lower course of the Congo River in west equatorial Africa, downstream from Malebo Pool in the Democratic Republic of the Congo."},{"name":"Dindefelo Falls","slug":"dindefelo-falls","category":"Waterfall","country":"Senegal","region":"Dindefelo","city":null,"latitude":12.36481,"longitude":-12.32489,"description":"Dindefelo Falls, located in the town of Dindefelo, is a tourist attraction and park in southeast Senegal. It is located just a few miles from the Guinean border. The falls are about 100 meters high."},{"name":"Félou Falls","slug":"f-lou-falls","category":"Waterfall","country":"Mali","region":"Kayes Region","city":null,"latitude":14.35639,"longitude":-11.34528,"description":"The Félou Falls are located on the Sénégal River 15 kilometres (9.3 mi) upstream of Kayes in western Mali. The river tumbles 13 metres (43 ft) down an irregular series of rocky steps. The waterfalls mark the furthest point from the mouth of the river that can be reached by boat."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 4: % places added', added;
end $$;

-- batch 5 of 6: 150 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Humbert Falls","slug":"humbert-falls","category":"Waterfall","country":"Madagascar","region":"Andapa","city":null,"latitude":-14.41667,"longitude":49.75,"description":"The Humbert Falls is a waterfall in the Marojejy National Park in North-Eastern Madagascar. It is situated approximately 800m from Camp Mantella and 4.3 km from the entrance of the park."},{"name":"Wli waterfalls","slug":"wli-waterfalls","category":"Waterfall","country":"Ghana","region":"Hohoe","city":null,"latitude":7.10583,"longitude":0.60889,"description":"Wli Waterfalls is the highest waterfall in Ghana and the tallest in West Africa. It has a lower and an upper fall."},{"name":"Horseshoe Falls","slug":"horseshoe-falls","category":"Waterfall","country":"South Africa","region":null,"city":null,"latitude":-25.1306,"longitude":30.6947,"description":"The Horseshoe Falls of South Africa are located 4 km off the Old Lydenburg Road along the Sabie River in Mpumalanga. These unusual falls, although not very high, are horseshoe shaped and have been declared a national monument. A short walk through an attractive landscape brings the visitor to the cascade-type falls. Here one also has the opportunity to spot some of the local birdlife or other wildlife."},{"name":"Kembé Falls","slug":"kemb-falls","category":"Waterfall","country":"Central African Republic","region":null,"city":null,"latitude":4.63556,"longitude":21.91806,"description":"Kembé Falls are located on the Kotto River, near Kembé on the road from Bangui to Bangassou in the Central African Republic, located about 80 km from Bangassou. Located some 3km from the town of Kembé, they are undeveloped and a regular stopping point for overland travelers."},{"name":"Kintampo waterfalls","slug":"kintampo-waterfalls","category":"Waterfall","country":"Ghana","region":"Kintampo North Municipal Assembly","city":null,"latitude":8.08965,"longitude":-1.69739,"description":"Kintampo waterfalls is one of Ghana' highest waterfalls located in Bono East. It was formerly known as Sanders Falls during the colonial days. It is located on the Pumpum river, a tributary of the Black Volta, about 4 kilometres (2.5 mi) north of the Kintampo municipality, on the Kumasi–Tamale road. It is just after the Falls Rest Stop when moving Northwards, on the right side of the road."},{"name":"Kongou Falls","slug":"kongou-falls","category":"Waterfall","country":"Gabon","region":null,"city":null,"latitude":0.29074,"longitude":12.58905,"description":"Chutes Kongou is a massive cataract about 3.2 kilometres (2.0 mi) wide and up to 56 metres (184 ft) tall, located in Ivindo National Park in eastern Gabon. It is located on the Ivindo River and is one of the strongest-flowing waterfalls in the world with an average flow of 900 cubic metres per second (32,000 cu ft/s)."},{"name":"Kundalila Falls","slug":"kundalila-falls","category":"Waterfall","country":"Zambia","region":"Central Province","city":null,"latitude":-13.1543,"longitude":30.7025,"description":"Kundalila Falls is a waterfall on the Kaombe River in Zambia. It falls over the lip of the Muchinga escarpment and makes a waterfall near the small town of Kanona in the Serenje District. The name 'Kundalila Falls' means \"crying dove\" in the local Bemba language."},{"name":"Lamadaya","slug":"lamadaya","category":"Waterfall","country":"Somaliland","region":"Somalia","city":null,"latitude":10.73583,"longitude":47.245,"description":"Lamadaya are waterfalls that are located in the Cal Madow mountain range in the Sanaag region of Somaliland. The meaning of the word in the Somali language is \"not to be looked at\", owing to the waterfalls' steep incline atop a high hill. The nearest town to Lamadaya is Ulheed, which is situated towards the Red Sea coast. Warsengali clan"},{"name":"Sipi Falls","slug":"sipi-falls","category":"Waterfall","country":"Uganda","region":"Kapchorwa District","city":null,"latitude":1.33778,"longitude":34.37944,"description":"Sipi Falls is a series of three waterfalls located on the north-western slopes of the eponymous extinct volcano, Mount Elgon, in Uganda, with views over the Karamoja plains. The falls are situated to the northeast of Sironko and Mbale, adjacent to Mount Elgon National Park, which is located 1.7 kilometers away from the Kenyan border. The falls account for 10% to 20% of all tourist visits to Uganda every year."},{"name":"Lumangwe Falls","slug":"lumangwe-falls","category":"Waterfall","country":"Zambia","region":null,"city":null,"latitude":-9.53333,"longitude":29.38333,"description":"Lumangwe Falls on the Kalungwishi River in northern Zambia is the largest waterfall wholly within the country, with a height of 30–40 m and a width of 100–160 m. It is a block-type waterfall located between the Luapula and Northern Provinces. The main bedrock is interbedded quartzite with layers of red siltstone."},{"name":"Gouina Falls","slug":"gouina-falls","category":"Waterfall","country":"Mali","region":"Kayes Region","city":null,"latitude":14.015,"longitude":-11.1025,"description":"The Gouina Falls or Chutes de Gouina are on the Sénégal River in Mali between the towns of Bafoulabé (upstream) and Diamou (downstream) in the Kayes Region, where the river runs north from the Talari Gorges. They have been called the \"Niagara falls of Mali\". The river is about 500 m wide at this point, and drops 16 m over the falls."},{"name":"Kalambo Falls","slug":"kalambo-falls","category":"Waterfall","country":"Tanzania","region":"Rukwa Region","city":null,"latitude":-8.59642,"longitude":31.23955,"description":"The Kalambo Falls on the Kalambo River is a 235-metre (772 ft) single-drop waterfall on the border of Zambia and Rukwa Region, Tanzania at the southeast end of Lake Tanganyika. The falls are some of the tallest uninterrupted falls in Africa."},{"name":"Barrakunda Falls","slug":"barrakunda-falls","category":"Waterfall","country":"Senegal","region":null,"city":null,"latitude":13.54321,"longitude":-13.82297,"description":"The Barrakunda Falls or Barra Kunda Falls is a waterfall located in the Tambacounda region of Senegal, 500 kilometres (300 mi) upstream from the mouth of the Gambia River."},{"name":"Ibini Ukpabi","slug":"ibini-ukpabi","category":"Waterfall","country":"Nigeria","region":"Abia State","city":null,"latitude":5.38544,"longitude":7.91186,"description":"The Ibini Ukpabi was an oracle of the Aro Confederacy of what is now Southeastern Nigeria. It was known among the British as the 'Long Ju-ju'. Ibini Ukpabi was used to settle cases, particularly those of murder, witchcraft, poisoning and family disputes."},{"name":"Ncandu Falls","slug":"ncandu-falls","category":"Waterfall","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-27.849,"longitude":29.844,"description":"Ncandu Falls is a waterfall in the Ncandu River in Northern KwaZulu-Natal, in South Africa close to the town of Newcastle, KwaZulu-Natal. Its name may mean \"small flow\" in Zulu or a Khosian language."},{"name":"Boti Falls","slug":"boti-falls","category":"Waterfall","country":"Ghana","region":"Eastern Region","city":null,"latitude":6.16472,"longitude":-0.20139,"description":"Boti Falls is a twin waterfall located at Boti in Yilo Krobo District in the Eastern Region of Ghana. These twin falls, which come from two rivers, are referred to as female and male; according to local myth, a rainbow is formed when they merge. Boti is a seasonal falls is a double side-by-side falls during the high flow and at the bottom of 250 concrete steps."},{"name":"Kabwelume Falls","slug":"kabwelume-falls","category":"Waterfall","country":"Zambia","region":"Zambia","city":null,"latitude":-9.52469,"longitude":29.35022,"description":"Kabwelume Falls is a waterfall on the Kalungwishi River in the Northern Province of Zambia. The falls is about 6 km down stream of Lumangwe Falls. When viewed at peak water volume (April/May), a month after the wet season, the falls makes a spectacular semi circle of falling water. There are plans to build a hydro power station on this falls."},{"name":"Magwa Falls","slug":"magwa-falls","category":"Waterfall","country":"South Africa","region":"Eastern Cape","city":null,"latitude":-31.44596,"longitude":29.63877,"description":"Magwa Falls is a waterfall in Eastern Cape province in South Africa. The main water drop is 142 metres (466 ft). The nearest town is Lusikisiki."},{"name":"Kalandula Falls","slug":"kalandula-falls","category":"Waterfall","country":"Angola","region":"Malanje Province","city":null,"latitude":-9.07583,"longitude":16.00333,"description":"Kalandula Falls or Calandula Falls are waterfalls in the municipality of Calandula, Malanje Province, Angola. On the Lucala River, the falls are 105 meters high and 400 meters wide. They are one of the largest waterfalls by volume in Africa. The distance from Luanda is 360 km (220 mi)."},{"name":"Karfiguéla waterfalls","slug":"karfigu-la-waterfalls","category":"Waterfall","country":"Burkina Faso","region":"Karfiguéla","city":null,"latitude":10.72228,"longitude":-4.821,"description":"The Cascades de Karfiguéla or the Banfora Cascades are a series of waterfalls along the Komoé River in Southwestern Burkina Faso. They are located about 12 km northwest of Banfora and constitute one of the most important tourism sites in Burkina Faso. The Cascades Region gets its name from the waterfalls. The flow of the falls peaks during the rainy season from June to September."},{"name":"Rusumo Falls","slug":"rusumo-falls","category":"Waterfall","country":"Tanzania","region":null,"city":null,"latitude":-2.37528,"longitude":30.7925,"description":"Rusumo Falls is a waterfall located on the Kagera river on the border between Rwanda and Tanzania, part of the most distant headwaters of the river Nile. The falls are approximately 15 m (49 ft) high and 40 m (130 ft) wide and have formed on Precambrian schists and quartz–phyllites."},{"name":"Tagbo Falls","slug":"tagbo-falls","category":"Waterfall","country":"Ghana","region":"Volta Region","city":null,"latitude":7.14083,"longitude":0.33306,"description":"Tagbo Falls is a waterfall near Mount Afadjato in Ghana, located at Liati Wote, approximately 27 kilometres east of the township of Hohoe. The water falls down in several stages, with the last stage being about 60 m. high. The area is surrounded by rainforest."},{"name":"Bujagali Falls","slug":"bujagali-falls","category":"Waterfall","country":"Uganda","region":null,"city":null,"latitude":0.49889,"longitude":33.14,"description":"Bujagali Falls was a waterfall near Jinja in Uganda where the Nile River comes out of Lake Victoria, sometimes considered the source of the Nile. Starting November 2011, the falls were submerged by the new Bujagali Power Station."},{"name":"Chishimba Falls","slug":"chishimba-falls","category":"Waterfall","country":"Zambia","region":"Kasama District","city":null,"latitude":-10.075,"longitude":30.55833,"description":"Chisimba Falls, also Chishimba Falls is a series of waterfalls located in Kasama District, in the Northern Province of Zambia. The waterfalls host the Chishimba Hydroelectric Power Station. The scenic views around the falls, together with a museum under development, are major tourist attractions."},{"name":"Ruacana Falls","slug":"ruacana-falls","category":"Waterfall","country":"Angola","region":null,"city":null,"latitude":-17.39361,"longitude":14.21694,"description":"Ruacana Falls is a waterfall located in Ruacana, Omusati on the Kunene River in Northern Namibia. The waterfall is 120 meters (390 ft) high and 700 meters (2,300 ft) wide in full flood. It is among the largest waterfalls in Africa, both by volume and width."},{"name":"Mandraka Falls","slug":"mandraka-falls","category":"Waterfall","country":"Madagascar","region":null,"city":null,"latitude":-18.92111,"longitude":47.92944,"description":"The Mandraka Falls are a small set of waterfalls on the Mandraka River, approximately 65 kilometres (40 mi) from Antananarivo, the capital of Madagascar. Their total drop is only about 30 metres (98 ft)."},{"name":"Nyambwezi Falls","slug":"nyambwezi-falls","category":"Waterfall","country":"Zambia","region":null,"city":null,"latitude":-11.90444,"longitude":25.09556,"description":"Nyambwezi Falls is a waterfall located in the North-Western Province of Zambia. They are approximately 20 metres (66 ft) high. Close to the lip of the falls, there is a rock shelter, which has petroglyphs and other evidence of late Stone Age occupation."},{"name":"Petites Chutes de la Lukaya","slug":"petites-chutes-de-la-lukaya","category":"Waterfall","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":-4.48571,"longitude":15.26708,"description":"The Petites Chutes de la Lukaya is a set of small waterfalls on the Lukaya River. They are just south of Kinshasa, the capital city of the Democratic Republic of the Congo. They are about 1 metre (3.3 ft) high."},{"name":"Ras al Helal","slug":"ras-al-helal","category":"Waterfall","country":"Libya","region":"Derna District","city":null,"latitude":32.883,"longitude":22.1803,"description":"Ras al-Helal is a village on the southern shore of the Mediterranean Sea in Derna District, Cyrenaica, Libya. It takes its name from its cape, which appears to have a crescent shape when viewed from the surrounding Jebel Akhdar mountainous plateau's foothills. It had a population totaling 2,235 in 2006. Ras al-Helal is known for its green, forested beach and its nearby waterfalls."},{"name":"Blue Nile Falls","slug":"blue-nile-falls","category":"Waterfall","country":"Ethiopia","region":"Amhara Region","city":null,"latitude":11.4905,"longitude":37.5878,"description":"The Blue Nile Falls is a waterfall on the Blue Nile river in South Gondar, Amhara Region, Ethiopia. It is known as Tis Abay in Amharic, meaning 'great smoke'. It is situated on the upper course of the river, about 30 kilometres downstream from the town of Bahir Dar and Lake Tana. The falls are one of Ethiopia's best-known tourist attractions."},{"name":"Mutumuna Falls","slug":"mutumuna-falls","category":"Waterfall","country":"Zambia","region":null,"city":null,"latitude":-10.075,"longitude":30.55833,"description":"Mutumuna Falls is a wide waterfall in Zambia. It is the \"Upper Fall\" in the 3-falls cascade commonly referred to as the Chisimba Falls, in Kasama District, in the Northern Province of Zambia. Mutumuna Falls and the other two components in the cascade, host the 15 megawatts Chishimba Hydroelectric Power Station and related infrastructure, across the Luombe River."},{"name":"Ngonye Falls","slug":"ngonye-falls","category":"Waterfall","country":"Zambia","region":"Western Province","city":null,"latitude":-16.65417,"longitude":23.57222,"description":"The Ngonye Falls or Sioma Falls is a waterfall on the Zambezi river in Western province Zambia, near the town of Sioma and a few hundred kilometres upstream from the Victoria Falls. Situated in the southern part of Barotseland, the falls are a day's journey by car from the capital, Lusaka. Their inaccessibility makes them much less known than Victoria Falls."},{"name":"Kapichira Falls","slug":"kapichira-falls","category":"Waterfall","country":"Malawi","region":"Malawi","city":null,"latitude":-15.9006,"longitude":34.7509,"description":"Kapachira Falls is a waterfall in Malawi. It is located on the lower Shire River near the town of Chikwawa and the Majete Wildlife Reserve. The Kapichira Hydroelectric Power Station was constructed above the falls to generate hydroelectricity."},{"name":"Thomson's Falls","slug":"thomsons-falls","category":"Waterfall","country":"Kenya","region":null,"city":null,"latitude":0.04417,"longitude":36.37028,"description":"Thomson's Falls is a 74-metre (243 ft) waterfall on the Ewaso Ng'iro River in Central Rift Valley Kenya, a few kilometres from Lake Ol Bolossat, which drains from the Aberdare Range. It is situated 3 kilometres (2 mi) from the town of Nyahururu, at 2,360 metres (7,740 ft) elevation. In 1883, Joseph Thomson was the first European to reach the waterfall and named it for his father."},{"name":"Mumbuluma Falls","slug":"mumbuluma-falls","category":"Waterfall","country":"Zambia","region":null,"city":null,"latitude":-10.93,"longitude":28.73667,"description":"Mumbuluma Falls are a set of waterfalls just outside Mansa, Zambia in the Luapula Province. The waterfalls are a national monument of Zambia."},{"name":"Mahamanina Falls","slug":"mahamanina-falls","category":"Waterfall","country":"Madagascar","region":"Ambanja","city":null,"latitude":-14.1333,"longitude":48.75,"description":"The Mahamanina Falls is a 60-meter-high (200 ft) waterfall in the region of Diana in the north of Madagascar. It is located 15 km from Ambanja via Route nationale 6. Two more falls are situated on the Mirahavavyse River at 14 km on the road to Sambirano."},{"name":"Riandahy Falls","slug":"riandahy-falls","category":"Waterfall","country":"Madagascar","region":"Ihorombe","city":null,"latitude":-22.1472,"longitude":46.89139,"description":"The Riandahy Falls is a waterfall in the region of Ihorombe in Madagascar. They are situated on the Zomandao River in the Andringitra Massif near the Andringitra National Park. At a distance of less than 1 km from these falls, there are also the Rianbavy Falls"},{"name":"Sakaleona Falls","slug":"sakaleona-falls","category":"Waterfall","country":"Madagascar","region":"Ampasinambo","city":null,"latitude":-20.5272,"longitude":47.9964,"description":"The Sakaleona Falls are the highest waterfalls of Madagascar, with a height of 200 metres (660 ft)."},{"name":"Owen Falls","slug":"owen-falls","category":"Waterfall","country":"Uganda","region":null,"city":null,"latitude":0.44444,"longitude":33.18722,"description":"The Owen Falls was a waterfall on the White Nile in Uganda near the city of Jinja. The falls, together with the nearby Ripon Falls, were submerged in 1954 with the completion of the Nalubaale Hydroelectric Power Station."},{"name":"Mambilima Falls","slug":"mambilima-falls","category":"Waterfall","country":"Zambia","region":null,"city":null,"latitude":-10.54417,"longitude":28.66083,"description":"Mambilima Falls is a series of rapids on the Luapula River on the boundary between Zambia and the Democratic Republic of the Congo. The falls used to be called the Johnstone Falls. They extend along a 5 kilometres (3.1 mi) stretch of the river."},{"name":"Ntumbachushi Falls","slug":"ntumbachushi-falls","category":"Waterfall","country":"Zambia","region":"Luapula Province","city":null,"latitude":-9.85,"longitude":28.93333,"description":"Ntumbachushi Falls are situated on the Ngona River in Luapula Province, Zambia where it runs over the edge of the northern Zambian plateau into the valley of the Luapula River."},{"name":"Lone Creek Falls","slug":"lone-creek-falls","category":"Waterfall","country":"South Africa","region":"Mpumalanga","city":null,"latitude":-25.1025,"longitude":30.70931,"description":"The Lone Creek Falls is near Sabie in Mpumalanga, South Africa. The waterfall plummets 70 m down into the Creek. The waterfall was declared a National Monument."},{"name":"Soni Falls","slug":"soni-falls","category":"Waterfall","country":"Tanzania","region":null,"city":null,"latitude":-4.84667,"longitude":38.34278,"description":"The Soni Falls is a waterfall in the Usambara Mountains of northeastern Tanzania, near the village of Soni, to the northeast of Kitunda. The falls lie at the end of the Mkuzu River where it joins the Bangala River. The falls lie in the southern part of the West Usambaras Lushoto Mountain Reserve."},{"name":"Mount Gahinga","slug":"mount-gahinga","category":"Mountain","country":"Uganda","region":"Musanze District","city":null,"latitude":-1.3873,"longitude":29.6435,"description":"Mount Gahinga is a dormant/extinct volcano in the Virunga Mountains on the Rwanda-Uganda border. Gahinga lies between Muhabura and Sabyinyo, but is the smallest of these three volcanoes. Mount Gahinga, also known in the local Kinyarwanda/Rufumbira dialect as \"a small pile of stones\", has a swampy caldera on its peak. The caldera is believed to be about 180 m (591 ft) wide."},{"name":"Central Island","slug":"central-island","category":"Mountain","country":"Kenya","region":"Kenya","city":null,"latitude":3.5,"longitude":36.05,"description":"Central Island, also known as Crocodile Island, is a volcanic island located in the middle of Lake Turkana in Kenya. It is also the location of Central Island National Park, which is governed by the Kenya Wildlife Service."},{"name":"Mount Ayalu","slug":"mount-ayalu","category":"Mountain","country":"Ethiopia","region":"Gabi Rasu","city":null,"latitude":10.08222,"longitude":40.70167,"description":"Mount Hazalo, also known as Azalo, or Ayelu is an isolated, rhyolitic stratovolcano in eastern Ethiopia. Located in the Afar Region, near the South of the towns of Āfdem and Gewane, and has an altitude of 2,145 metres (7,037 ft)."},{"name":"Borawli","slug":"borawli","category":"Mountain","country":"Ethiopia","region":"Afar Region","city":null,"latitude":13.30389,"longitude":40.98639,"description":"Borawli is a stratovolcano with lava domes, located in Administrative Zone 2 of the Afar Region, Ethiopia. It lies above the eastern shore of Lake Afrera."},{"name":"Ardoukoba","slug":"ardoukoba","category":"Mountain","country":"Djibouti","region":"Tadjourah Region","city":null,"latitude":11.57194,"longitude":42.49583,"description":"Ardoukoba is a fissure vents volcano in Djibouti. Located on the coast 100 kilometres (62 mi) from Djibouti City, its summit is situated at 298 metres (978 ft) above sea level. It last erupted in November 1978 following an earthquake, the area having been dormant for 3,000 years. The volcano's rift is 17 kilometres (11 mi) in width, and has a depth of 800 metres (2,600 ft)."},{"name":"Tarso Toussidé","slug":"tarso-toussid","category":"Mountain","country":"Chad","region":"Tibesti Region","city":null,"latitude":21.04083,"longitude":16.47361,"description":"Toussidé is a potentially active stratovolcano in Chad. Toussidé lies in the Tibesti Mountains; the large Yirrigué caldera and the smaller Trou au Natron and Doon Kidimi craters are close to it. It has an elevation of 3,302 m (10,833 ft) above sea level. The volcano is the source of a number of lava flows, which have flowed westward away from Toussidé and east into the Yirrigué caldera."},{"name":"Mount Bisoke","slug":"mount-bisoke","category":"Mountain","country":"Democratic Republic of the Congo","region":"Musanze District","city":null,"latitude":-1.51111,"longitude":29.44833,"description":"Mount Bisoke is an active stratovolcano in the Virunga Mountains of the Albertine Rift, the western branch of the East African Rift. It straddles the border of Rwanda and the Democratic Republic of the Congo, but the summit is located in Rwanda. It is located approximately 35 km northeast of the town of Goma and the adjacent Lake Kivu."},{"name":"Furi","slug":"furi","category":"Mountain","country":"Ethiopia","region":"Addis Ababa","city":null,"latitude":8.9,"longitude":38.68333,"description":"Mount Furi is a stratovolcano near Addis Ababa, Ethiopia. Located in the south eastern outskirt of Addis Ababa, this mountain has a latitude and longitude of 8°54′N 38°41′E and an altitude of 2,839 metres (9,314 ft)."},{"name":"Oku Volcanic Field","slug":"oku-volcanic-field","category":"Mountain","country":"Cameroon","region":null,"city":null,"latitude":6.33333,"longitude":10.66667,"description":"The Oku Volcanic Field or Oku Massif is a group of volcanoes based on a swell in the Cameroon Volcanic Line, located in the Oku region of the Western High Plateau of Cameroon. The Mount Oku stratovolcano rises to 3,011 m above sea level."},{"name":"Mount Karisimbi","slug":"mount-karisimbi","category":"Mountain","country":"Democratic Republic of the Congo","region":"North Kivu","city":null,"latitude":-1.5,"longitude":29.45,"description":"Mount Karisimbi is a stratovolcano in the Virunga Mountains on the border between Rwanda and the Democratic Republic of Congo. At 4,507 metres (14,787 ft), Karisimbi is the highest of the eight major mountains of the mountain range, which is a part of Albertine Rift, the western branch of the East African Rift."},{"name":"Mount Nyiragongo","slug":"mount-nyiragongo","category":"Mountain","country":"Democratic Republic of the Congo","region":"Democratic Republic of the Congo","city":null,"latitude":-1.51667,"longitude":29.25,"description":"Mount Nyiragongo is an active stratovolcano with an elevation of 3,470 m (11,385 ft) in the Virunga Mountains associated with the Albertine Rift. It is located inside Virunga National Park, in the North Kivu province in the Democratic Republic of the Congo, about 12 km (7.5 mi) north of the town of Goma and Lake Kivu and just 9.8 km (6.1mi) west of the border with Rwanda."},{"name":"Pico do Fogo","slug":"pico-do-fogo","category":"Mountain","country":"Cape Verde","region":"Santa Catarina do Fogo","city":null,"latitude":14.94927,"longitude":-24.34037,"description":"Pico do Fogo is an active stratovolcano located on the island of Fogo, Cape Verde, rising to 2,829 metres (9,281 ft) above sea level. The main cone last erupted in 1680, causing mass emigration from the island. A subsidiary vent erupted in 1995. The only deadly eruption was in 1847 when earthquakes killed several people."},{"name":"Mawenzi","slug":"mawenzi","category":"Mountain","country":"Tanzania","region":null,"city":null,"latitude":-3.09544,"longitude":37.45506,"description":"Mawenzi is the second-tallest volcanic cone of the Kilimanjaro massif in Tanzania, located east of Kilimanjaro's main summit. It rises to an elevation of 5,149 metres (16,893 ft) and has a prominence of 849 metres (2,785 ft), making it the third-highest peak in Africa after Kilimanjaro's main summit and Mount Kenya. As such, it is counted as one of the Seven Third Summits, the third-highest peaks on each continent."},{"name":"Mount Longonot","slug":"mount-longonot","category":"Mountain","country":"Kenya","region":"Kenya","city":null,"latitude":-0.91528,"longitude":36.45694,"description":"Mount Longonot is a stratovolcano located southeast of Lake Naivasha in the Great Rift Valley of Kenya, Africa. It is thought to have last erupted in the 1860s. Its name is derived from the Maasai word Olongongot, meaning \"mountains of many spurs\" or \"steep ridges\"."},{"name":"Monte Gordo","slug":"monte-gordo","category":"Mountain","country":"Cape Verde","region":null,"city":null,"latitude":16.62083,"longitude":-24.35417,"description":"Monte Gordo is a mountain on the island of São Nicolau, Cape Verde. At 1,312 m elevation, it is the island's highest point. It is situated in the western part of the island, 6 km west of the island capital Ribeira Brava. The mountain is of volcanic origin, less than 1 million years old. The boundary of the municipalities Tarrafal de São Nicolau and Ribeira Brava runs over the mountain."},{"name":"Mount Fentale","slug":"mount-fentale","category":"Mountain","country":"Ethiopia","region":"Oromia Region","city":null,"latitude":8.96667,"longitude":39.93333,"description":"Fentale is a stratovolcano located in Awash National Park which was found in the Afar Region, Ethiopia. It is the highest point of Fentale woreda."},{"name":"Mount Cameroon","slug":"mount-cameroon","category":"Mountain","country":"Cameroon","region":"Fako","city":null,"latitude":4.21667,"longitude":9.1725,"description":"Mount Cameroon is an active stratovolcano in the Southwest Region of Cameroon next to the city of Buea near the Gulf of Guinea. Mount Cameroon is also known as Cameroon Mountain or Fako or by its indigenous name Mongo ma Ndemi. Mount Cameroon is ranked 22nd by topographic isolation."},{"name":"Mallahle","slug":"mallahle","category":"Mountain","country":"Ethiopia","region":"Afdera","city":null,"latitude":13.277,"longitude":41.655,"description":"Mallahle is a stratovolcano on the border of Ethiopia and Eritrea, with a 6 km wide caldera."},{"name":"Ankaratra","slug":"ankaratra","category":"Mountain","country":"Madagascar","region":null,"city":null,"latitude":-19.34978,"longitude":47.24334,"description":"Ankaratra is a cinder cone volcanic range located about 50 km (30 mi) southwest of Antananarivo, the capital city of Madagascar. It lies between the towns of Arivonimamo to the north, Ambatolampy to the east, Faratsiho to the west and Betafo to the south. It is located in the Central Highlands. The highest peak in Ankaratra is Mount Tsiafajavona, at 2,644 metres (8,668 ft.) above sea level."},{"name":"Erta Ale","slug":"erta-ale","category":"Mountain","country":"Ethiopia","region":"Kilbet Rasu","city":null,"latitude":13.603,"longitude":40.6634,"description":"Erta Ale is a continuously active shield volcano in the Afar Region of northeastern Ethiopia, which is itself part of the wider Afar Triangle. The volcano is located in the Danakil Depression, an area on the border between Ethiopia and Eritrea that is below sea level. It is composed of basalt, and it is the most active of the volcanoes in Ethiopia."},{"name":"Emi Koussi","slug":"emi-koussi","category":"Mountain","country":"Chad","region":null,"city":null,"latitude":19.78944,"longitude":18.55111,"description":"Emi Koussi, also known as Emi Koussou, is a high pyroclastic shield volcano that lies at the southeast end of the Tibesti Mountains in the central Sahara, in the northern Borkou Region of northern Chad. The highest mountain of the Sahara, the volcano is one of several in the Tibesti range, and reaches an elevation of 3,447 metres (11,309 ft), rising 3 km (1.9 mi) above the surrounding sandstone plains."},{"name":"Mont-Aux-Sources","slug":"mont-aux-sources","category":"Mountain","country":"Lesotho","region":"KwaZulu-Natal","city":null,"latitude":-28.75908,"longitude":28.88464,"description":"Mont-aux-Sources is a mountain in Southern Africa, forming one of the highest portions of the Drakensberg Range. It is mostly within Lesotho, with parts in KwaZulu-Natal and Free State province of South Africa."},{"name":"Cova","slug":"cova","category":"Mountain","country":"Cape Verde","region":null,"city":null,"latitude":17.1077,"longitude":-25.0627,"description":"Cova is a volcanic caldera in the east-central part of the island of Santo Antão in Cape Verde. It is situated at the southwestern end of the municipality of Paul. Its lowest point is 1,166 meters, and the highest point of the crater rim is about 1,500 m. The diameter of the caldera is about 1.0 km. It forms a part of Cova-Paul-Ribeira da Torre Natural Park."},{"name":"Bordeira (Fogo)","slug":"bordeira-fogo","category":"Mountain","country":"Cape Verde","region":null,"city":null,"latitude":14.961,"longitude":-24.392,"description":"Bordeira is a semicircular mountain in the middle of the island Fogo. It is a crater rim, up to 1 km high, formed by a prehistoric collapse of the volcano Pico do Fogo. At a maximum elevation of 2,692 metres (8,832 ft), it is the second highest point in the nation behind Pico do Fogo. The name literally means the \"border\". It forms part of Fogo Natural Park."},{"name":"Aluto","slug":"aluto","category":"Mountain","country":"Ethiopia","region":null,"city":null,"latitude":7.787,"longitude":38.771,"description":"Aluto is a dormant stratovolcano in Ethiopia, located in the Ethiopian Rift Valley in southern Oromia region between Lake Langano and Lake Ziway. It is the site of the Aluto–Langano Geothermal Power Station."},{"name":"Njesuthi","slug":"njesuthi","category":"Mountain","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-29.2,"longitude":29.36667,"description":"Njesuthi or Injesuthi Dome is the fourth highest mountain in the Drakensberg mountain range at 3,408 metres (11,181 ft), and second highest peak in South Africa. It is located on the border between Lesotho and the South African province KwaZulu-Natal. Also, less than 1.5 km away on the border is the taller Mafadi peak at 3,450 metres (11,319 ft)."},{"name":"Mount Meru","slug":"mount-meru","category":"Mountain","country":"Tanzania","region":"Arumeru District","city":null,"latitude":-3.24678,"longitude":36.76025,"description":"Mount Meru is a dormant stratovolcano located 70 kilometres (43 mi) west of Kilimanjaro in southeast Arusha Region, Tanzania. At a height of 4,562.13 metres (14,968 ft), it is visible from Mount Kilimanjaro on a clear day, and is the eighth-highest mountain of Africa."},{"name":"Mount Elgon","slug":"mount-elgon","category":"Mountain","country":"Kenya","region":"Bungoma District","city":null,"latitude":1.1185,"longitude":34.5265,"description":"Mount Elgon is an extinct shield volcano on the border of Uganda and Kenya, north of Kisumu, east of Mbale and west of Kitale. The mountain's highest point, named \"Wagagai\", is located entirely within Uganda. Although there is no verifiable evidence of its earliest volcanic activity, geologists estimate that Mount Elgon is at least 24 million years old, making it the oldest known extinct volcano in East Africa."},{"name":"Hayli Gubbi","slug":"hayli-gubbi","category":"Mountain","country":"Ethiopia","region":"Afar Region","city":null,"latitude":13.51,"longitude":40.71639,"description":"Hayli Gubbi is a shield volcano located in the Afar Region of Ethiopia. It is the southernmost volcano of the Erta Ale Range. Until November 2025, there was no direct record of any eruptions of this volcano, although records of eruptions in the area are limited by the remoteness of the region."},{"name":"Tchabal Nganha","slug":"tchabal-nganha","category":"Mountain","country":"Cameroon","region":null,"city":null,"latitude":7.35369,"longitude":14.01468,"description":"Tchabal Nganha is a stratovolcano on the Ngaoundere Plateau, a highland area in the Adamawa Region of Cameroon."},{"name":"Mount Afadja","slug":"mount-afadja","category":"Mountain","country":"Ghana","region":"Jasikan District","city":null,"latitude":7.14444,"longitude":0.355,"description":"Mount Afadja, known as Afadjato to the Ewe people of Ghana and Togo, is one of the highest mountains in Ghana. The summit is located in the Volta Region, near the border with Togo, close to the villages of Liati Wote and Gbledi Gbogame in the Afadjato South District and Hohoe Municipality, respectively. It is about 178 kilometers (111 mi) northeast of Accra, and 178 kilometers (111 mi) northwest of Lomé."},{"name":"Shimbiris","slug":"shimbiris","category":"Mountain","country":"Somalia","region":"Sanaag Region","city":null,"latitude":10.73583,"longitude":47.245,"description":"Mount Shimbiris is the highest peak in Somaliland. It is also the highest peak in any somali territory including Somalia. It has an elevation of 2,460 metres (8,071 ft) above sea level. It is located in the Ogo Mountains range, which forms part of the Cal Madow mountain system in the Sanaag region of Somaliland."},{"name":"Kerimasi volcano","slug":"kerimasi-volcano","category":"Mountain","country":"Tanzania","region":"Arusha Region","city":null,"latitude":-2.43167,"longitude":34.98056,"description":"Kerimasi Volcano, also known as Kerimasi at 2,602 metres (8,537 ft) is an extinct shield volcano located in Monduli District of Arusha Region in Tanzania. The majority of the mountain lies in Engaruka Ward, and a quarter of it is in the Ngorongoro Conservation Area. The volcano is located in the geographic area known as the Crater Highlands and is a shield volcano that last erupted in the Pleistocene."},{"name":"Wonchi","slug":"wonchi","category":"Mountain","country":"Ethiopia","region":null,"city":null,"latitude":8.8,"longitude":37.9,"description":"Wenchi crater lake, also spelled as Wancii or Wonchi, is a volcano located 98 km (61 mi) west of Addis Ababa, in Oromia Region, Ethiopia. At 3,450 m (11,320 ft) above sea level, it is the highest volcano in Ethiopia, 13.5 km (8.4 mi) from Mount Dendi, Ethiopia's second highest volcano. Wonchi is located at equal distance between the towns of Ambo and Woliso. It erupted in the Tertiary period of the Cenozoic Era."},{"name":"Mount Mikeno","slug":"mount-mikeno","category":"Mountain","country":"Democratic Republic of the Congo","region":"North Kivu","city":null,"latitude":-1.46277,"longitude":29.41682,"description":"Mount Mikeno is an extinct volcanic mountain located in the Democratic Republic of the Congo section of the Virunga Mountains along with Mount Nyiragongo, Mount Nyamuragira, Mount Karisimbi, Mount Bisoke and Mount Sabyinyo. At 4,437 metres (14,557 ft) Mount Mikeno is the second highest peak in the Virunga Mountains after Karisimbi, and the 13th highest in Africa."},{"name":"Menengai","slug":"menengai","category":"Mountain","country":"Kenya","region":"Kenya","city":null,"latitude":-0.2,"longitude":36.06667,"description":"Menengai Crater is a massive shield volcano with one of the biggest calderas in the world, in the Great Rift Valley, Kenya. It is the largest volcano caldera in Kenya and the second largest volcano caldera in Africa. Volcanic formed rich loam soils enrich the adjacent farmland around its flanks. The crater is on the floor of the Rift Valley."},{"name":"Pico de São Tomé","slug":"pico-de-s-o-tom","category":"Mountain","country":"São Tomé and Príncipe","region":"Lembá","city":null,"latitude":0.26667,"longitude":6.53333,"description":"Pico de São Tomé is the highest mountain in São Tomé and Príncipe at 2,024 m (6,640 ft) elevation. It lies just west of the centre of São Tomé Island, in the Parque Natural Obô de São Tomé and in the Lembá District. The second highest point, Pico de Ana Chaves (1,630 m [5,348 ft]), lies about 3 km (1.9 mi) to its south east. The town Santa Catarina is 8 km (5.0 mi) to the west."},{"name":"Pico Basilé","slug":"pico-basil","category":"Mountain","country":"Equatorial Guinea","region":"Bioko Norte","city":null,"latitude":3.58333,"longitude":8.76667,"description":"Pico Basilé, located on the island of Bioko, is the tallest mountain of Equatorial Guinea. With an elevation of 3,011 metres, it is the summit of the largest and highest of three overlapping basaltic shield volcanoes which form the island. From the summit, Mount Cameroon can be seen to the north-east. Pico Basilé lies close to the city of Malabo."},{"name":"Mount Alayta","slug":"mount-alayta","category":"Mountain","country":"Ethiopia","region":"Kilbet Rasu","city":null,"latitude":12.88806,"longitude":40.57194,"description":"Mount Alayta is an active shield volcano in the Afar Region of Ethiopia. It is part of the Afar Triangle, a highly active volcanic region which includes the adjacent Mount Afdera. Mount Alayta covers an area of 2,700 square kilometers southwest of Lake Afrera."},{"name":"Marion Island","slug":"marion-island","category":"Mountain","country":"South Africa","region":"Western Cape","city":null,"latitude":-46.90611,"longitude":37.73694,"description":"The Prince Edward Islands are two small uninhabited subantarctic volcanic islands in the southern Indian Ocean that are administered by South Africa. They are named Marion Island and Prince Edward Island."},{"name":"Tarso Yega","slug":"tarso-yega","category":"Mountain","country":"Chad","region":null,"city":null,"latitude":20.66,"longitude":17.42,"description":"Tarso Yega is a stratovolcano in Tibesti, with a summit caldera that is 19 by 20 kilometres wide and 300 metres (980 ft) deep. The summit of the volcano reaches a height of 2,972 metres (9,751 ft), and its caldera is the largest caldera of the Tibesti. Neighbouring volcanoes include Doudriki east, Ehi Dosoatou south and Ehi Fodoboro southwest of the caldera."},{"name":"Mount Suswa","slug":"mount-suswa","category":"Mountain","country":"Kenya","region":null,"city":null,"latitude":-1.04948,"longitude":36.33352,"description":"Mount Suswa is a shield volcano in the Great Rift Valley, Kenya. It is located between Narok and Nairobi, the capital of Kenya. The northwestern part of Mount Suswa is in Narok County, while the eastern and southern parts are in Kajiado County. The town with the same name, Suswa, is just northwest of the mountain and it is the main access point for visits to the mountain."},{"name":"Emuruangogolak","slug":"emuruangogolak","category":"Mountain","country":"Kenya","region":null,"city":null,"latitude":1.5,"longitude":36.33,"description":"Emuruangogolak is an active shield volcano straddling the Gregory Rift in Kenya, in Eastern Africa. It has a 3.5-by-5.0-kilometre caldera on its summit. The last known eruption was a trachyte flow which occurred in 1910. Steam vents and fumarolic activity continues from fissures within the caldera and along the flanks of the volcano. Several maar lakes exist in the rift valley adjacent to the volcano."},{"name":"San Carlos","slug":"san-carlos","category":"Mountain","country":"Equatorial Guinea","region":"Bioko Sur","city":null,"latitude":3.35611,"longitude":8.51306,"description":"San Carlos is a basaltic shield volcano with a broad summit caldera on the island of Bioko, Equatorial Guinea. With an elevation of 2,261 metres above sea level it is the second highest peak in Equatorial Guinea."},{"name":"Korosi","slug":"korosi","category":"Mountain","country":"Kenya","region":"Baringo County","city":null,"latitude":0.77,"longitude":36.12,"description":"Korosi is a shield volcano located in the Gregory Rift at the northern end of Lake Baringo, Kenya."},{"name":"Jbel El Koudiate","slug":"jbel-el-koudiate","category":"Mountain","country":"Morocco","region":"Ifrane Province","city":null,"latitude":33.53111,"longitude":-5.15639,"description":"Jbel El Koudiate is an extinct shield volcano located 5 km west of the city of Ifrane in the Middle Atlas of Morocco. It is one of the three main volcanic structures of the Azrou region with Jbel Outgui and Jbel Tamarrakoit."},{"name":"Jbel Outgui","slug":"jbel-outgui","category":"Mountain","country":"Morocco","region":"Ifrane Province","city":null,"latitude":33.64278,"longitude":-5.24694,"description":"Jbel Outgui is an extinct shield volcano located 15 km southeast of the city of El Hajeb in the Middle Atlas of Morocco. The mountain is one of the three main volcanic structures of the Azrou region with Jbel El Koudiate and Jbel Tamarrakoit."},{"name":"Jbel Tamarrakoit","slug":"jbel-tamarrakoit","category":"Mountain","country":"Morocco","region":"Ifrane Province","city":null,"latitude":33.0623,"longitude":-5.0652,"description":"Jbel Tamarrakoit is an extinct shield volcano located 60 km south of the city of Ifrane in the Middle Atlas of Morocco. This mountain is one of the three main volcanic structures of the Azrou region along with Jbel El Koudiate and Jbel Outgui."},{"name":"Chenoua","slug":"chenoua","category":"Mountain","country":"Algeria","region":"Tipasa Province","city":null,"latitude":36.60639,"longitude":2.37167,"description":"Mount Chenoua is a mountain range in northern Algeria. It is located between Cherchell and Tipaza on the Mediterranean coast, just west of Algiers. There are marble quarries on the side of the mountain."},{"name":"Jebel Dair","slug":"jebel-dair","category":"Mountain","country":"Sudan","region":null,"city":null,"latitude":12.44,"longitude":30.65,"description":"Jebel Dair is an igneous mountain in the Er Rahad locality in the state of North Kordofan, in central Sudan. It rises over 1000m above the surrounding terrain and 1451m above sea level. The flanks of the mountain apparently have been denuded of vegetation, although water exists in some of the meandering stream channels within the darker, vegetated wadis."},{"name":"Afdera","slug":"afdera","category":"Mountain","country":"Ethiopia","region":"Kilbet Rasu","city":null,"latitude":13.08806,"longitude":40.85306,"description":"Afdera is an isolated stratovolcano in northeastern Ethiopia, located at the intersection of three fault systems between the Erta Ale, Tat Ali, and Alayta mountain ranges."},{"name":"Mount Dama Ali","slug":"mount-dama-ali","category":"Mountain","country":"Ethiopia","region":"Awsi Rasu","city":null,"latitude":11.28724,"longitude":41.63811,"description":"Mount Dama Ali is a 25 km (16 mi) wide shield volcano in Ethiopia, on the shore of Lake Abbe."},{"name":"Mount Sinai","slug":"mount-sinai","category":"Mountain","country":"Egypt","region":"South Sinai Governorate","city":null,"latitude":28.5384,"longitude":33.9752,"description":"Mount Sinai, also known as Jabal Musa, is a mountain on the Sinai Peninsula of Egypt. It is one of several locations claimed to be the biblical Mount Sinai, the place where, according to the sacred scriptures of the three major Abrahamic religions, the Hebrew prophet Moses received the Ten Commandments from God."},{"name":"Trou aux Cerfs","slug":"trou-aux-cerfs","category":"Mountain","country":"Mauritius","region":"Curepipe","city":null,"latitude":-20.31812,"longitude":57.51153,"description":"Trou aux Cerfs is a dormant, crater lake, cinder cone volcano with a well-defined cone and crater. It is 605 m (1,985 ft) high and located in Curepipe, Mauritius. The crater has been alternately described as 300 and 350 meters in diameter, and is 80 meters deep."},{"name":"Ben Amera","slug":"ben-amera","category":"Mountain","country":"Mauritania","region":null,"city":null,"latitude":21.23333,"longitude":-13.66667,"description":"Ben Amera is Africa's largest monolith, rising 633 metres (2,077 ft) above the desert floor. It is the world's second-largest monolith, after only Uluru in Australia. Ben Amera is located in Mauritania, near the border with Western Sahara. It lies 4 kilometres (2.5 mi) north of the train track where the famous Iron Ore Train travels between Nouâdibhou and Choûm."},{"name":"Mount Oku","slug":"mount-oku","category":"Mountain","country":"Cameroon","region":"Bui","city":null,"latitude":6.19972,"longitude":10.51889,"description":"Mount Oku, or Kilum Mountain, is the largest volcano in the Oku Massif, in the Cameroon Volcanic Line, located in the Oku region of the Western High Plateau of Cameroon. It is the second highest mountain in mainland Central Africa. The stratovolcano rises to 3,011 metres (9,879 ft) above sea level, and is cut by a large caldera."},{"name":"Dofan","slug":"dofan","category":"Mountain","country":"Ethiopia","region":"Gabi Rasu","city":null,"latitude":9.34444,"longitude":40.13194,"description":"Dofan or Dofen is a 1,151 m (3,776 ft) high rhyolitic shield volcano in Ethiopia's Awash National Park. The volcano rises 450 m (1,480 ft) above the valley floor. A north–south zone of cinder cones extending 10 km (6.2 mi); the cones in the north show intense fumarolic activity. Along the southern flank crater, a fumarole produced significant sulfur. The volcano's last eruptions were during the Holocene."},{"name":"Mount Manengouba","slug":"mount-manengouba","category":"Mountain","country":"Cameroon","region":"Moungo","city":null,"latitude":5.03,"longitude":9.83,"description":"Mount Muanenguba is a volcano in the Southwest Province of Cameroon. The Manenguba shrew and endemic vegetal species are native to the mountain. The area is featured in the documentary The Mists of Mwanenguba with botanist Martin Cheek."},{"name":"Kitumbeine Volcano","slug":"kitumbeine-volcano","category":"Mountain","country":"Tanzania","region":"Monduli District","city":null,"latitude":-2.8795,"longitude":36.211,"description":"Kitumbeine Volcano also known as Kitumbeine at 2,850m is a shield volcano located in Longido District of Arusha Region in Tanzania. It stands at 2,850 metres (9,350 ft). The volcano is shared amongst three wards of Longido District, namely; Elang'ata Dapash, Kitumbeine and Iloirienito wards."},{"name":"Mount Kupe","slug":"mount-kupe","category":"Mountain","country":"Cameroon","region":"Koupé-Manengouba","city":null,"latitude":4.801,"longitude":9.707,"description":"Mount Kupe or Mont Koupé is a plutonic mountain in the Western High Plateau of Cameroon, part of the Cameroon line of volcanoes. It is the highest of the Bakossi Mountains, rising to 2,064 metres (6,772 ft)."},{"name":"Tshibinda","slug":"tshibinda","category":"Mountain","country":"Democratic Republic of the Congo","region":null,"city":null,"latitude":-2.31667,"longitude":28.75,"description":"Tshibinda is a group of pyroclastic cones in the east of the Democratic Republic of the Congo. It has a prominence of 1,460 metres (4,790 ft). It last erupted during the Pleistocene epoch."},{"name":"May-Ya-Moto","slug":"may-ya-moto","category":"Mountain","country":"Democratic Republic of the Congo","region":"Rutshuru","city":null,"latitude":-0.93333,"longitude":29.33333,"description":"May-Ya-Moto is a potentially active volcano in the east of the Democratic Republic of the Congo. It has a prominence of 950 metres (3,117 ft). Although no eruptions have been dated, the volcano still shows signs of unrest. At the crater, fumaroles and hot springs are active. Water temperatures are less than (100 °C. There have been few studies on this volcano."},{"name":"Alu","slug":"alu","category":"Mountain","country":"Ethiopia","region":"Kilbet Rasu","city":null,"latitude":13.825,"longitude":40.508,"description":"Alu is a system of volcanic fissures, located in Ethiopia. The fissures have produced silicic lava flows, and other fissures south of the volcano have been the source of huge youthful basaltic lava flows, which enlarge to the north as far as Lake Bakili. There is major fumarolic activity, located on parallel faults, some with 100-m uplifts."},{"name":"Amba Alagi","slug":"amba-alagi","category":"Mountain","country":"Ethiopia","region":"Debubawi Zone","city":null,"latitude":12.98333,"longitude":39.55,"description":"Imba Alaje is a mountain, or an amba, in northern Ethiopia. Located in the Debubawi Zone of the Tigray Region, Imba Alaje dominates the roadway that runs past it from the city of Mek'ele south to Maychew. Because of its strategic location, Emba Alaje has been the site of several battles."},{"name":"Amba Geshen","slug":"amba-geshen","category":"Mountain","country":"Ethiopia","region":"Debub Wollo Zone","city":null,"latitude":11.4986,"longitude":39.3184,"description":"Amba Geshen is the name of a mountain in northern Ethiopia. It is in Ambassel, South Wollo Zone of the Amhara Region, northwest of Dessie, at a latitude and a longitude of 11°31′N 39°21′E. Part of Ambassel woreda, Amba Geshen is one of the mountains of Ethiopia where most of the male heirs to the Emperor of Ethiopia were interned, usually for life."},{"name":"Arkenu craters","slug":"arkenu-craters","category":"Mountain","country":"Libya","region":null,"city":null,"latitude":22.10139,"longitude":23.79833,"description":"The Arkenu structures, also known as the Arkenu craters, are a pair of prominent circular geological structures in eastern Libya. The structures are approximately 10 kilometres (6.2 mi) and 6.8 kilometres (4.2 mi) in diameter, and lie about 70 kilometres (43 mi) west of Jabal Arkanu on the eastern margin of the al-Kufrah Basin."},{"name":"Aïdour","slug":"a-dour","category":"Mountain","country":"Algeria","region":"Oran District","city":null,"latitude":35.70194,"longitude":-0.68278,"description":"The Aïdour, or Murdjajo, is a mountain reaching an altitude of 429.3 m, overlooking the city of Oran. Several buildings were constructed there, including the fort and the chapel of Santa Cruz."},{"name":"Lake Tissongo","slug":"lake-tissongo","category":"Lake","country":"Cameroon","region":"Littoral","city":null,"latitude":3.56889,"longitude":9.87889,"description":"Lake Tissongo is a lake of western Cameroon. It is situated within the Douala Edéa Wildlife Reserve of Littoral Province, and is connected to the south bank of the Sanaga River by a 5 kilometres (3.1 mi) tidal channel. The lake drains into the river about 40 kilometres downstream of Edéa. The area is biologically rich."},{"name":"Zeekoevlei","slug":"zeekoevlei","category":"Lake","country":"South Africa","region":"Western Cape","city":null,"latitude":-34.0667,"longitude":18.5167,"description":"Zeekoevlei is a freshwater lake in the Southern Suburbs of Cape Town, South Africa. The lake is 258 hectares in area. Its name means hippopotamus pond or lake, from the Afrikaans words seekoei and vlei."},{"name":"Fernan Vaz Lagoon","slug":"fernan-vaz-lagoon","category":"Lake","country":"Gabon","region":null,"city":null,"latitude":-1.51433,"longitude":9.20833,"description":"Fernan Vaz Lagoon is a large lagoon on the Atlantic coast of Gabon. It is named for Fernão Vaz, the first European to reach it, and is known its wildlife and for the church at Mission Saint Anne, built in 1889 by Gustav Eiffel. The main settlement on the lagoon's shore is Omboué."},{"name":"Aby Lagoon","slug":"aby-lagoon","category":"Lake","country":"Ivory Coast","region":null,"city":null,"latitude":5.27944,"longitude":-3.22472,"description":"The Aby Lagoon complex is the second largest lagoon in Ivory Coast, after Ébrié Lagoon. As a whole, the lagoon has an area of 424 km2 (164 sq mi), a mean depth of 3.5 m (11 ft), and a volume of 1.57 km3 (0.38 cu mi). It drains into the Atlantic Ocean through shallow channels between the Ehotilé Islands that converge at Assinie-Mafia, where Assoindé Lagoon also connects from the west."},{"name":"Small Bitter Lake","slug":"small-bitter-lake","category":"Lake","country":"Egypt","region":"Suez Governorate","city":null,"latitude":30.22694,"longitude":32.54222,"description":"The Great Bitter Lake is a large saltwater lake in Egypt which is part of the Suez Canal. Before the canal was built in 1869, the Great Bitter Lake was a dry salt valley or basin. References are made to the Great Bitter Lake in the ancient Pyramid Texts."},{"name":"Lake Mariout","slug":"lake-mariout","category":"Lake","country":"Egypt","region":"Alexandria","city":null,"latitude":31.15306,"longitude":29.89861,"description":"Lake Mariout, is a brackish lake in northern Egypt near the city of Alexandria. The lake area covered 200 square kilometres (77 sq mi) and had a navigable canal at the beginning of the 20th century, but at the beginning of the 21st century, it covers only about 50 square kilometres (19 sq mi)."},{"name":"Sakumo Ramsar Site","slug":"sakumo-ramsar-site","category":"Lake","country":"Ghana","region":"Greater Accra Region","city":null,"latitude":5.61528,"longitude":-0.03222,"description":"The Sakumo Ramsar Site also known as the Sakumo Lagoon is a wetland of international importance. It covers an area of 1,400 hectares and is situated along the coastal road between Accra and Tema in the Greater Accra Region of Ghana. It is about 3 km (1.9 mi) west of Tema. Activities ongoing within the site include farming, fishing, recreation, urban and industrial development."},{"name":"Lake Bardawil","slug":"lake-bardawil","category":"Lake","country":"Egypt","region":"North Sinai Governorate","city":null,"latitude":31.19056,"longitude":33.16222,"description":"Lake Bardawil, is a large, very saline lagoon near the protected of Zaranik in Egypt on the north coast of the Sinai Peninsula. Lake Bardawil is about 30 kilometers (19 mi) long, and 14 kilometers (8.7 mi) wide. It is considered to be one of the three major lakes of the Sinai Peninsula, along with the Great Bitter Lake and the Little Bitter Lake."},{"name":"Lagune Ndogo","slug":"lagune-ndogo","category":"Lake","country":"Gabon","region":null,"city":null,"latitude":-2.58333,"longitude":10.0,"description":"The Ndogo Lagoon is the largest lagoon in Gabon, located in the southwestern part of the country. It has a surface area of 487 square kilometres (188 sq mi). It runs parallel to the Atlantic coast for about 40 kilometres (25 mi), with an outlet to the sea at the northwest. Because of its small outlet compared to its length, the lagoon's water is not very saline, with a salinity below 1 g/L."},{"name":"Lake Volta","slug":"lake-volta","category":"Lake","country":"Ghana","region":null,"city":null,"latitude":7.40057,"longitude":0.19472,"description":"Lake Volta, the largest artificial reservoir in the world by surface area, is contained behind the Akosombo Dam which generates a substantial amount of Ghana's electricity. It is completely within the country of Ghana and has a surface area of 8,502 square kilometres (3,283 sq mi). It extends from Akosombo in the south to the northern part of the country southwest of Tamale."},{"name":"Lake Nasser","slug":"lake-nasser","category":"Lake","country":"Egypt","region":"Aswan Governorate","city":null,"latitude":22.5,"longitude":31.86,"description":"Lake Nasser is a large reservoir in southern Egypt and northern Sudan. It was created by the construction of the Aswan High Dam and is one of the largest man-made lakes in the world. The lake has become an important economic resource in Egypt, improving agriculture and supporting robust fishing and tourism industries. The lake is named after Gamal Abdel Nasser, the second President of Egypt."},{"name":"Lake Kossou","slug":"lake-kossou","category":"Lake","country":"Ivory Coast","region":null,"city":null,"latitude":7.15,"longitude":-5.59,"description":"Lake Kossou is Côte d'Ivoire's largest lake. It lies on the Bandama River in the center of the country. It is an artificial lake, created in 1973 by damming the Bandama River at Kossou. Some 75,000 Baoulé people were displaced by the lake."},{"name":"Mar Chica","slug":"mar-chica","category":"Lake","country":"Morocco","region":null,"city":null,"latitude":35.16,"longitude":-2.84,"description":"Marchica, also known as Sebkha Bou Areg, is a lagoon in northern Morocco, adjacent to the city of Nador."},{"name":"Lake Sibhayi","slug":"lake-sibhayi","category":"Lake","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-27.3525,"longitude":32.69139,"description":"Lake Sibaya, also known as Lake Sibhayi, a freshwater lake in South Africa, with a surface area of 64 km2 (25 sq mi). The lake is also known as Sibaya or Sibhaya."},{"name":"Lake Timsah","slug":"lake-timsah","category":"Lake","country":"Egypt","region":null,"city":null,"latitude":30.57778,"longitude":32.28889,"description":"Lake Timsah, Arabic for Crocodile Lake, is a lake in Egypt on the Nile Delta. It lies in a basin developed along a fault extending from the Mediterranean Sea to the Gulf of Suez through the Bitter Lakes region. In 1800, a flood filled the Wadi Tumilat, which caused Timsah's banks to overflow and moved water south into the Bitter Lakes about nine miles (14 km) away."},{"name":"Lekki Lagoon","slug":"lekki-lagoon","category":"Lake","country":"Nigeria","region":"Lagos State","city":null,"latitude":6.5,"longitude":4.11667,"description":"Lekki Lagoon is a lagoon located in Lagos and Ogun states in Nigeria. The lagoon lies directly to the east of Lagos Lagoon and is connected to it by a channel. It is surrounded by many beaches. The surrounding vegetation is predominantly characterized by swamp forests and mangrove vegetation, which helps stabilize the shoreline and filter pollutants."},{"name":"Keta Lagoon","slug":"keta-lagoon","category":"Lake","country":"Ghana","region":"Volta Region","city":null,"latitude":5.8879,"longitude":0.8267,"description":"Keta Lagoon, also called Anlo-Keta lagoon, is the largest of the over 90 lagoons that cover the 550 km stretch of the coastline of Ghana. This lagoon is 126.13 km in length. It is located in the eastern coast of Ghana and separated from the Gulf of Guinea by a narrow strip of sandbar. This open salty water is surrounded by flood plains and mangrove swamps."},{"name":"Sakumono Lagoon","slug":"sakumono-lagoon","category":"Lake","country":"Ghana","region":null,"city":null,"latitude":5.64167,"longitude":-0.03333,"description":"Sakumono Lagoon is a coastal lagoon in Sakumono near Tema in the Greater Accra Region of Ghana, West Africa. The site covers 1,340 hectares. It was designated to form the bulk of the Sakumo Ramsar Site, a Ramsar wetland site of international importance, on 14 August 1992."},{"name":"Lake Nokoué","slug":"lake-nokou","category":"Lake","country":"Benin","region":null,"city":null,"latitude":6.43278,"longitude":2.42556,"description":"Lake Nokoué is a lake in the southern part of Benin. It is 20 km (12 mi) wide and 11 km (6.8 mi) long and covers an area of 4,900 ha. The lake is partly fed by the Ouémé River and the Sô River, both of which deposit sediments from throughout the region in the lake."},{"name":"Ébrié Lagoon","slug":"bri-lagoon","category":"Lake","country":"Ivory Coast","region":null,"city":null,"latitude":5.27186,"longitude":-4.33925,"description":"The Ébrié Lagoon lies in Ivory Coast, separated for almost all of its length from the Atlantic Ocean by a narrow coastal strip. The 130 km (80 mi) long lagoon is linked to the sea by the Vridi Canal, while the Komoé River flows into it. The lagoon averages 4 km in width, and 5 m (16 ft) in depth. Abidjan and towns such as Grand Bassam, Bingerville, Jacqueville, Attécoubé, and Tiagba lie on the lagoon."},{"name":"Lake of Tunis","slug":"lake-of-tunis","category":"Lake","country":"Tunisia","region":"Tunis Governorate","city":null,"latitude":36.81667,"longitude":10.25,"description":"The Lake of Tunis is a natural lagoon located between the Tunisian capital city of Tunis and the Gulf of Tunis. The lake covers a total of 37 square kilometres, in contrast to its size its depth is very shallow. It was once the natural harbour of Tunis."},{"name":"Bahiret el Bibane","slug":"bahiret-el-bibane","category":"Lake","country":"Tunisia","region":"Medenine Governorate","city":null,"latitude":33.24556,"longitude":11.24863,"description":"Bahiret el Bibane is a large lagoon of around 33 km length by 10 km width near the Libyan border located 10 km North of the town of Ben Gardane and 20 km West of the city of Zarzis, in the Medenine governorate. It has been classified as a Ramsar Wetland since 2007. The lagoon itself is the second largest in Tunisia after the lagoon or gulf of Boughrara."},{"name":"Lake Bermin","slug":"lake-bermin","category":"Lake","country":"Cameroon","region":"Southwest","city":null,"latitude":5.15889,"longitude":9.63583,"description":"Lake Bermin is a small lake in the volcanic chain in the Southwest Region of Cameroon. It is a volcanic lake with a diameter of about 700 m (2,300 ft) and a crater rim that rises to a height of about 46 m (150 ft). This highly isolated lake is roughly circular in shape, lacks an inflow, but has an outflow into the Cross River system."},{"name":"Lake Victoria","slug":"lake-victoria","category":"Lake","country":"Kenya","region":null,"city":null,"latitude":-1.0,"longitude":33.0,"description":"Lake Victoria is one of the African Great Lakes. With a surface area of approximately 59,947 km2 (23,146 sq mi), Lake Victoria is Africa's largest lake by area, the world's largest tropical lake, and the world's second-largest fresh water lake by surface area after Lake Superior in North America."},{"name":"Lake Malawi","slug":"lake-malawi","category":"Lake","country":"Tanzania","region":null,"city":null,"latitude":-12.18333,"longitude":34.36667,"description":"Lake Malawi, also known as Lake Nyasa in Tanzania and Lago Niassa in Mozambique, is an African Great Lake and the southernmost lake in the East African Rift system, located between Malawi, Mozambique and Tanzania."},{"name":"Lake Tanganyika","slug":"lake-tanganyika","category":"Lake","country":"Tanzania","region":null,"city":null,"latitude":-6.1,"longitude":29.5,"description":"Lake Tanganyika is an African Great Lake. It is the world's second-largest freshwater lake by volume and the second deepest, in both cases after Lake Baikal in Siberia. It is the world's longest freshwater lake. It is also the 6th largest lake by area."},{"name":"Pool Malebo","slug":"pool-malebo","category":"Lake","country":"Republic of the Congo","region":"Kinshasa","city":null,"latitude":-4.28194,"longitude":15.48861,"description":"The Pool Malebo, also known historically as Mpumbu, Lake Nkunda, Lake Nkuna, Lake Ntamo, or Lake Ngobila, is a broad, lake-like widening of the lower Congo River in Central Africa that forms a natural basin where the river expands before descending downstream into the Livingstone Falls."},{"name":"Lake Ichkeul","slug":"lake-ichkeul","category":"Lake","country":"Tunisia","region":"Bizerte Governorate","city":null,"latitude":37.162,"longitude":9.66706,"description":"Lake Ichkeul is a lake in northern Tunisia, located 20 kilometres to Bizerte, the northernmost city in Africa on the Mediterranean Sea. The lake and wetlands of Ichkeul National Park are an important stopping-over point for hundreds of thousands of migrating birds each year. Among the lake's visitors are ducks, geese, storks, and pink flamingoes."},{"name":"Lake Mweru","slug":"lake-mweru","category":"Lake","country":"Zambia","region":null,"city":null,"latitude":-9.16667,"longitude":28.5,"description":"Lake Mweru is a freshwater lake on the longest arm of Africa's second-longest river, the Congo. Located on the border between Zambia and Democratic Republic of the Congo, it makes up 110 kilometres (68 mi) of the total length of the Congo, lying between its Luapula River (upstream) and Luvua River (downstream) segments."},{"name":"Lake Fitri","slug":"lake-fitri","category":"Lake","country":"Chad","region":"Batha Region","city":null,"latitude":12.80917,"longitude":17.5025,"description":"Lake Fitri is a shallow freshwater lake in central Chad, located in the Sahel region about 300 km east of N’Djamena. It has been designated a Wetland of International Importance under the Ramsar Convention."},{"name":"Asejire Reservoir","slug":"asejire-reservoir","category":"Lake","country":"Nigeria","region":"Oyo","city":null,"latitude":7.36694,"longitude":4.13333,"description":"The Asejire Reservoir is a reservoir in Nigeria, located on the border between Oyo State and Osun State, about 30 kilometers east of the city of Ibadan. The reservoir is created by the impoundment of the Osun River by the Asejire Dam. The reservoir was built in the late 1960s. Farming is totally banned in the catchment area, and trees have been planted on the banks, making erosion and silting non-issues."},{"name":"Lake Ashenge","slug":"lake-ashenge","category":"Lake","country":"Ethiopia","region":"Tigray Region","city":null,"latitude":12.58056,"longitude":39.5,"description":"Lake Hashenge is a lake in the southern Tigray Region of Ethiopia. Located in the Ethiopian Highlands at an elevation of 2409 meters, it has no outlet. According to the Statistical Abstract of Ethiopia for 1967/68, Lake Hashenge is five kilometers long and four wide, with a surface area of 20 square kilometers."},{"name":"Chott el Hodna","slug":"chott-el-hodna","category":"Lake","country":"Algeria","region":"M'Sila Province","city":null,"latitude":35.44167,"longitude":4.76667,"description":"The Chott el Hodna is a very shallow saline lake in Algeria. It is located within an endorheic basin in the Hodna region, towards the eastern end of the Hautes Plaines. The Chott el Hodna includes seasonal brackish and saline pools and marshes, but the central zone of the lake is characterized by a complete absence of vegetation."},{"name":"Lake Chilwa","slug":"lake-chilwa","category":"Lake","country":"Malawi","region":"Zomba District","city":null,"latitude":-15.3,"longitude":35.7,"description":"Lake Chilwa is the second-largest lake in Malawi after Lake Malawi. It is in eastern Zomba District, near the border with Mozambique. Approximately 60 km long and 40 km wide, the lake is surrounded by extensive wetlands. There is an island in the middle of the lake called Chisi Island. The lake has no outlet, and the level of water is greatly affected by seasonal rains and summer evaporation."},{"name":"Lake Amaramba","slug":"lake-amaramba","category":"Lake","country":"Mozambique","region":null,"city":null,"latitude":-14.3775,"longitude":35.92194,"description":"Lake Amaramba is a shallow lake in Mozambique, near the border with Malawi. Located in the Nyasa plateau, it is north of Lake Chiuta. The lakes are separated by a sandy ridge and a channel links the two lakes. On the western side of the channel, the connecting waterway is known as the River Msambiti while on the eastern side, it is known as the Lugenda River."},{"name":"Lake Ambussel","slug":"lake-ambussel","category":"Lake","country":"Tanzania","region":null,"city":null,"latitude":-3.95,"longitude":37.26667,"description":"Lake Ambussel is a lake on the Lossogonoi Plateau in Tanzania. Along with Nyumba ya Mungu Reservoir, Lake Chala and Lake Jipe, it is one of four waterbodies in the Pangani basin. It covers an area of about 19 km2 (7.3 sq mi), spanning 6 by 4.5 km."},{"name":"Lake Basaka","slug":"lake-basaka","category":"Lake","country":"Ethiopia","region":null,"city":null,"latitude":8.86667,"longitude":39.8667,"description":"Lake Basaka is a shallow, saline lake in the Oromia Region of central Ethiopia. It is located in the Great Rift Valley about 200 kilometres (120 mi) south east of the capital Addis Ababa. The lake is at an elevation of 950 metres (3,000 ft)."},{"name":"Lake Kwania","slug":"lake-kwania","category":"Lake","country":"Uganda","region":"Lira","city":null,"latitude":1.71667,"longitude":32.7,"description":"Lake Kwania is in the districts of Lira, Apac and Amolatar in the Northern Region of Uganda. It is part of a large wetland along the White Nile between Lake Victoria and Lake Albert. The wetland, which includes Lake Kwania, the even larger Lake Kyoga, and other water bodies and swamps, consists of about 3,420 square kilometres (1,320 mi2) of open water and about 2,180 square kilometres (840 mi2) of permanent swamps."},{"name":"Lake Guinas","slug":"lake-guinas","category":"Lake","country":"Namibia","region":null,"city":null,"latitude":-19.23292,"longitude":17.35265,"description":"Lake Guinas is the larger of only two permanent natural lakes in Namibia. It is a sinkhole lake, created by a collapsing karst cave, located thirty-eight kilometres west of Tsumeb, near the D3043 road."},{"name":"Lagos Lagoon","slug":"lagos-lagoon","category":"Lake","country":"Nigeria","region":null,"city":null,"latitude":6.50158,"longitude":3.52249,"description":"Lagos Lagoon is a lagoon found in the city of Lagos, southwest Nigeria, the most populous city in Africa. The name Lagos means 'lakes' in Portuguese, therefore Lagos Lagoon is an example of a tautological place name. The lagoon lies between the Atlantic Ocean and Lagos State. It is one of the ten lagoons in Lagos State and the largest in the Gulf of Guinea which spans over 6,000 square kilometres (2,300 sq mi)."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 5: % places added', added;
end $$;

-- batch 6 of 6: 131 places
do $$
declare
  added int;
begin
  insert into public.places
    (name, slug, category, country, region, city, latitude, longitude,
     best_season, best_time, access_info, entry_fee, description, status, created_by)
  select x.name, x.slug, x.category, x.country, x.region, x.city, x.latitude, x.longitude,
         'Check the best season locally',
         'Check opening times locally',
         'Check access, opening times and conditions locally before travelling.',
         'Varies. Check before you go.',
         x.description, 'draft',
         (select id from public.profiles order by created_at limit 1)
    from jsonb_to_recordset($tl$[{"name":"Lake Kulul","slug":"lake-kulul","category":"Lake","country":"Eritrea","region":"Northern Red Sea Region","city":null,"latitude":14.38333,"longitude":40.35,"description":"Lake Kulul is the lowest point in Eritrea, located in the Northern Red Sea Region. It lies in the Eritrean portion of the Danakil Depression at approximately 75 meters below sea level."},{"name":"Lake Bam","slug":"lake-bam","category":"Lake","country":"Burkina Faso","region":"Kongoussi","city":null,"latitude":13.40167,"longitude":-1.5175,"description":"Lake Bam is located near the town of Kongoussi, in Burkina Faso. The lake is slowly drying up, putting at risk the nearby village's agriculture, fish stocks, and cattle watering. The lake has been designated as a Ramsar site since 2009."},{"name":"Lake Kariba","slug":"lake-kariba","category":"Lake","country":"Zambia","region":null,"city":null,"latitude":-16.9,"longitude":28.0,"description":"Lake Kariba is the world's largest artificial lake and reservoir by volume. It lies 1,300 kilometres (810 mi) upstream from the mouth of the Zambezi river on the Indian Ocean, bordering Zambia and Zimbabwe. Lake Kariba was filled between 1958 and 1963 following the completion of the Kariba Dam at its northeastern end, flooding the Kariba Gorge on the Zambezi River."},{"name":"Koka Reservoir","slug":"koka-reservoir","category":"Lake","country":"Ethiopia","region":null,"city":null,"latitude":8.38333,"longitude":39.08333,"description":"The Koka Reservoir is a reservoir in south-central Ethiopia. It was created by the construction of the Koka Dam across the Awash River. The reservoir has an area of 180 square kilometres (69 sq mi)."},{"name":"Lake Alaotra","slug":"lake-alaotra","category":"Lake","country":"Madagascar","region":"Toamasina Province","city":null,"latitude":-17.5,"longitude":48.5,"description":"Lake Alaotra is the largest lake in Madagascar, located in Alaotra-Mangoro Region and on the island's northern central plateau. Its basin is composed of shallow freshwater lakes and marshes surrounded by areas of dense vegetation. It forms the center of the island's most important rice-growing region."},{"name":"Lake Manyara","slug":"lake-manyara","category":"Lake","country":"Tanzania","region":"Manyara Region","city":null,"latitude":-3.58333,"longitude":35.83333,"description":"Lake Manyara also known as Lake Moya among the Iraqw people is a lake located in Monduli District of Arusha Region, Tanzania and is the seventh-largest lake of Tanzania by surface area, at 470-square-kilometre (180 sq mi). It is a shallow, alkaline lake in the Natron-Manyara-Balangida branch of the East African Rift."},{"name":"Lake Abijatta","slug":"lake-abijatta","category":"Lake","country":"Ethiopia","region":"Oromia Region","city":null,"latitude":7.61667,"longitude":38.6,"description":"Lake Abijatta is an alkaline lake in Ethiopia. It lies in the Main Ethiopian Rift valley south of Addis Ababa, in the Abijatta-Shalla National Park."},{"name":"Lake Nyos","slug":"lake-nyos","category":"Lake","country":"Cameroon","region":"Northwest","city":null,"latitude":6.43806,"longitude":10.29889,"description":"Lake Nyos is a crater lake in the Northwest Region of Cameroon, located about 315 km (196 mi) northwest of Yaoundé, the capital of Cameroon. Nyos is a deep lake high on the flank of an inactive volcano in the Oku volcanic plain along the Cameroon line of volcanic activity. A volcanic dam impounds the lake waters."},{"name":"Lake Afrera","slug":"lake-afrera","category":"Lake","country":"Ethiopia","region":"Afar Region","city":null,"latitude":13.28333,"longitude":40.91667,"description":"Lake Afrera is a hypersaline lake in northern Ethiopia. Located in Kilbet Rasu, Afar Region, it is one of the lakes of the Danakil Depression. It has a surface of 117 km2 (45 mi2) and holds 2.4 km3 of brine. The maximal depth of Lake Afdera is 80 m in the northern basin and 76 m in the southern basin. No major river drains the lake. It is fed by hot springs along the shores of the lakes."},{"name":"Merja Zerga","slug":"merja-zerga","category":"Lake","country":"Morocco","region":"Rabat-Salé-Kénitra","city":null,"latitude":34.84776,"longitude":-6.27568,"description":"Merja Zerga or Lagune de Moulay Bou Selham is a tidal lagoon on the Atlantic coast of Morocco, 70 km north of the city of Kenitra. Classified as a Permanent Biological Reserve in 1978, it is managed by several government agencies."},{"name":"Lake No","slug":"lake-no","category":"Lake","country":"South Sudan","region":null,"city":null,"latitude":9.49778,"longitude":30.465,"description":"Lake No is the largest lake in South Sudan, which is locally known as Dhoo Lake by Ruweng Panaruu community. It is located just north of the vast swamp of the Sudd, at the confluence of the Bahr al Jabal and Bahr el Ghazal rivers, and marks the transition between the Bahr al Jabal and White Nile proper."},{"name":"Ga'raet el Oubeïra","slug":"garaet-el-oube-ra","category":"Lake","country":"Algeria","region":"El Tarf Province","city":null,"latitude":36.8473,"longitude":8.3876,"description":"Lake Oubeïra is a freshwater lake situated in El-Kala National Park in El Tarf Province, Algeria. It was designated as a Ramsar site on 4 November 1983. The lake serves as a significant nesting area for bird species in North Africa."},{"name":"Lake Karum","slug":"lake-karum","category":"Lake","country":"Ethiopia","region":"Afar Region","city":null,"latitude":14.0167,"longitude":40.4167,"description":"Lake Karum is a salt lake in the Afar Region of Ethiopia. One of two salt lakes in the northern end of the Danakil Depression, it lies 120 m (394 ft) below sea level. The volcano Erta Ale rises southeast of this lake."},{"name":"Lake Kompienga","slug":"lake-kompienga","category":"Lake","country":"Burkina Faso","region":null,"city":null,"latitude":11.13889,"longitude":0.63444,"description":"Lake Kompienga is a reservoir lake in Kompienga Province in southeastern Burkina Faso. The Kompienga Dam was built in the 1980s to create the lake for economic purposes."},{"name":"Lake Mutirikwe","slug":"lake-mutirikwe","category":"Lake","country":"Zimbabwe","region":null,"city":null,"latitude":-20.24892,"longitude":31.03326,"description":"Lake Mutirikwi, originally known as Lake Kyle or Kyle Dam, lies in south eastern Zimbabwe, south east of Masvingo. It is thought to have been named after Kyle Farm which occupied most of the land required for the lake, which in turn was named after the Kyle district in Scotland from which the pioneer of the Lowveld, Tom Murray MacDougall came originally."},{"name":"Cahora Bassa Reservoir","slug":"cahora-bassa-reservoir","category":"Lake","country":"Mozambique","region":"Cahora-Bassa District","city":null,"latitude":-15.66667,"longitude":31.83333,"description":"The Cahora Bassa lake—in the Portuguese colonial era known as Cabora Bassa, from Nyungwe Kahoura-Bassa, meaning \"finish the job\"—is Africa's fourth-largest artificial lake, situated in the Tete Province in Mozambique. In Africa, only Lake Volta in Ghana, Lake Kariba on the Zambezi upstream of Cahora Bassa, and Egypt's Lake Nasser are bigger in terms of surface water."},{"name":"Kainji Lake","slug":"kainji-lake","category":"Lake","country":"Nigeria","region":"Niger State","city":null,"latitude":10.40611,"longitude":4.56444,"description":"Kainji Lake, in North Central Nigeria, is a reservoir on the Niger River, formed by the Kainji Dam. It was formed in 1968 and is a part of Niger State and Kebbi State. Kainji Lake National Park (KNLP), situated around the lake, is Nigeria's oldest National Park, established in 1976."},{"name":"Sebkha d'Oran","slug":"sebkha-doran","category":"Lake","country":"Algeria","region":null,"city":null,"latitude":35.5333,"longitude":-0.8,"description":"The Sebkha of Oran is a salt lake located within the territory of the municipality of Misserghin, in the province of Oran, Algeria."},{"name":"Lake Manzala","slug":"lake-manzala","category":"Lake","country":"Egypt","region":null,"city":null,"latitude":31.291,"longitude":32.018,"description":"Lake Manzala, also Manzaleh, is a brackish lake, sometimes called a lagoon, in northeastern Egypt on the Nile Delta near Port Said and a few miles from the ancient ruins at Tanis. It is the largest of the northern deltaic lakes of Egypt. As of 2008 it is 47 km (29 mi) long and 30 km (19 mi) wide."},{"name":"Lake Manantali","slug":"lake-manantali","category":"Lake","country":"Mali","region":null,"city":null,"latitude":13.158,"longitude":-10.344,"description":"Lake Manantali is a large artificial lake, formed by the 1989 construction of the Manantali Dam, on the Bafing River in Mali. Its northern point is located 90 km to the south-east of the city of Bafoulabé."},{"name":"Lake Buyo","slug":"lake-buyo","category":"Lake","country":"Ivory Coast","region":null,"city":null,"latitude":6.3,"longitude":-7.1,"description":"Lake Buyo is an artificial lake in western Ivory Coast on the Sassandra River. It was formed by the construction of the Buyo Dam at Buyo in 1980."},{"name":"Lake Zway","slug":"lake-zway","category":"Lake","country":"Ethiopia","region":null,"city":null,"latitude":8.0,"longitude":38.83,"description":"Lake Batu, also known as Hora-Dambal or Dambal is one of the freshwater Rift Valley lakes of Ethiopia. Located about 100 miles south of Addis Ababa, on the border between the Oromia and Southern Nations, Nationalities, and Peoples' Region, the woredas holding the lake's shoreline are Adami Tullu-Jido Kombolcha, Dugda, and Batu town. The town of Batu lies on the lake's western shore."},{"name":"Lake Elmenteita","slug":"lake-elmenteita","category":"Lake","country":"Kenya","region":"Nakuru County","city":null,"latitude":-0.446,"longitude":36.244,"description":"Lake Elmenteita is a soda lake, in the Great Rift Valley, about 120 km northwest of Nairobi, Kenya."},{"name":"Great Bitter Lake","slug":"great-bitter-lake","category":"Lake","country":"Egypt","region":null,"city":null,"latitude":30.3225,"longitude":32.3825,"description":"A lake in Egypt, documented on Wikipedia. Check local guides for access, boat hire and the best season before you visit."},{"name":"Praia do Xai-Xai","slug":"praia-do-xai-xai","category":"Beach","country":"Mozambique","region":null,"city":null,"latitude":-25.124,"longitude":33.733,"description":"Praia do Xai-Xai is a beach which is a tourist destination in Mozambique. Located approximately 10 kilometers from Xai-Xai, the seat of Mozambique's Gaza Province, the beach attracts visitors who are interested in exploring the massive coral reef that runs parallel to the shoreline."},{"name":"Praia de Cabral","slug":"praia-de-cabral","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.185,"longitude":-22.918,"description":"Praia de Cabral is a beach on the northwest coast of the island of Boa Vista in Cape Verde in the immediate area of the town of Sal Rei. Nearby in Praia de Fátima is an abandoned chapel of Our Lady of Fatima."},{"name":"Chocas Mar","slug":"chocas-mar","category":"Beach","country":"Mozambique","region":null,"city":null,"latitude":-14.9361,"longitude":40.73825,"description":"Chocas Mar is a long pristine beach in Nampula Province in Mozambique. It is about 40km north of the Island of Mozambique across the Mossuril Bay. Chocas Mar is accessible either by unpaved road or boat."},{"name":"Boulders Beach","slug":"boulders-beach","category":"Beach","country":"South Africa","region":"City of Cape Town","city":null,"latitude":-34.197,"longitude":18.451,"description":"Boulders Beach is a sheltered beach made up of inlets between granite boulders, from which the name originated. It is located on the eastern side of the Cape Peninsula, in Simon's Town, in the southern region of Cape Town, South Africa. It is also commonly known as Boulders Bay."},{"name":"Anse Lazio","slug":"anse-lazio","category":"Beach","country":"Seychelles","region":"Praslin","city":null,"latitude":-4.29361,"longitude":55.70167,"description":"Anse Lazio is a beach situated in the northwest of Praslin Island, Seychelles, considered by Lonely Planet to be the \"best beach on Praslin\", and one of the \"best in the archipelago\"."},{"name":"Diani Beach","slug":"diani-beach","category":"Beach","country":"Kenya","region":"Kwale County","city":null,"latitude":-4.32222,"longitude":39.575,"description":"Diani Beach is a beach on the Indian Ocean coast of Kenya. It is located 30 kilometres (19 mi) south of Mombasa, in Kwale County."},{"name":"Flamengos, Cape Verde","slug":"flamengos-cape-verde","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.807,"longitude":-25.045,"description":"Praia dos Flamengos is a beach in the southwest of the island of São Vicente in Cape Verde. It is 2.5 km southeast of the village São Pedro and 11 km southwest of Mindelo. It is accessible from the northeast by a dirt road."},{"name":"Glen Beach","slug":"glen-beach","category":"Beach","country":"South Africa","region":"Western Cape","city":null,"latitude":-33.9469,"longitude":18.3781,"description":"Glen Beach is located north of Camps Bay Beach in Cape Town, South Africa. The two beaches are divided by a rock outcrop that extends from the land to the shore-line. During the summer months, sand deposits tend to build up at the shore-line, widening both Glen and Camps Bay beaches until the two beaches merge—until winter, when the sand deposits are eroded by winter storms."},{"name":"Gezira Beach","slug":"gezira-beach","category":"Beach","country":"Somalia","region":"Banaadir","city":null,"latitude":1.94396,"longitude":45.16684,"description":"Jazeera Beach is a beach which overlooks the Somali Sea near the city of Mogadishu, the capital of Somalia."},{"name":"Cape Indienne, Congo","slug":"cape-indienne-congo","category":"Beach","country":"Republic of the Congo","region":"Kouilou Department","city":null,"latitude":-4.66139,"longitude":11.78333,"description":"Pointe Indienne is a cape north of Pointe Noire in the Republic of the Congo. It is also the name of the beach close to it."},{"name":"Bar Beach, Lagos","slug":"bar-beach-lagos","category":"Beach","country":"Nigeria","region":"Lagos","city":null,"latitude":6.422,"longitude":3.4334,"description":"Bar Beach was a beach on the Atlantic Ocean along the shoreline of Lagos, situated on Victoria Island. For a time, it was the most popular beach in Nigeria especially when Lagos was the capital of the country. The beach served as a venue for social activities like family outing, picnics and for some even spiritual gatherings."},{"name":"Kuramo Beach","slug":"kuramo-beach","category":"Beach","country":"Nigeria","region":"Lagos State","city":null,"latitude":6.422,"longitude":3.4334,"description":"Kuramo Beach is a sandy beach in Lagos, Nigeria, located at the south side of Victoria Island, just east of Bar Beach and south of the Kuramo Waters lagoon. It was the location of numerous illegal shanties and cabins, some of them being used for music entertainment, bars and prostitution. In August 2012, a surge of the Atlantic Ocean hit Kuramo Beach, destroying some of these shacks and killing 16 people."},{"name":"La Femme","slug":"la-femme","category":"Beach","country":"Egypt","region":null,"city":null,"latitude":30.83735,"longitude":28.99019,"description":"La Femme is a women-only beach in Marina, Egypt that mainly caters to Muslims who want to swim in comfort away from men and cameras. La femme started in 2005. It is owned by Mohamed el Saadany, it was decorated by Lamia Yehia, and it's managed by Camilia el Saadany."},{"name":"La Preneuse","slug":"la-preneuse","category":"Beach","country":"Mauritius","region":null,"city":null,"latitude":-20.354,"longitude":57.366,"description":"La Preneuse is a public beach in western coast of the island Mauritius in the district of Rivière Noire located in the village of Black River. It was named after a French ship, the frigate Preneuse, which served as a commerce raider at Isle de France and was also involved in a naval battle with the British in the 18th century. The beach is home to the best preserved Martello tower in Mauritius."},{"name":"Labadi Beach","slug":"labadi-beach","category":"Beach","country":"Ghana","region":"Greater Accra Region","city":null,"latitude":5.56242,"longitude":-0.13943,"description":"Labadi Beach or more properly known as La Pleasure Beach is the busiest beach on Ghana's coast. It is one of Accra's beaches and is maintained by the local hotels. Labadi Beach is in a town called La, popularly known as Labadi, near Teshie in the Greater Accra Region of Ghana. An entrance fee to those not staying in the hotels is charged."},{"name":"Miller's Point","slug":"millers-point","category":"Beach","country":"South Africa","region":"City of Cape Town","city":null,"latitude":-34.231,"longitude":18.474,"description":"Miller's Point is a headland and stretch of protected coastline in South Africa. It is located about 4 kilometres (2.5 mi) south of Simon's Town on the road to Cape Point."},{"name":"North Beach","slug":"north-beach","category":"Beach","country":"South Africa","region":"Durban","city":null,"latitude":-29.84878,"longitude":31.0386,"description":"North Beach is one of the beaches of Durban, South Africa. It is situated north of the harbour and bluff, in between Bay of Plenty and Dairy Beach on Durban's Golden Mile."},{"name":"Ponta Preta","slug":"ponta-preta","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.6057,"longitude":-22.9297,"description":"Ponta Preta is a headland in the southwest of the island of Sal in Cape Verde. It is about 2 km west of the town Santa Maria and about 2 km of Ponta do Sinó, the southernmost point of the island. It lies within the nature reserve Ponta do Sinó, at the edge of a tourism development zone."},{"name":"Praia Grande","slug":"praia-grande","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.86667,"longitude":-24.9,"description":"Praia Grande is a large beach on the northeast coast of the island of São Vicente, Cape Verde. It is 1.5 km northwest of the village Calhau. The white sandy beach is surrounded by volcanic rocks. It is accessible by road from Calhau and Baía das Gatas."},{"name":"Praia da Chave","slug":"praia-da-chave","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.1,"longitude":-22.91667,"description":"Praia de Chaves is a beach in the western part of the island of Boa Vista in Cape Verde, close to the town Rabil. It is about 5 km long."},{"name":"Praia da Varandinha","slug":"praia-da-varandinha","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.0432,"longitude":-22.964,"description":"Praia da Varandinha is a beach on the southwest coast of the island of Boa Vista in Cape Verde. It lies north of the headland Ponta Varandinha. The beach forms part of the protected area Morro de Areia Nature Reserve."},{"name":"Praia das Gatas","slug":"praia-das-gatas","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":16.181,"longitude":-22.707,"description":"Praia das Gatas is a sandy beach in the northeastern part of the island of Boa Vista in Cape Verde. The nearest village is Fundo das Figueiras, 5 km to the southwest. It forms a part of Northern Nature Park. The small island Ilhéu dos Pássaros lies off the coast at the Praia das Gatas."},{"name":"Ibeno Beach","slug":"ibeno-beach","category":"Beach","country":"Nigeria","region":"Ibeno","city":null,"latitude":4.54062,"longitude":8.00311,"description":"The Ibeno Beach is one of the beaches on the Atlantic Ocean along the shorelines of Ibeno in Akwa Ibom State, Nigeria. It is the longest sand beach in West Africa Qua Iboe River estuary is the major estuary in Ibeno Beach. Ibeno Beach stretches for about 30 kilometres from Ibeno to James Town along the Atlantic coastline of Akwa Ibom State in Nigeria. It is the best tourist site in Akwa Ibom State."},{"name":"Zaranha","slug":"zaranha","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":17.176,"longitude":-25.149,"description":"Praia d'Aranhas is a beach on the northern coast of the island of Santo Antão in Cape Verde and is part of the municipality of Ribeira Grande and the village of Fontainhas. It lies east of the village of Cruzinha close to its limits and west of Ponta do Sol."},{"name":"Cabo de Santa Maria","slug":"cabo-de-santa-maria","category":"Beach","country":"Cape Verde","region":"Boa Vista","city":null,"latitude":16.202,"longitude":-22.865,"description":"Praia de Atalanta is a beach on the north coast of the island of Boa Vista in Cape Verde. It is approximately 6 km northeast of the island capital of Sal Rei and 3 km west of Vigía. The wreck of the Spanish cargo ship Cabo Santa Maria, which ran aground on September 1, 1968, is located here."},{"name":"Elegushi Beach","slug":"elegushi-beach","category":"Beach","country":"Nigeria","region":"Lagos State","city":null,"latitude":6.42206,"longitude":3.48661,"description":"Elegushi Beach is a private beach located at Lekki, Lagos state, southwest Nigeria. The beach is owned by the Elegushi royal family in Lekki, Lagos state. Elegushi private beach is seen as one of the best beaches in Lagos and Nigeria at large. The beach entertains close to 40,000 guests every week with Sundays being the best day on the beach."},{"name":"Eleko Beach","slug":"eleko-beach","category":"Beach","country":"Nigeria","region":"Lagos State","city":null,"latitude":6.4391,"longitude":3.85419,"description":"Eleko Beach is a private beach in the Lekki peninsula, about 30 mi (48 km) east of Lagos Island in Nigeria. It opened in 1989. Eleko Beach is located in the Ibeju-lekki local Government area. Eleko is a small community located along the Lagos coastline. Eleko Beach stands out among the community's other natural blessings."},{"name":"Lido Beach, Mogadishu","slug":"lido-beach-mogadishu","category":"Beach","country":"Somalia","region":"Mogadishu","city":null,"latitude":2.03975,"longitude":45.36372,"description":"Lido Beach is a beach in Somalia's capital, Mogadishu, which overlooks the Somali Sea. It derives its name from the Italian word for \"beach\". Commonly, the name Liido is colloquially used by locals."},{"name":"Tofinho","slug":"tofinho","category":"Beach","country":"Mozambique","region":null,"city":null,"latitude":-23.86194,"longitude":35.55167,"description":"Tofinho Beach or simply Tofinho is a tourist Beach, Monument and Residential area in southeastern Mozambique. This holiday settlement lies on the Indian Ocean coast, on the Ponta da Barra peninsula in Inhambane Province, 1.5km south of Tofo, 25km Northeast of Inhambane in Mozambique."},{"name":"Port Harcourt Tourist Beach","slug":"port-harcourt-tourist-beach","category":"Beach","country":"Nigeria","region":"Port Harcourt","city":null,"latitude":4.75936,"longitude":7.0122,"description":"The Port Harcourt Tourist Beach is a white sand urban beach in Port Harcourt, Rivers State, Nigeria, created in 1988. It is located along Kolabi Creek, east of the Old Township district, and about 235 kilometres from Kribi in Cameroon."},{"name":"Praia da Barra","slug":"praia-da-barra","category":"Beach","country":"Mozambique","region":"Inhambane Province","city":null,"latitude":-23.79306,"longitude":35.51806,"description":"Barra Beach or simply Barra is a tourist beach in southeastern Mozambique. This holiday settlement lies on the Indian Ocean coast, on the Ponta da Barra peninsula in Inhambane Province, 25 km drive from Inhambane city. A major Mozambican tourist destination, Barra is home to beach resorts, private vacation homes, restaurants and diving charters."},{"name":"Nyali Beach","slug":"nyali-beach","category":"Beach","country":"Kenya","region":null,"city":null,"latitude":-4.04868,"longitude":39.70948,"description":"Nyali is a residential area and Sub-County within Mombasa City, located on the mainland north of Mombasa County. It is connected to Mombasa Island by the New Nyali Bridge. Nyali is known for its many high-class hotels and residential houses, modern standards, and long white sand beaches making it a popular destination for both local and foreign tourists."},{"name":"Manaba Beach","slug":"manaba-beach","category":"Beach","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-30.85444,"longitude":30.38389,"description":"Manaba Beach is a small coastal town on the South Coast of the KwaZulu-Natal province of South Africa, located approximately 2 kilometres (1.2 mi) north of the Margate CBD and 13 kilometres (8.1 mi) south of Port Shepstone. The name ‘Manaba’ translates to 'ease and relaxation' in the Zulu language."},{"name":"Praia de Carquejinha","slug":"praia-de-carquejinha","category":"Beach","country":"Cape Verde","region":null,"city":null,"latitude":15.976,"longitude":-22.855,"description":"Praia de Carquejinha is a beach on the south coast of the island of Boa Vista in Cape Verde Neighboring beaches are Praia de Santa Mónica to the west and Praia de Curral Velho to the east. The beach is about 8 km long."},{"name":"Santa Maria Beach","slug":"santa-maria-beach","category":"Beach","country":"Cape Verde","region":"Sal","city":null,"latitude":16.5914,"longitude":-22.9147,"description":"Praia de Santa Maria is a beach on the south coast of the island of Sal, Cape Verde. It stretches from the city center of Santa Maria in the east to the Ponta do Sinó in the southwest. It is about 2 km long. Along with Praia da Ponta Preta, it is the most popular beach on the city and island."},{"name":"Anse Georgette","slug":"anse-georgette","category":"Beach","country":"Seychelles","region":null,"city":null,"latitude":-4.2949,"longitude":55.681,"description":"Anse Georgette is a beach situated in the northwestern coast of Praslin, Seychelles. It is ranked among the top 10 best beaches in the world for 2024."},{"name":"Landmark Leisure Beach","slug":"landmark-leisure-beach","category":"Beach","country":"Nigeria","region":"Lagos","city":null,"latitude":6.42256,"longitude":3.44565,"description":"Landmark Leisure Beach is a beach that is located in Lagos, Lagos State Nigeria. It is at numbers 3 & 4 Water Corporation Road, VI, Lagos. The beach is open to the public every day. It employed paid lifeguards who watch over the beach and have rescued many people from drowning."},{"name":"Okpoama Beach, Bayelsa","slug":"okpoama-beach-bayelsa","category":"Beach","country":"Nigeria","region":"Bayelsa State","city":null,"latitude":4.29301,"longitude":6.28912,"description":"Okpoama beach is a beach located in Brass Local Government Area of Bayelsa State, Nigeria. The beach is often considered a recreation center for people within and outside Bayelsa State and it occupies a 23 km space."},{"name":"Suntan Beach","slug":"suntan-beach","category":"Beach","country":"Nigeria","region":null,"city":null,"latitude":6.39194,"longitude":2.83333,"description":"Suntan Beach in Badagry, Lagos State, is a quiet coastal spot lined with coconut trees and soft sand, offering a relaxed atmosphere away from the busy city. It's a place where people come to enjoy the ocean breeze, take walks along the shore, or simply unwind. The beach is popular for casual outings, with visitors playing beach games, riding horses, or just sitting by the water."},{"name":"Point of Sangomar","slug":"point-of-sangomar","category":"Beach","country":"Senegal","region":"Dionewar","city":null,"latitude":13.82389,"longitude":-16.75722,"description":"The Point of Sangomar is a sand spit located on the Atlantic Ocean at the mouth of the Saloum Delta, which marks the end of the Petite Côte west of Senegal."},{"name":"Anse source d´argent","slug":"anse-source-d-argent","category":"Beach","country":"Seychelles","region":"La Digue and Inner Islands","city":null,"latitude":-4.37157,"longitude":55.82722,"description":"Anse Source d'Argent is a beach situated in the southwest coast of La Digue, Seychelles. It is listed in Lonely Planet as one of the world's best beaches in 2024."},{"name":"Beaches in Lomé","slug":"beaches-in-lom","category":"Beach","country":"Togo","region":null,"city":null,"latitude":6.12714,"longitude":1.23664,"description":"The beaches of Lomé form the sandy coastline of Lomé, the capital of Togo, on the Gulf of Guinea. East of the port, the coast continues towards Baguida, Kpémé and Aného. The beaches serve as a recreational area, a base for small-scale fishing and a historic site."},{"name":"Praia do Sarico","slug":"praia-do-sarico","category":"Beach","country":"Angola","region":null,"city":null,"latitude":-8.63506,"longitude":13.41079,"description":"Praia do Sarico, Angola, was known until 2023 as Cemitério Dos Navios or Shipwreck Beach. In 2020, the Angolan government ordered the demolition of most of the wrecks, and since 2025 only the keels of the ships have been visible underwater."},{"name":"Ilha de Luanda","slug":"ilha-de-luanda","category":"Beach","country":"Angola","region":"Luanda","city":null,"latitude":-8.77855,"longitude":13.24367,"description":"Ilha do Cabo typically known as Ilha de Luanda is a spit off the shore of Luanda, the capital of Angola, a country on the continents' southwestern coast. It consists of a low sandy strip formed by sedimentation. In administrative terms, the peninsula belongs to the municipality of Ingombota in the Luanda Province."},{"name":"Sandy Bay","slug":"sandy-bay","category":"Beach","country":"South Africa","region":"Western Cape","city":null,"latitude":-34.0233,"longitude":18.3308,"description":"Sandy Bay is a beach just south of Llandudno. It is on the west side of the Karbonkelberg, and cannot be seen from the main road to Hout Bay, which turns inland above Llandudno."},{"name":"Sanda Kyarimi Park Zoo","slug":"sanda-kyarimi-park-zoo","category":"Forest","country":"Nigeria","region":"Borno State","city":null,"latitude":11.83235,"longitude":13.14736,"description":"The Sanda Kyarimi Park Zoo is a 17-hectare (200,000 yd2) zoological garden and wildlife sanctuary located in Maiduguri, Borno State, Nigeria. It is one of the oldest zoological gardens in Nigeria, established in 1970. It is considered the only public facility in Borno for the conservation of endangered animal species."},{"name":"Echuya Central Forest Reserve","slug":"echuya-central-forest-reserve","category":"Forest","country":"Uganda","region":"Western Region","city":null,"latitude":-1.3,"longitude":29.83333,"description":"The Echuya Central Forest Reserve is a forest reserve in Uganda. This typical tropical rainforest covers approximately 34 km2 and is located at the intersection of Kisoro and Rubanda districts. It is one of the few remaining tropical rain forests in Uganda."},{"name":"Kalinzu Central Forest Reserve","slug":"kalinzu-central-forest-reserve","category":"Forest","country":"Uganda","region":"Bushenyi District","city":null,"latitude":-0.28333,"longitude":30.11667,"description":"Kalinzu Central Forest Reserve is a protected area located in Bushenyi district in south-western Uganda. Covering an area of 137 square kilometers, the reserve is characterized by its diverse ecosystem consisting of dense tropical rainforest vegetation and a wide range of wildlife."},{"name":"Mount Otzi Central Forest Reserve","slug":"mount-otzi-central-forest-reserve","category":"Forest","country":"Uganda","region":"Moyo District","city":null,"latitude":3.685,"longitude":31.90333,"description":"Mount Otzi Central Forest Reserve is a 188 square kilometer forest reserve located in Moyo District, West Nile Region, Uganda. It is situated on an escarpment that overlooks the confluence of River Achwa and the White Nile as it flows into South Sudan. The reserve is bordered on the North by the International border of South Sudan and to the South by the Moyo-Adjumani District border."},{"name":"Gibi National Forest","slug":"gibi-national-forest","category":"Forest","country":"Liberia","region":null,"city":null,"latitude":6.31292,"longitude":-8.83691,"description":"The Gibi National Forest is found in Liberia. It was established in 1960. This site is 607 km2."},{"name":"Echuya Forest reserve","slug":"echuya-forest-reserve","category":"Forest","country":"Uganda","region":null,"city":null,"latitude":-1.22167,"longitude":29.62,"description":"A forest in Uganda, documented on Wikipedia. Check local guides for trails, opening times and permits before you visit."},{"name":"Kagombe Central Forest Reserve","slug":"kagombe-central-forest-reserve","category":"Forest","country":"Uganda","region":"Kibaale District","city":null,"latitude":0.84148,"longitude":30.66746,"description":"Kagombe Central Forest Reserve is a 301-square-kilometre (74,000-acre) forest reserve located in Western Uganda's district of Kagadi and Nyamarundu sub county. It is also located in Uganda's Albertine Rift ecoregion area renowned for its rich biodiversity."},{"name":"Bujawe Central Forest Reserve","slug":"bujawe-central-forest-reserve","category":"Forest","country":"Uganda","region":"Hoima District","city":null,"latitude":1.53174,"longitude":31.19728,"description":"Bujawe Central Forest Reserve is a protected tropical forest that is located in Hoima district of western Uganda. The forest covers an area of 50 km2. Bujawe has one named mountain called Buhirigi which has the highest peak and is the most prominent mountain in Uganda with 1130m/3707 ft a.s.l. and the prominence is 60m/197 ft. The size of the forest is 31km2."},{"name":"North Rwenzori Central Forest Reserve","slug":"north-rwenzori-central-forest-reserve","category":"Forest","country":"Uganda","region":"Bundibugyo District","city":null,"latitude":0.81,"longitude":30.213,"description":"North Rwenzori Central Forest Reserve is a protected tropical forest situated between Bundibugyo District and Ntoroko District in Western Uganda. This Natural Forest Reserve is at the foothills of the Rwenzori Mountains east of the Democratic Republic of Congo."},{"name":"Matiri Central Forest Reserve","slug":"matiri-central-forest-reserve","category":"Forest","country":"Uganda","region":"Kyenjojo District","city":null,"latitude":3.21063,"longitude":31.19728,"description":"Matiri Central Forest Reserve is a protected tropical forest reserve that is located in Kyenjojo district of western Uganda. The central forest covers an area of 64 square kilometres (25 sq mi) and is among the few surviving natural forest reserves in the Tooro region."},{"name":"Rwengiri Central Forest Reserve","slug":"rwengiri-central-forest-reserve","category":"Forest","country":"Uganda","region":"Rukungiri District","city":null,"latitude":-0.6658,"longitude":29.8703,"description":"Rwengiri Central Forest Reserve is a protected tropical forest that is located in Rukungiri district in Western Uganda. It covers an area of 155 km2. It managed by the National Forestry Authority. Its WPDA ID is 40357. It was designated a reserve in 1968."},{"name":"Rwengeye Central Forest Reserve","slug":"rwengeye-central-forest-reserve","category":"Forest","country":"Uganda","region":"Kibaale District","city":null,"latitude":1.1032,"longitude":31.0069,"description":"Rwengeye Central Forest Reserve is a protected tropical high forest in the Kiryanga and Pacwa subcounties in Kibaale District in Western Uganda. It covers an area of 329 hectares. It is operated by the National Forestry Authority (NFA). Its WDPA ID is 39999. It was declared a forest reserve in 1932."},{"name":"Nyamakere Central Forest Reserve","slug":"nyamakere-central-forest-reserve","category":"Forest","country":"Uganda","region":"Kiryandongo District","city":null,"latitude":2.00833,"longitude":32.24389,"description":"Nyamakere Central Forest Reserve is a protected area located in the Kiryandongo District of Uganda. It is one of the many Central Forest Reserves managed by the National Forestry Authority (NFA) of Uganda. Nyamakere Central Forest Reserve covers an extensive stretch of over 3.4 kilometers."},{"name":"Nyabyeya Central Forest Reserve","slug":"nyabyeya-central-forest-reserve","category":"Forest","country":"Uganda","region":"Masindi District","city":null,"latitude":1.68472,"longitude":31.52194,"description":"Nyabyeya Central Forest Reserve is a forest reserve located in Masindi District, Western Uganda, Bujenje County, Budongo sub-county, and Nyabyeya parish in western Uganda. It is part of the extensive network of Central Forest Reserves managed by the National Forestry Authority (NFA) in Uganda. This forest reserve covers an area of about 358.06 hectares."},{"name":"Kasenyi Central Forest Reserve","slug":"kasenyi-central-forest-reserve","category":"Forest","country":"Uganda","region":"Mubende District","city":null,"latitude":0.5579,"longitude":31.4157,"description":"Kasenyi Central Forest Reserve is a protected high forest located in Buwekula county in Mubende District in Central Region of Uganda. It was designated a forest reserve in 1968 and it covers an area of 1.99 km2. Its World Database on Protected Areas (WDPA) ID is 40141. It is under the management of National Forestry Authority."},{"name":"Arua Central Forest Reserve","slug":"arua-central-forest-reserve","category":"Forest","country":"Uganda","region":"Arua","city":null,"latitude":3.009,"longitude":30.924,"description":"Arua Central Forest Reserve, also known as Barifa Forest is a protected area in Arua district, Uganda. It is managed by National Forestry Authority (NFA). The reserve is constantly under threat from depletion and encroachers who are a threat the existence of tree species in this forest reserve. The forest was gazetted in 1932 with a land coverage of 236 hectares."},{"name":"Gio National Forest","slug":"gio-national-forest","category":"Forest","country":"Liberia","region":null,"city":null,"latitude":6.66667,"longitude":-8.66667,"description":"The Gio National Forest is a forest area situated in central Nimba County, Liberia. It was established in 1960 and covers an area of about 327 km2."},{"name":"Hlatikhulu Forest","slug":"hlatikhulu-forest","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-27.34139,"longitude":32.00028,"description":"Hlathikulu Forest is a coastal scarp forest in the Lebombo Mountains of South Africa, between Ingwavuma and the Pongola Gorge. The forest is also known as the Gwaliweni Forest. The forest is part of the IUCN's Maputaland Centre of Plant Endemism"},{"name":"Bugamba Central Forest Reserve","slug":"bugamba-central-forest-reserve","category":"Forest","country":"Uganda","region":"Rwampara district","city":null,"latitude":-0.7325,"longitude":30.51611,"description":"Bugamba Central Forest reserve is a natural forest located in the Rwampara district, in southwestern Uganda. It has been referred to as an intensive soil conservation zone. The Reserve is one of the few softwood plantations where spacing is practiced."},{"name":"Nakindiba Central Forest Reserve","slug":"nakindiba-central-forest-reserve","category":"Forest","country":"Uganda","region":"Wakiso District","city":null,"latitude":0.442,"longitude":32.394,"description":"Nakindiba Central Forest Reserve, a protect area located in Wakiso district, is a 142 hectares forest reserve with a boundary length of 7.2 kilometers. It is situated in Central Uganda and is protected by the National Forestry Authority under National Forest and Tree Planting Act."},{"name":"Olokemeji Forest Reserve","slug":"olokemeji-forest-reserve","category":"Forest","country":"Nigeria","region":null,"city":null,"latitude":7.25,"longitude":3.33,"description":"Olokemeji Forest Reserve is Nigeria's first Forest Reserve, established around 1900. The reserve covers about 5,900 hectares and is located between the Nigerian cities of Abeokuta and Ibadan. While the reserve does contain freshwater swamp forest areas, particularly in the south, its primary composition is characterized by moist evergreen forest, often referred to as 'mixed rainforest'"},{"name":"Busitema Forest","slug":"busitema-forest","category":"Forest","country":"Uganda","region":"Tororo District","city":null,"latitude":0.5375,"longitude":33.9925,"description":"Busitema Forest Reserve is forest reserve located in eastern Uganda, covering parts of the Busia, Tororo, and Bugiri districts. The forest can be accessed via the Tororo-Busia road, near Busitema University which makes it easy for visitors to reach this natural attraction. It spans approximately 25 square kilometers, providing a haven a diverse ecosystem."},{"name":"Zirimiti Forest Reserve","slug":"zirimiti-forest-reserve","category":"Forest","country":"Uganda","region":"Mukono District","city":null,"latitude":0.23649,"longitude":32.76464,"description":"Zirimiti Forest Reserve is a forest reserve in Mukono District, Central Uganda. It encompasses an area with an elevation of around 1,163 meters. It is positioned close to the localities of Kitenda and Kipayo, making it an important ecological and community area in the region. The reserve is along the shores of Lake Victoria."},{"name":"Kibale Forest National Park","slug":"kibale-forest-national-park","category":"Forest","country":"Uganda","region":"Kibaale District","city":null,"latitude":0.4364,"longitude":30.3667,"description":"Kibale Forest National Park is a protected area in South Western Uganda. It is managed by a cluster of government agencies that include: Uganda Wildlife Authority (UWA) Ministry of Water and Environment (MWE), National Forest Authority (NFA), National Environment Management Authority and Ministry of Tourism, Wildlife & Antiquities."},{"name":"Karura Forest","slug":"karura-forest","category":"Forest","country":"Kenya","region":"Nairobi","city":null,"latitude":-1.24028,"longitude":36.82361,"description":"Karura Forest is an urban forest in Nairobi, the capital of Kenya. It is the second largest urban forest in the world after the Tijuca Forest in Rio de Janeiro located in Brazil. The forest was gazetted in 1932 and is managed by the Kenya Forest Service in conjunction with the Friends of Karura Forest Community Forest Association."},{"name":"Kpelle National Forest","slug":"kpelle-national-forest","category":"Forest","country":"Liberia","region":"Gbarpolu County","city":null,"latitude":7.50139,"longitude":-10.25139,"description":"The Kpelle National Forest is found in Liberia. It was established in 1961. This site is 1748 km2."},{"name":"Achimota Forest","slug":"achimota-forest","category":"Forest","country":"Ghana","region":"Greater Accra Region","city":null,"latitude":5.6247,"longitude":-0.2037,"description":"Achimota Forest Reserve is a forest in Achimota in the Okaikwei North Municipality in the Greater Accra Region. It is located approximately 7.6 km (4.7 mi) from Accra. It is under protection against unauthorized usage such as poaching, construction of homes, hunting and shopping malls by individuals and groups. It is one of the green facilities in Accra assisting with control of carbon emissions."},{"name":"Gishwati Forest","slug":"gishwati-forest","category":"Forest","country":"Rwanda","region":null,"city":null,"latitude":-1.79079,"longitude":29.45424,"description":"Gishwati Forest is a forest in the north-western part of Rwanda, not far from Lake Kivu. It is part of Gishwati–Mukura National Park. The area's forests were largely intact in 1978, and substantial forest cover still remained in 1986. During the Rwandan genocide, wave after wave of refugees arrived in Gishwati Forest and began clearing it, often for subsistence farming."},{"name":"Maramagambo Forest","slug":"maramagambo-forest","category":"Forest","country":"Uganda","region":"Bushenyi District","city":null,"latitude":-0.55,"longitude":29.88333,"description":"Maramagambo Forest is located in Bushenyi district in south western region of Uganda. It adjoins the Queen Elizabeth National Park to the north. It is jointly managed by the Uganda Wildlife Authority and the National Forestry Authority."},{"name":"Marutswa forest","slug":"marutswa-forest","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-29.80775,"longitude":29.78422,"description":"Marutswa Forest is an indigenous mist-belt forest near Bulwer in the Midlands of KwaZulu-Natal region of South Africa."},{"name":"Mikea Forest","slug":"mikea-forest","category":"Forest","country":"Madagascar","region":"Atsimo-Andrefana","city":null,"latitude":-22.6,"longitude":43.4,"description":"The Mikea Forest is a forested region of southwestern Madagascar, between Manombo and Morombe, inhabited by the hunter-gatherer Mikea people. More specifically, it stretches from Route Nationale 9 to the west coast and from Mangoky south to the Manombo River."},{"name":"Newlands Forest","slug":"newlands-forest","category":"Forest","country":"South Africa","region":"Western Cape","city":null,"latitude":-33.97083,"longitude":18.44167,"description":"Newlands Forest is a conservancy area on the eastern slopes of Table Mountain, beside the suburb of Newlands, Cape Town, South Africa. It is owned and maintained by the Table Mountain National Parks Board, along with the City Parks Department of Cape Town, and includes a Fire Station, Nursery and Reservoir."},{"name":"Ngome Forest Reserve","slug":"ngome-forest-reserve","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-27.83333,"longitude":31.41667,"description":"Ngome Forest is situated to the east of Vryheid, KwaZulu-Natal, South Africa. This is a unique forest, being transitional between Mistbelt Forest and Coastal Scarp Forest. The area has been protected since 1905, and forms part of the Ntendeka Wilderness Area."},{"name":"Nimba National Forest","slug":"nimba-national-forest","category":"Forest","country":"Liberia","region":null,"city":null,"latitude":7.5,"longitude":-8.5,"description":"Nimba National Forest is a national forest in Nimba County, Liberia. The forest, which borders Guinea and Ivory Coast, has eastern and western sections that cover 96 km2 (37 sq mi) and 91 km2 (35 sq mi) respectively. It is also known as the Mount Nimba Forest Reserves."},{"name":"Okeluse Forest Reserve","slug":"okeluse-forest-reserve","category":"Forest","country":"Nigeria","region":"Ondo State","city":null,"latitude":6.78768,"longitude":5.58686,"description":"The Okeluse Forest Reserve is situated in Okeluse, an agrarian community in Ose Local Government Area of Ondo State, South West, Nigeria, West Africa. It covers 144 square kilometres (56 sq mi). It is a major forest reserve in Nigeria"},{"name":"Oluwa Forest Reserve","slug":"oluwa-forest-reserve","category":"Forest","country":"Nigeria","region":"Ondo State","city":null,"latitude":6.823,"longitude":4.674,"description":"Oluwa Forest Reserve is located in Ondo State, Nigeria and covers over 829 km2 (320 sq mi). It is part of the Omo, Shasha and Oluwa forest reserves, although it has become separated from the Omo and Shasha reserves. The three reserves contain some of the last remaining forest in the area. Although they are biologically unique, they are threatened by logging, hunting and agriculture."},{"name":"Harenna Forest","slug":"harenna-forest","category":"Forest","country":"Ethiopia","region":"Bale Zone","city":null,"latitude":6.51345,"longitude":39.24716,"description":"The Harenna Forest is a montane tropical evergreen forest in Ethiopia's Bale Mountains. The forest covers the southern slope of the mountains, extending from 1450 to 3200 meters elevation. The Bale Mountains are in Ethiopia's Oromia Region, and form the southwestern portion of the Ethiopian Highlands."},{"name":"Mare aux Hippopotames","slug":"mare-aux-hippopotames","category":"Forest","country":"Burkina Faso","region":"Houet Province","city":null,"latitude":11.6167,"longitude":-4.1333,"description":"The Mare aux Hippopotames is a lake and national park in Burkina Faso, created in 1937 and designated in 1977 as the only UNESCO Biosphere Reserve in the nation. The park was created around a freshwater lake and includes surrounding pools and marches in the flood plain of the Black Volta River, and surrounding forests. The park is home to about 100 hippos; about 1000 eco-tourists visit each year."},{"name":"Nialama (Nyalama) Classified Forest","slug":"nialama-nyalama-classified-forest","category":"Forest","country":"Guinea","region":"Linsansaran","city":null,"latitude":11.57583,"longitude":-12.77444,"description":"Nialama Classified Forest, also spelled Nyalama, is found in the Fouta Djalon highland region of north-west Guinea."},{"name":"Anjajavy Forest","slug":"anjajavy-forest","category":"Forest","country":"Madagascar","region":null,"city":null,"latitude":-15.03444,"longitude":47.22444,"description":"The Anjajavy's Protected Area is located on a peninsula of the town of Antonibe, in the district of Analalava and in the north-west region of Madagascar. It is part of the Sofia region of the independent province of Mahajanga and its position is between 47°13’ at 44°22’ of longitude east and 14°58 at 15°07’ of latitude south.."},{"name":"Upper Orashi Forest Reserve","slug":"upper-orashi-forest-reserve","category":"Forest","country":"Nigeria","region":null,"city":null,"latitude":4.89,"longitude":6.51,"description":"Upper Urashi Forest Reserve is a nature reserve in Rivers State, Nigeria located along the upper reaches of the Urashi River, near the village of Ikodi in Ahoada West. The reserve covers an area of 25,165 ha. It was designated a wetland of international importance under the Ramsar Convention on 30 April 2008."},{"name":"Toro-Semliki Wildlife Reserve","slug":"toro-semliki-wildlife-reserve","category":"Forest","country":"Uganda","region":"Kabarole District","city":null,"latitude":0.89722,"longitude":30.36333,"description":"Semliki Wildlife Reserve is a protected area in the Western Region of Uganda with headquarters at Karugutu in Ntoroko District. It was established as a game park in 1926 and was among the earliest protected areas to be gazetted in the country."},{"name":"Chikangawa Forest Reserve","slug":"chikangawa-forest-reserve","category":"Forest","country":"Malawi","region":"Northern Region","city":null,"latitude":-11.81,"longitude":33.85,"description":"Chikangawa Forest Reserve is a protected area in Chikangawa, Northern Malawi. It was established in 1948 and covers 1147.8 square kilometers. The forest is mainly composed of exotic pine trees. It is home to the Viphya Plantation, which was established in 1964 in a failed attempt to grow construction timber. The forest reserve is home to several native evergreen montane forests."},{"name":"Mabira Forest","slug":"mabira-forest","category":"Forest","country":"Uganda","region":"Buikwe District","city":null,"latitude":0.39833,"longitude":33.0164,"description":"The Mabira Forest is a rainforest area covering about 300 square kilometres (120 mi2) in Uganda, located in Buikwe District, between Lugazi and Jinja. It has been protected as Mabira Forest Reserve since 1932. It is home for many endangered species like the primate Lophocebus ugandae."},{"name":"Atewa Range","slug":"atewa-range","category":"Forest","country":"Ghana","region":null,"city":null,"latitude":6.16667,"longitude":-0.6,"description":"The Atewa Range Forest Reserve is in the Akyem Abuakwa region of southeastern Ghana, near the town of Kibi, and south-west of the Kwahu Plateau which forms the south-west boundary of Lake Volta. The range runs roughly north–south, consisting of steep-sided hills with fairly flat summits. It is the last remains of the Cenozoic peneplain that once covered southern Ghana, and contains ancient bauxitic soils."},{"name":"Shai Hills Resource Reserve","slug":"shai-hills-resource-reserve","category":"Forest","country":"Ghana","region":"Shai Osudoku District","city":null,"latitude":5.90941,"longitude":0.06535,"description":"Shai Hills Resource Reserve is a resource reserve located in Doryumu in the Shai Osudoku District all in the Greater Accra Region of southern Ghana. It lies along the Tema-Akosombo Highway some 57 km from Accra."},{"name":"Jerada","slug":"jerada","category":"Forest","country":"Morocco","region":"Jerada Province","city":null,"latitude":34.31,"longitude":-2.16,"description":"Jerada is a city in the Oriental region of northeastern Morocco. It is located close to the border with Algeria."},{"name":"Amani Nature Reserve","slug":"amani-nature-reserve","category":"Forest","country":"Tanzania","region":"Tanga Region","city":null,"latitude":-5.08333,"longitude":38.66667,"description":"The Amani Forest Reserve, officially listed as Amani Nature Forest Reserve is a forest reserve of Tanzania located the Muheza and Korogwe Districts in the Tanga Region of Tanzania. The nature reserve was established in 1997 in order to preserve the unique flora and fauna of the East Usambara Mountains. The East and West Usambara Mountains are a biodiversity hotspot."},{"name":"Ayum Forest Reserve","slug":"ayum-forest-reserve","category":"Forest","country":"Ghana","region":"Ahafo Region","city":null,"latitude":6.76028,"longitude":-2.69111,"description":"The Ayum Forest Reserve is found in the Asunafo South District in the Ahafo Region of Ghana. It was established in 1940. This site is 112 km2."},{"name":"Bonsam Bepo Forest Reserve","slug":"bonsam-bepo-forest-reserve","category":"Forest","country":"Ghana","region":"Ahafo Region","city":null,"latitude":6.66667,"longitude":-2.61667,"description":"The Bonsam Bepo Forest Reserve is located at Ahantamo near Akrodie in the Ahafo Region of Ghana. It was established in 1934, and covers 124.00 km2 (47.88 sq mi)."},{"name":"Pian Upe Wildlife Reserve","slug":"pian-upe-wildlife-reserve","category":"Forest","country":"Uganda","region":"Karamoja","city":null,"latitude":1.85,"longitude":34.28333,"description":"The Pian Upe Wildlife Reserve is a conservation area in the Karamoja subregion of northeastern Uganda. It is the second largest conservation protected area in Uganda."},{"name":"Dhlinza Forest, KwaZulu-Natal","slug":"dhlinza-forest-kwazulu-natal","category":"Forest","country":"South Africa","region":"KwaZulu-Natal","city":null,"latitude":-28.90525,"longitude":31.44476,"description":"The Dlinza Forest is a subtropical forest or Coastal Scarp Forest in Eshowe, Zululand, South Africa, one of five natural forests running in a 100 km line running northwest from the coast. Others are the Ongoye, Entumeni, Nkandla and Qudeni Forests. They are the most important forests in southern Africa from the aspect of unique biodiversity."},{"name":"Bwindi Impenetrable Forest","slug":"bwindi-impenetrable-forest","category":"Forest","country":"Uganda","region":"Western Region","city":null,"latitude":-1.052,"longitude":29.62,"description":"The Bwindi Impenetrable Forest is a large primeval forest located in south-western Uganda and is located in three districts of Kisoro, Kabale and Kanungu. The Bwindi forest is on the edge of the Albertine Rift, the western branch of the East African Rift, at elevations ranging from 1,160 to 2,607 metres. The forest contains around 160 species of trees and over 100 species of ferns."},{"name":"El Ma’moura","slug":"el-mamoura","category":"Forest","country":"Morocco","region":null,"city":null,"latitude":34.1,"longitude":-6.6,"description":"Al-Mamoura Forest in Morocco is the largest Quercus suber forest in the world, with an area of 130,000 hectares. It is situated on the Atlantic coast between the cities of Rabat and Kenitra and is primarily composed of four tree species: Quercus suber, eucalyptus, pinales, and acacias. The forest is home to a diverse array of plant species and serves as a vital habitat for numerous animal species."},{"name":"Karkloof Forest","slug":"karkloof-forest","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-29.29833,"longitude":30.23222,"description":"The Karkloof Forest is situated in the Karkloof Nature Reserve, 22 km north of Howick, KwaZulu-Natal, South Africa."},{"name":"Ngezi Forest Reserve","slug":"ngezi-forest-reserve","category":"Forest","country":"Tanzania","region":null,"city":null,"latitude":-4.91667,"longitude":39.7,"description":"The Ngezi Forest Reserve is a forest reserve located in the Micheweni District of the North Pemba Region on Pemba Island, Tanzania. It covers an area of 1,440 hectares, mostly comprising primary forest. The reserve was established in 1959."},{"name":"Viphya Forest","slug":"viphya-forest","category":"Forest","country":"Malawi","region":null,"city":null,"latitude":-13.06472,"longitude":34.19111,"description":"The Viphya Mountains, also known as the Viphya Plateau or Viphya Highlands, are a mountain range in located in Chikangawa in Malawi's Northern Region."},{"name":"Sambisa Forest","slug":"sambisa-forest","category":"Forest","country":"Nigeria","region":"Borno State","city":null,"latitude":11.53333,"longitude":13.33333,"description":"The Sambisa Forest is a forest in Borno State, northeast Nigeria. It is in the southwestern part of Chad Basin National Park, about 60 km southeast of Maiduguri, the capital of Borno State. It has an area of 518 km2."},{"name":"Hawaan Forest","slug":"hawaan-forest","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-29.70778,"longitude":31.0925,"description":"The Hawaan Forest is situated in Umhlanga, KwaZulu-Natal, South Africa. It is a large remnant of a climax dry coastal dune forest and the last of its kind. This forest grows on a dune that dates back 18,000 years. The Hawaan forest is currently under the guardianship of the Wildlife and Environment Society of Southern Africa (WESSA), but is owned by the Tongaat Hulett Group."},{"name":"Ongoye Forest","slug":"ongoye-forest","category":"Forest","country":"South Africa","region":null,"city":null,"latitude":-28.84667,"longitude":31.73222,"description":"oNgoye Forest, also known as Ngoye or Ngoya Forest, is an ancient coastal scarp forest, protected by the oNgoye Forest Reserve in South Africa's KwaZulu-Natal province. The forest of almost 4,000 ha covers an extensive granite ridge that rises from 200 to 460 metres above sea level."},{"name":"Cameroonian Highlands forests","slug":"cameroonian-highlands-forests","category":"Forest","country":"Cameroon","region":null,"city":null,"latitude":6.0,"longitude":11.0,"description":"The Cameroonian Highlands forests, also known as the Cameroon Highlands forests, is a montane tropical moist broadleaf forest ecoregion located on the range of mountains that runs inland from the Gulf of Guinea and forms the border between Cameroon and Nigeria. This is an area of forest and grassland which has become more populous as land is cleared for agriculture."},{"name":"Mediterranean woodlands and forests","slug":"mediterranean-woodlands-and-forests","category":"Forest","country":"Algeria","region":null,"city":null,"latitude":36.33333,"longitude":2.0,"description":"The Mediterranean woodlands and forests is an ecoregion in the coastal plains, hills, and mountains bordering the Mediterranean Sea and Atlantic Ocean in North Africa. It has a Mediterranean climate, and is in the Mediterranean forests, woodlands, and scrub biome."}]$tl$::jsonb) as x(
           name text, slug text, category text, country text, region text, city text,
           latitude double precision, longitude double precision, description text)
   where not exists (select 1 from public.places p where p.slug = x.slug);

  get diagnostics added = row_count;
  raise notice 'TerraLens batch 6: % places added', added;
end $$;

